window.__D("text/sefer-hachakira/c001",{"p":[[3000730266,"כמארז\"ל ספ\"ק דיבמות ע\"פ נער הייתי גם זקנתי שרו של עולם אמרו כו'. וכיון שכן איך יהי' זה מושג בעין השכל, אבל הזמן שהוא מענינים השייכים תחת השכל, וכ\"ש ענין האנשים שיהיו במספר או בלי מספר לכן מה שהשכל גוזר עליהן זהו נקרא מופת ובירור.\nה <b>ולבאר</b> הבדל זה יותר נאמר עד\"מ אילו יאמרו לך שיש לפנינו שני דברים ושניהם קשים לקבל בשכל, ואעפ\"כ מוכרח שאחד משניהם אמת, והשני שקר. ואיזו דבר משניהם אמת, אינו ידוע ברור, רק אתה המעיין תברור לך מה שמתקבל אצלך איזו דבר ראוי לדחות ואיזו ראוי לקבל, אזי ודאי הענין שהוא קשה יותר להתקבל בשכל הוא שראוי לדחותו משנדחה הענין שאינו קשה לקבל כל כך, וזה פשוט. ושוב אחר זמן רב ראיתי שכתב כן הגאון רב סעדיה בהקדמתו לספר האמונות והדעות וז\"ל וכשיאמר אומר האמנתי בכך הקשה על המוחש, והיתה האמונה ההיא מפסדת מוחש אחר נדון בגבול שבשני המוחשים כו' וכאשר נפגשים בהבאת הראויה כמו אלה השנים הגדול שבהן יותר ראוי לראיה עכ\"ל. וכל שכן אם הענין הקשה יותר, נראה ג\"כ בחוש הראייה ממש שאינו כן בבירור, והענין שאינו קשה כל כך אין שייך לדון עליו מחוש הראייה, ואין עליו סתירה מחוש הראייה, שבודאי נדחה הענין הקשה ביותר מה שחוש הראייה רואה שאינו כן. אע\"פ שזה מביא ג\"כ לקיים עלינו ענין הקשה כיון שאינו קשה כל כך, וגם אין עליו סתירה מחוש הראייה, משום דמה שהעיניים רואות בדבר שחוש הראייה משיגו בטוב זהו ודאי א\"א לדחות עד\"מ על העמוד של אבן אי אפשר לומר בשום אופן שזהו של זהב, וכן כיוצא בזה על שני מטבעות אי אפשר לומר בשום אופן שהם שלשה עשרה מטבעות, ולכן כשזה מכריחנו לקיים דבר הקשה שאין עליו סתירה כזה ואין הענין שולטת בו, מוכרחים אנו בעל כרחינו להודות עליו. כשאם לא כן תוכרח לומר על שני מטבעות שהם שלשה עשר, או על העמוד של אבן שהוא של זהב כנ\"ל. והרי כמו כן ממש הוא אילו יאמרו לך האמן שיש בחינה בלתי בעל תכלית שאינו בגדר זמן כלל, ועבר והוה ועתיד הם בהשוואה אחת. ושאם ח\"ו לא תקבל זה אזי תוכרח להאמין שיש בשנה אחת לא שס\"ה ימים לבד כי אם שמניסן עד ניסן יש ששה מאות אלפים ימים עד\"מ. ואי אפשר להמלט מלהאמין ולקבל אחד משני דברים אלו. ולכן עם היות שזה שנצייר בחינה שאינו בגדר זמן הוא דבר הקשה על השכל לקבלו ר\"ל שכחו גדול כמשך זמן בלתי בעל תכלית ועכ\"ז אינו בגדר זמן כלל ולא דמות זמן, הרי אין השכל משיג כלל ציור בחי' זו. ועכ\"ז מוכרחים אנו בעל כרחנו להודות ולהאמין בזה באמונה קבועה ומוחלטת כיון שאם לא תאמין בזה ח\"ו תפול בהאמנת דבר הקשה ביותר לאין שיעור והוא מה שאנו כולנו רואים בחוש שהוא שקר גמור והוא שנאמר שיש בשנה אחת ששה מאות אלף יום, שזה כאילו תאמר על שס\"ה מטבעות, שאינן שס\"ה כ\"א ת\"ר אלף. וכיון שזה אי אפשר לקבל בשום פנים בעולם על כרחך צריכים אנו להודות ולהאמין ענין מציאות למעלה מהזמן. כך הוא ודאי אם הענין כן שבעל כרחך אחד משני הדברים הנ\"ל אמת אם שיש מציאות למעלה מהזמן, או שמניסן עד ניסן יש ת\"ר אלף ימים ודאי היה נתברר אצלינו בבירור גמור שיש בחינה שלמעלה מהזמן מאחר שעל זה אין שום ספק שמניסן עד ניסן אין ת\"ר אלף ימים כ\"א שס\"ה ימים לבד<sup data-n=\"108\">*</sup>.\n<b>ועתה</b> צריכים אנו להבין איך הוא בהנמשל שבעל כרחך א\"א להמלט מלהאמין באחד משני הדברים הנ\"ל. והענין הוא כי מבואר לעיל שמכאן ר\"ל מן עתה עד סוף כל הדורות אי אפשר בשום אופן שיצא אל הפועל שיעברו ימים בלי גבול.",[["108","*","<b>ימים לבד</b>: בבוך 1095 רוב העמוד פנוי."]]],[3000730274,"כמש\"ל אות ב' בשם ספר נוה שלום וע\"ש דכיון שאתה אוחז שתי הקצוות ראש וסוף היינו מן העתה דעכשיו, עד סוף כל הדורות שאז הוא ג\"כ בחינת עתה. א\"כ אי אפשר שבינתיים יהי' שיעור בלי גבול כו' יעו\"ש באריכות. וזהו נמנע יותר ממה שנאמר שיש בשנה אחת ששים רבוא ימים דהתם השקר הוא משס\"ה לששים רבוא. וכאן השקר הוא מן בעל גבול על בלתי בעל גבול שהוא דבר שאין ערוך ביניהם כלל. ושקר זה שוה כמעט לאילו תאמר שיש בשנה אחת ימים בלי גבול. ועכ\"פ ודאי לא פחות הוא מהשקר הנ\"ל כאילו תאמר שיש בשנה אחת ששים רבוא ימים. וא\"כ כך ממש הוכרחנו להאמין חידוש העולם עם היותו דבר הקשה. שהרי אם תמאן מלקבל זה ותחזיק בשקר של אנשי הקדמות, א\"כ תוכרח לומר שעברו דורות זה אחר זה בלי גבול, שאם יש גבול למספר הדורות לפניך א\"כ העולם מחודש. וא\"א לקיים שקר הנ\"ל כ\"א שתאמר שאין גבול כלל למספר הדורות לפניך. והנה כל דור הוא עכ\"פ ערך עשרים שנה לפחות או שלשים שנה, א\"כ במשך זה שקדם לפנינו עד עתה את\"ל שהשקר שעברו דורות בלי גבול א\"כ בהכרח שעברו שנים יותר מבלי גבול היינו עשרים פעמים בלי גבול לפחות. וא\"כ עברו ימים שבעה אלפים פעמים בלי גבול, והיינו שעבר תחלה פעם א' ימים בלי גבול ואח\"כ עוד פעם שני ימים בלי גבול כו' עד שעברו ימים שבעה אלפים פעמים בלי גבול זה אחר סור זה. מאחר שבמשך דור אחד עוברים ימים שבעה אלפים זה אחר זה כי בעשרים שנה יש שבעה אלפים ימים ויותר. וא\"כ במשך הזמן שעברו דורות זה אחר זה בלי גבול בהכרח שעברו ג\"כ ימים זה אחר זה שבעה אלפים פעמים בלי גבול. וא\"כ תפוש דור אחד מזקניך שבאמצע דורות הנ\"ל ותאמר שממנו עד עתה עברו ימים פעם א' בלי גבול עכ\"פ. והרי זה ממש כמו שתאמר שמעתה דהיינו מעכשיו עד העתיד יעברו ימים פ\"א בלי גבול עכ\"פ. דאין לחלק בין עתה דעכשיו לעתה העבר כגון אחר שעברו ימים ששה אלפים פעמים בלי גבול עד\"מ, תפוס הזמן ההוא במקום עתה דעכשיו, שכבר יש לו עבר ששה אלפים פעמים בלי גבול ימים. וא\"כ הוא עתה. וכשתאמר שממנו עד עתה דעכשיו עברו ימים בלי גבול ה\"ז שקר ונמנע כמו מעתה דעכשיו עד העתיד שיעבור בלי גבול ימים, ואדרבה הוא נמנע עצום יותר שלא די לך בפעם א' בלי גבול, כ\"א אלף פעמים בלי גבול זה אחר זה. וכבר נתבאר שזה שתאמר כן הוא ממש כמו שתאמר שבשנה אחת מניסן עד ניסן יש ימים בלי גבול או עכ\"פ ששים רבוא ימים, וא\"כ יצא לנו הענין הנ\"ל שאי אפשר להמלט מלהאמין באחד משני דברים אלו היינו להאמין האמת שהעולם מחודש והדורות היו בגבול מאדם הראשון יציר כפיו של הקב\"ה עד מתן תורה ך\"ו דורות כו', שאם לא כן תוכרח להאמין דבר הנראה בחוש שהוא שקר, היינו כי זה שנאמר שהיו דורות בלי גבול זהו שקר הנראה בחוש שאינו כן, כמו שנראה כשיש לפניך שס\"ה מטבעות שמן השקר הוא שנאמר שהן ששים רבוא מטבעות או בלי גבול כו', דכך ממש הוא מןה שקר שמבחי' הזמן שהיה בבחי' עתה עד עתה יעברו ימים בלי גבול, דכך לי מן עתה עד עתה כמו מניסן עד ניסן, וכ\"ש שתצטרך לומר שעברו כן שבעת אלפים פעמים זה אחר זה. וכיון ששקר זה אי אפשר לקבל בשום אופן, אז מן ההכרח להודות בחידוש העולם דהא אין להמלט מן השקר הנ\"ל אא\"כ תאמר שלא עברו דורות בלתי גבול כי אם בגבול ומספר, ואם כן העולם מחודש, וכל שכן שיהיה השקר הנ\"ל נראה יותר בחוש איך שהוא שקר עפמש\"ל אות ב' בענין מספר האנשים דהנה מראובן דעכשיו עד סוף כל הדורות אי אפשר שיהי' מספר האנשים פרטיים מדברים וגם בעלי חיים מה שיצאו אל הפועל רק מספר וגבול ואי"],[3000730281,"אפשר בשום אופן שיצטרכפו להיות בלי גבול. וזה שתאמר שיהיו בלי גבול הוא שקר כמו שתאמר שבשנה אחת מניסן עד ניסן יש ששים רבוא ימים וכנ\"ל. ואם כן אם ח\"ו תקבל השקר של אנשי הקדמות שהיו דורות לפנינו בלי גבול א\"כ תוכרח לומר שהי' בין ראובן זקניך עד עכשיו עברו אנשים ובע\"ח בלי גבול וכך עברו אלף מילייאן פעמים בלי גבול זה אחר זה מראובן לראובן עד\"מ כו' ע\"ש. וה\"ז כמו שתכפול השקר הנ\"ל ממציאות ס\"ר ימים מניסן עד ניסן, אלף מילייאן פעמים, לומר שהיו כל כך שנים שהן כשנים שלפנינו ובכל שנה לא שס\"ה ימים כ\"א ס\"ר ימים, מה שכל עין תשורנו שזהו שקר וא\"א לקבלו אפילו על שנה א' כ\"ש לכפול השקר כל כך פעמים ח\"ו וא\"כ כדי להמלט מהשקרים הנ\"ל אי אפשר אא\"כ נודה על האמת שלא עברו דורות בלי גבול רק במספר, וא\"כ העולם מחודש. וכמו כן<sup data-n=\"109\">*</sup> יש לבאר מופת זה על הזמן מחודש והוא עפמש\"ל אות ג' איך שמראובן דעכשיו עד סוף כל הדורות אי אפשר בשום אופן שיעברו ויצאו אל הפועל רגעים (כל רגע תתרף בשעה) רק במספר וגבול, ושתאמר שיעברו ויצאו אל הפועל בלי גבול מעתה דעכשיו עד עתה שבסוף כל הדורות כו' זהו ממש נראה בחוש שהוא נמנע כמו שנמנע שיהי' מניסן עד ניסן הסמוך לו ס\"ר ימים או אילו ימים בלי גבול, כנ\"ל וכיון שזה נראה בחוש שאי אפשר, הרי כמו כן אזמן החולף ועבר הרי אם תאמר שהיו דורות בלי גבול א\"כ עברו רגעים במשך הנ\"ל שני מאות ול\"ז פעמים מילייאן בלי גבול זה אחר סור זה. וגם נוכל להעלות החשבון יותר שכשנאמר שהיה הזמן החולף בלי גבול הרי תוכרח לומר שהיה יובלות בלי גבול, וכן כל חשבון גדול שתתפוס כמו מחזור החמה וכה\"ג וא\"כ בע\"כ עברו רגעים חשבון גדול יותר בלי גבול, וכן אם תחלק הרגע עצמו לכמה חלקים והנה בזמן העתיד א\"א שיעברו אפילו חלקי הרגע רק במספר וגבול, ואיך בזמן החולף עברו חלקי הרגע מילייאן פעמים מילייאן, בלי גבול עד\"מ או יותר פעמים בלי גבול. ואי אפשר להמלט מן השקרים האלו הנראים בחוש שהם נמנע גמור, אא\"כ נודה ונקבל שהזמן נברא ומחודש. ואם תאמר הרי הקב\"ה הוא ושנותיו לא יתמו גם קודם שנברא העולם הרי זהו מבוקשינו להכריח ששנותיו של הקב\"ה (עד\"מ מה שאנו קוראים לשון שנותיו לשכך את האוזן במה שהיא יכולה לשמוע) אינן בגדר זמן כלל כ\"א למעלה מבחי' הזמן ועבר והוה ועתיד שוין, ועם היות שבאמת הוא דבר הקשה על השכל להבינו אעפ\"כ מוכרח השכל לקבלו בטוב ויפה כיון שאם לא כן תוכרח לומר על שלשה מטבעות המונחים לפניך שהן שלשה עשר מאות עד\"מ או על שלשה ימים שהן שלשה עשר מאות ימים ממש, מה שזה ודאי שקר, כמו השקר שהחלק הוא גדול כמו הכל. ועיין בתשובת הרשב\"א סי' תי\"ח בענין דעת הפילוספים האומרים שיש לנמנע טבע קיים כאמרנו בראובן שהוא רוכב ובלתי רוכב יחד בנקודה אחת נרמזת מהזמן או כותב ולא כותב יחד כו' או כאמרנו בהמצאת זמן עבר ועתיד יחד כו' ואיך ימצא יום שיקרא אתמול ומחר\nנוסח א\nיחד כו'<sup data-n=\"110\">*</sup> ע\"ש. והרשב\"א לא ס\"ל כן שלגבי הקב\"ה אין שום נמנע. אכן ענין השקר הנ\"ל שיהיה שנה כמו שהיא עכשיו ממש ושנאמר שיש בה ששים רבוא ימים זהו הכל מודים שהוא שוא ושקר, וענין שיש לנמנע טבע קיים אינו ערוך כלל לענין זה, דהא הוא שוא",[["109","*","<b>וכמו כן</b>: בבוך 1155 מסומן כאן סעיף ו. יחד כו': בוך 2321 בגוכתי\"ק."],["110","*","<b>יחד</b>: בכת\"י הנוסחא ”יחד. . אבל שאר\"."]]],[3000730288,"ושקר. משא\"כ ענין לנמנע טבע קיים יש חולקי' ע\"ז שהקב\"ה שהוא אדון הנפלאות לא יבצר ממנו לעשות נס ופלא גם בענין שהוא נראה נמנע אצלינו."],[3000730295,"יחד כו'<sup data-n=\"111\">*</sup> ע\"ש אבל שאר הנמנעות אין נמנעות אצלו ית' וכמו שברא העולם מאין ליש שהוא פלא היותר גדול כו'. ותוכן הטעם בזה ההבדל בין שני מיני נמנעות אלה, הוא כי זה החלק השני שהם קוראים יש לנמנע טבע קיים, זהו הנמנע מצד הנברא, שאין",[["111","*","<b>יחד כו'</b>: קטע זה בבוך 1095."]]],[3000730301,"יתכן שראובן יהיה רוכב ולא רוכב. נמצא אין המניעה מצד הבורא ית' כ\"א מצד הנברא. וכמ\"ש רס\"ג שא\"א שיכניס חלל העולם בנקב הטבעת, מבלי שירחיב זה או יקצר זה. א\"כ הגם שלדברי הכל יש בעולם מציאות בלתי בעל גבול. אך זה שהבלתי בעל גבול יהי' בבחי' זמן, ושיעבור זמן ממש בלי גבול כמה פעמים, וכש\"כ דורות אנשים בלי גבול, זה מן הנמנע השני שיש לנמנע טבע קיים, כמו שיכניס חלל העולם בנקב הטבעת. כמ\"כ שיכניס ענין בלי גבול, בדבר שאנו רואין שהוא מוגבל משני קצותיו. משא\"כ כשאנו אומרים שדורות האנשים הי' בגבול, ורק הש\"י לבדו הוא הקדמון, וענין המשך בלתי בעל גבול אינו בבחי' זמן שלנו המוגבל, כ\"א למעלה מהזמן, זהו רק נמנע מאתנו, ולא שייך ע\"ז לנמנע טבע קיים, כיון שהוא בדבר שאין לנו השגה בו, כמו החרש אינו מבין שמע הקולות, והסריס תאות המשגל, מכ\"ש שהגשמי המוגבל איך ישיג ענין הבלתי בעל גבול, ואיך הנברא ישיג את הבורא. אבל זה שנלביש ענין בלתי בעל גבול, בנו בעלי הגבול לומר שהדורות היו בלי גבול זהו ענין יש לנמנע טבע קיים. והנה אף לפ\"ד הרשב\"א שאין לנמנע טבע קיים היינו אצלו ית' שהוא אדון הנפלאות, אבל שנלביש כח זה על העולם הגשמי הבעל גבול זה ודאי אינו. אשר לכן על דורות האנשים יש לתפוס בודאי שהיו בגבול לבד ולא ליתן להם הענין הבלתי גבול שלגבי האנשים ודאי יש לנמנע זה טבע קיים לכל הדיעות.\nו<sup data-n=\"112\">*</sup> <b>והנה</b> כמ\"כ נאמר בענין המקום שמלבד המופתים שהביאו החוקרים שא\"א שיהי' בלי גבול, עוד זאת ע\"ד הנ\"ל דאם תאמר שיש גבול כמה פרסאות הוא א\"כ הוא בעל גבול ואת\"ל שיש פרסאות בלי גבול אזי בהכרח יש מילין ד' פעמים בלי גבול ובכל מיל שני אלפים אמה שהם י\"ב אלפים טפחים שהם מ\"ח אלפים אגודלין א\"כ יש קצ\"ב אלף פעמים בלי גבול אגודלין. וא\"כ כשתמדוד מעמידתך שהוא באמצע הארץ עד\"מ יש צ\"ו אלפים פעמים בלי גבול אגודלין מקום לכל צד, א\"כ בהכרח שכל בלי גבול אגודלין יש לו ב' קצוות קצה מכל צד הצד הא' בעמידתך באמצע הארץ והצד השני אצל התחלת בלי גבול הב' הסמוך לו כו', וכן בבלי גבול השני יש עד\"ז שני קצוות כו'. והדבר הזה מבואר ביטולו ושקרו שכל מי שיש בו קצה מכאן וקצה מכאן בהכרח שהוא בעל גבול, וזה מושכל ראשון, כי איך הוא בלי גבול, הרי יש לו גבול מכל צד, והיינו שיש לו ראשית והתחלה וגם קץ וסוף א\"כ הוא בעל גבול, וכמ\"ש הגאון רב סעדיה בספר האמונות מאמר א' פרק א' ומצאתי הכתוב שהעיד עליהם בתכלית באמרו ולמקצה השמים ועד קצה השמים עכ\"ל, הרי שזה שנאמר למקצה כו' ועד קצה כו' הוא עדות שהשמים הם בגבול ותכלית, כי כל מה שיש לו קצה ותחלה הרי זהו בעל גבול וכיון שזה שתאמר שהמקום בלי גבול אי אפשר אא\"כ תאמר שהבלי גבול הזה יש לו שני קצוות קצה אחד מזה ששם הוא התחלתו וקצה אחד מזה ששם הוא מסתיים וביניהם יש בלי גבול, וזה דבר שוא ושקר א\"כ מוכרח שהמקום הוא בעל גבול. והנה המופת שנתבאר לעיל על הזמן העתיד שאי אפשר שיעבור מהעתה יהיה העתה באיזה זמן שיהי', אי אפשר שיצא לבלי גבול, הוא מעיד ג\"כ על המקום. דהא אנו רואים שהענין הוא איך מן עתה עד עתה שבעתיד שהוא קצה מזה וקצה מזה אי אפשר שביניהם יהיה בלי גבול, וכך הוא ג\"כ בענין המקום. הגם שיש לחלק לכאורה דאילו הזמן העתיד היינו",[["112","*","<b>ו</b>: בבוך 1155: ז."]]],[3000730306,"מעתה עד העתיד אנו באים לקבצו מחלקי הזמן שהם גבוליים רגעים ומינוטין ושעות וימים כו' לומר שמצטרפין לחשבון גדול הוא בלי גבול. וזהו שנתבאר שאי אפשר, יען כי אף שמתרבים הימים ובאים בחשבון גדול רבוא רבבות כו' הנה עם הרבוי העצום הזה לא פגעו ולא נגעו כלל להתקרב לגבי ענין הבלי גבול, יותר מהיום הראשון שמהעתה. כי לגבי בלי גבול שוה אלף אלפים עם אחד ממש, ע\"כ ע\"י צירוף ורבוי החלקיים גבוליים לא יתהווה ויעבור בשום אופן לבלי גבול כ\"א לחשבון גדול שבגבול. אבל המקום כבר היה ונברא בבת אחת. א\"כ י\"ל שהוא בלי גבול חלקים גבוליים. אכן באמת שניהם ענין אחד ממש, דאע\"פ שכבר היה ונמצא, עכ\"ז זה שתאמר שהוא בלי גבול הענין שחלקים גבוליים נתקבצו יחד ברבוי עצום כל כך עד שנעשו בלי גבול, וזה אי אפשר כיון שכל רבוי החלקים גבוליים אינו פוגע ונוגע כלל להתקרב לענין בלי גבול. א\"כ איך ע\"י ריבויים יתהווה בלי גבול, אא\"כ תאמר שהבלי גבול הוא בלעדם ולא מהם וזה ג\"כ שקר, דא\"כ אינו מקום. א\"כ יצא לנו שי\"ל שגם המופת הנראה בחוש שמעתה עד העתיד א\"כ שיעבור זמן בלי גבול שנת' לעיל שהוא כמו שתאמר על שלשה שהן י\"ג מאות עד\"מ כו' או אפילו בלי גבול. כמו כן מופת זה שייך שא\"א לומר שיש פרסאות בלי גבול וטפחים מ\"ח אלף פעמים בלי גבול כו' כי אי אפשר שחלקים גבוליים יצטרף מהם לבלי גבול. ועוד שכל מי שיש לו קצה מזה וקצה מזה היינו תחלה ותכלה הוא בעל גבול.<sup data-n=\"113\">*</sup>\nח<sup data-n=\"114\">*</sup> <b>דרך</b> וראיה שלישית. הנה תחלה יש להקדים מ\"ש הרמב\"ם במ\"נ ח\"א ספע\"ג סד\"ה ההקדמה האחת עשרה, כאלו אמרת ראובן בן יעקב ויעקב בן יצחק ויצחק בן אברהם אל לא תכלה. זה גם כן אצלם שקר כו' קצתם ישתדל לאמתו רצונם לומר לבאר המנעו בדרך אבארהו לך בזה המאמר וקצתם אומר שמזה מושכל בעצמו וידוע בתחלת מחשבה ואין צריך עליו מופת, ואם היה מן השקר כו' הנה יהיה שקר קדמות העולם מתחלת מחשבה ולא יצטרך אל הקדמה אחרת כלל כו', וכ\"כ עוד בסוף ההקדמה לחלק שני וכח דבריהם שהוא אצלם מושכל ראשון כו'. והנה מ\"ש לבאר המנעו בדרך אבארהו לך בזה המאמר הוא מה שביאר שם ח\"א ס\"פ ע\"ד כי כל איש מהמין הוא כו' ויחייבו במחשבה בזאת הבחינה שיהיה מה שאין תכלית יותר ממה שאין תכלית כו' וע\"ז כתב שם וכבר הכה אבונצר כו', ור\"ל שהשיג על ראיות אלו לומר שאינן מוכרחות. אבל על מ\"ש ס\"פ ע\"ג שקצתם אומר שזה מושכל בעצמו, לא ביאר כלל סתירה ע\"ז ס\"פ ע\"ד ודלא כמשמעות הרש\"ט פע\"ג שם. ולענ\"ד יש לבאר איך שאמת הוא שזה מושכל בעצמו מבלי הראיות שהביא ס\"פ ע\"ד דא\"כ ימצא בבע\"ת גדול מבלתי בעל תכלית. וכמו שהביא ראיה זו בח\"ה שער היחוד פ\"ה יהיה דבר שאין לו תכלית גדול מדבר שאין לו תכלית וזה אי אפשר דאע\"פ שהיא ראיה טובה עכ\"ז נניח זה ונאמר שלא בא מופת על המנעו בבא זה אחר סור זה כו' וכמו בזמן לדברי האומרים שאינו מחודש מה שגם זה אינו אמת. אך עכ\"ז אף לשיטתם עכ\"ז מושכל ראשון שהאנשים שהיו בזמן החולף הם כולם מחודשים, ור\"ל שאי אפשר שילך תולדותם ומספר הדורות לפנינו אל לא תכלה. דלא דמי אנשים לרגעי הזמן מכמה טעמים. האחד שהאנשים הם יש להם גשם שהרי גופו הוא מד' יסודות ורובו יסוד מעפר. א\"כ גם האנשים שחלפו ומתו יכולני לצייר כאלו הם קיימים עתה באיש, הן חיים, הן מתים, הן אפילו ששבו לעפר ממש, כמ\"ש ואל עפר תשוב. עכ\"פ הנה אם היו כל האנשים שחלפו עתה לפנינו ואפילו רק אחד מכל דור, ואפילו רק מקצת",[["113","*","<b>פ\"ז</b>: ראה בהוספות [לקמן קכא, א]."],["114","*","<b>ח</b>: ראה לקמן קכא, א, ובהערת כ\"ק אדמו\"ר זי\"ע שם בשולי העומד. וראה גם לקמן נד, א קטע: תחת פרק ח ופרק ט."]]],[3000730310,"עפר גופו של כל איש א' מכל דור ודור שהיה לפנינו, הוא נמצא בפני עצמו, ונשאל ונתבונן עליהם במחשבתינו, אם הם כולם מחודשים אחר ההעדר או שיש מהם דור שהוא קדמון ולא מחודש, אזי ודאי נפשוט ונאמר שכולם נולדו מחודשים ואין שום אחד מהם שאינו מחודש שהרי בין לפי האמת שנולדו מאדה\"ר שהיה יציר כפיו של הקב\"ה בין לפי השקר של מאמיני הקדמות עכ\"פ פרטי האישים הם מחודשים ונולדו מאב ואם, ואין שום אחד מהם קדמון באיש עכ\"פ. וכיון שהם כולם במציאות עתה או אחד מכל דור, וכולם מחודשים, אזי מושכל ראשון וברור כשמש שכל האנשים היו מחודשים והיה זמן שלא היו אנשים כלל ולא שייך מקום הספק על קדמות ח\"ו רק על דבר שאין לו תולדות ואין אישיו מתחדשים כמו השמים והארץ, שהרי לא נולדו מאב ואם כי אם נבראו בשי\"ב ומאז הם קיימים באיש עליהם יוכל המתעקש לומר שהיו מעולם מה שגם זה שוא ושקר ואין השכל מקבלו כלל. אבל על אנשים הנולדים מאב ואם שהם ודאי מחודשים ואי אפשר לומר על שום איש מהן שהיה מעולם כי ודאי הוא נולד ומחודש. אם כן כשכולם קיימים לפנינו, הרי כולם יחד בצירוף הם כמו ארץ אחת, כי זה נמשך ונולד מזה בזמן עמידת הארץ. אלא שההפרש בינם להארץ הוא שעליהם אין שום ספק שודאי הוא מחודש ולא קדמון, דלא עדיפי כולם יחד מאילו יצוייר ג\"כ איש אחד שישנו מזמן עמידת הארץ עד עכשיו ואח\"כ הוליד ג\"כ תולדות והתולדות תולדות. דעכ\"פ כיון שאי אפשר לומר שהאיש הוא קדמון, שעל זה אין שום ספק אפילו למאמיני הקדמות, וכיון שהוא מחודש והיה בהכרח זמן שלא היה בעולם א\"כ הכל מחודש. וזהו ענין המושכל ראשון, שהוא שקר שילך אל לא תכלה כו':\n<b>(קיצור.</b> אם כל האנשים מכל הדורות שלפנינו היו קיימים באיש אפילו מתים רק שגופם קיים או אפילו אחד מכל דור, והרי כולם מחודשים ואין אחד מהם שיפול ספק שמא גופו קדמון ולא דמי לגוף הארץ. וא\"כ מוכרח שהיה זמן שלא היה מציאת אנשים כלל, ושפיר הוא מושכל ראשון שאי אפשר שילך זה ההשתלשלות אל הקדמות אם כולם קיימים באיש עכ\"פ וכולם מחודשים)\nט <b>וביאור</b> ענין זה איך הם כמו איש אחד פשוט הוא שהרי האב המת מזמן מאה שנה עד\"מ וגופו מונח לפנינו בבה\"ק, הרי הוא כשרש לגבי התולדות שלו שהם ענפים שלו, והוא כולל אותם בענין השנים שהוא בן ק\"ע שנה עד\"מ וישנו, והם ענפים בני ק\"כ שנה או ע' שנה או פחות, הרי הוא האיש אחד כולל אותם, וכל הזמן שלהם מראש עד סוף. ועל דרך זה למעלה יותר באבי אבי האב כו' עד מאה דורות אילו גופו מונח לפנינו וה\"ז כאילו קיים באיש מזה עד עתה זה שלשה אלפים שנה עד\"מ הרי הוא כולל כל הזמן של הענפים הנמשכים ממנו. וא\"כ עד\"ז אם כל הדורות או עכ\"פ אחד מכל דור קיים באיש מעת היותו עד עתה איש אחד מכל דור לא נעדר, הרי כל הדורות האחרונים הם ענפים מאיש שבדור שלפניהם, ואין לדבר רק בו וכיון שהוא גם כן קדמו בודאי ההעדר והיה זמן שלא היה בעולם. א\"כ ממילא שכל מין האנשים קדמם ההעדר.\n<b>(קיצור.</b> ועוד כשכולם קיימים א\"כ הקודם בזמן כולל את שאחריו. וא\"כ מאי נפ\"מ מהרבוי אנשים ודורות כיון שגם היותר קודם לכולם מחודש ואינו קדמון א\"כ ק\"ו שכל הבאים אחריו מחודשים וה\"ז כאילו היה איש אחד או דור אחד והוא מחודש): \nי<sup data-n=\"115\">*</sup> <b>עוד</b> יש לבאר איך אי אפשר שילך זה בלי תכלה וכי בהכרח תגיענו אל האדם",[["115","*","<b>*)ראה לקמן נד, א קטע</b>: תחת פרק יוד."]]],[3000730314,"הראשון אשר בראו ית' בלי חבור זכר ונקבה, נמשיל על מספר הדורות משל משורות אילנות, כי האדם עץ השדה, וכי מכל שורה מתחדש ויוצא משרשי' בריחוק מקום מעט ממנה עוד שורה שהיא כמו ענפים משורה הראשונה, והנה שורה החיצונה המחודשת מקרוב גבוה עשרים וחמשה טפחים עד\"מ דוגמת דור ך\"ה שנה. והשניה שהן האבות גובהן חמשים טפחים, והשורה הפנימי' השלישית שממנה יצאה השורה השנייה גובהה ע\"ה טפחים והרביעית מאה טפחים וכך הולכים שורות אילנות רבים זה למעלה מזה. והנה הגע עצמך אם נתברר שאין שום שורה שתהיה גובהה לבלי גבול אזי בהכרח שכל השורות מוגבלים. שהרי השורה היותר פנימיות שהיא עודפת בגובהה על גובה כל השורות, א\"כ כיון שהיא עצמה בעלת גבול כש\"כ שכולם מוגבלים וזה פשוט. וכמ\"כ הדורות נמשלו לשורות וכל כ\"ה שנה מתחדש דור עד\"מ כמו השורה הנמוכה מהשורה הגבוה אבל הרי הגבוה כולל הנמוכה ע\"ד קרסולי החיות כנגד כולן כו'. ועד\"ז כל הגבוה יותר כולל כולן. וכיון שאין שום גוף שיהי' קדמון באיש, רק על כרחך מחודש, א\"כ כולם מחודשים, ואי אפשר שילך אל הקדמות. ולא דמי לשמים וארץ שיוכל המתעקש לומר שאינן מחודשים אבל אלו הכל מודים שאין שום גוף שיהי' קדמון וכשכל הגופים קיימים וכולם מחודשים א\"כ הכל מחודש, כמו אם אין שום אילן שיהיה גבוה בלי גבול בהכרח הכל בגבול ואין הרבוי מעלה ומוריד כלל. והנה במשל האילנות אמרנו ענין לבלי גבול ובהנמשל בהדורות אמרנו ענין הקדמות, כי זהו מבוקשינו להכריח ענין החדוש, רק עיקר כוונת המשל לדחות סברת המתעקש האומר שע\"י רבוי השתלשלות האישים אף שכל א' וא' מחודש באיש ויש לו גבול, עכ\"ז יהי' עי\"ז המין קדמון, ובלי גבול. ואע\"פ שמצורף רק מאישים מחודשים ובעלי גבול, עכ\"ז אף שהחלקים הם בעלי גבול יהי' הכל בלי גבול. ואף שהחלקים הם מחודשים כולם, עכ\"ז יהי' הכל קדמון ולא מחודש. וסתירת דבר זה נראה בחוש ממשל שורות האילנות, שעם שנאמר שיש בהן רבוי עצום מאוד וזה גבוה מזה גבוה מעל גבוה וגבוהים עליהם עכ\"ז אם מתברר לנו שאין שום שורה אחת שתהיה היא בעצמה לבד בלי גבול, אזי כולם מוגבלים עם הרבוי העצום, ולא מהני כלל ענין מה שיש רבוי שורות במאד זה למעלה מזה, לעשות את הכל בלי גבול. הרי מבואר שכיון שאין שום שורה שתהיה בלי גבול אזי גם הכל מוגבל, וכמו כן נאמר דלא מהני רבוי הדורות המחודשים כל א' וא' באיש ובעלי גבול לשנאמר שמצירופם יהי' המין קדמון, אם ברור שאין שום דור שיהי' קדמון. וזה פשוט אם כולם לפנינו, דאז פשוט שכך לי הדורות כמו השורות, וכך לי הזמן של הדורות כמו הגובה של השורות, וכך לי החידוש לגבי הקדמות כמו הגבול לגבי בלי גבול.\n<b>(קיצור</b>. יש לראות זה גם בעין הרואה ממש, ע\"י ציור שורות אילנות זה גבוה מעל זה שהנמוך יוצא מהגדול וכשאומרים שעכ\"פ אין שום שורה שתהי' היא עצמה גובהה בלי גבול רק בגבול אזי נאמר שהכל מוגבל, כי אז נאמר פשוט שהשורה היותר עליונה המוגבלת כוללת כל מה שתחתיה וגבוה מהן כמו כן האדם עץ השדה דור למעלה מדור וכשברור שאין שום א' קדמון כ\"א מחודש אזי נאמר שהכל מחודש, דממשל הגבול יש ללמוד להחידוש).\nיא <b>ועדיין</b> יש לומר, דהנה כבר נת' לעיל אות ג' ואות ב' שלשטת האומרים שהזמן אינו מחודש צריך לומר שיש בהכרח בלי גבול גדול מבלי גבול היינו כמו שתאמר בלי גבול דורות על כרחך זהו יותר מבלי גבול שנים היינו שלשים פעמים כמוהו, כי כל דור ערך שלשים או כ\"ה שנה. וכן בלי גבול שנה הוא שס\"ה פעמים בלי גבול ימים כו', עד שבלי גבול דורות הוא ערך רל\"ז מילייאן פעמים בלי גבול רגעים לפי החשבון שהדור הוא כ\"ה שנה כו' ע\"ש. וא\"כ ממילא כמו שיש רל\"ז מילייאן פעמים בלי"],[3000730318,"גבול רגעים, כך יש לומר כך אלפים או מילייאן פעמים בלי גבול דורות דמאי שנא, כיון שלפי שטתם מוכרח שיש כמה וכמה כפילות ומספרים בענין הבלי גבול כמו בענין הגבול. ואע\"פ ששם ביארנו שנראה בחוש שאי אפשר לומר כן דהעתיד יוכיח שלא יצא בלי גבול אפילו פעם א' בפועל מהזמן דעתה יהיה איזה עתה שיהיה עד כל העתיד שבפועל כו', כש\"כ שא\"א לצייר כפילות אין מספר בבלי גבול. מ\"מ כאן שאנו באים לבאר ענין המושכל ראשון הנ\"ל שזה שקר ע\"כ צריך לומר שזהו חוץ ולבד מהמופת דלעיל. והיינו אף לשטתם שהזמן י\"ל שאינו מחודש וממילא מוכרח כהנ\"ל. ולכן נאמר דאף לשיטתם שא\"כ יכול לצייר שעברו דורות מחודשים מאב ואם בלי תכלה ועדיין לא פגע ונגע זה אל הקדמות ממש, דהא הקדמות על כרחם למעלה וגדול יותר מענין לא תכלה. כיון בקדמות מוכרח לצייר כפילות רבוי עצום בלי גבול של הזמן כנ\"ל ולא סגי בלאו הכי בשום אופן. א\"כ גם דורות ללא תכלה שלפנינו לא נגע זה אל הקדמות ממש כ\"א גם במחודשים הנולדים מאב ואם יכול להיות שעבר זמן כמספר הדורות בלי גבול. וכיון שכן שמא אין ראיה ממשל השורות אילנות הנ\"ל דהתם היינו שנאמר כשאין שום שורה בלי גבול אזי גם הכל מוגבל. אבל כאן שנאמר שיש דור שעבר עליו זמן בלי גבול מעת היותו עד עתה ויש הרבה דורות כן, רק שנאמר שכולם מחודשים ונולדו מזכר ונקבה ואין בהם קדמון באיש, שמא נאמר שמרבוי צירוף הדורות המחודשים יצטרף להיות המין קדמון ממש כיון גם פרטי האישים יש להם מעלה כ\"כ שהם גבוהים לבלי גבול רק שהם מחודשים. אך באמת אין שום חילוק דכך לי המחודש לגבי הקדמון כמו הגבול לגבי הבלי גבול, כי לשיטתם חזר ערך בלתי גבול המחודש לגבי הקדמון ממש כמו חשבון גבול לגבי בלתי בעל גבול, דריחוק עצום הוא בין הקדמון למחודש שקדמו ההעדר יותר מהריחוק בין הבלתי בעל גבול לבעל גבול, כאשר הדעת נותן שהמחודש לגבי הקדמון אינו ערוך כלל וכלל. משא\"כ חשבון הגבול לגבי בלתי בעל גבול, כיון שלפי שטתם וטעותם יש לצייר כפילות הרבה פעמים בלי גבול א\"כ הוא בגדר ערך וחשבון, וכך אני יכול לומר בלתי גבול פעמים בלתי גבול, כמו שיכולני לומר מילייאן פעמים מילייאן בלי גבול, כיון שהבלי גבול הוא בגדר חשבון בלי גבול פעם א' ימים, ונוסף ע\"ז עוד מילייאן פעמים מילייאן מספרים כאלו הבלתי גבוליים ימים. הרי במספר זה יש בלי גבול, ועוד מילייאן פעמים מילייאן כאלו. א\"כ כך יש לספר ג\"כ בלי גבול פעמים כאלו, כמו שמנית וספרת בלי גבול ימים, ובלי גבול שנים, כך תספור בלי גבול פעמים הבלי גבול ימים, וממילא תוכל לומר ג\"כ בלי גבול פעמים בלי גבול שנים כו', וגם בלי גבול פעמים בלי גבול פעמים בלי גבול כו', כשאר החשבונות שאני כופל מילייאן פעמים מילייאן פעמים מילייאן כו'. וא\"כ ריחוק החשבון הגבול מהבלתי גבול הראשון אינו רחוק כ\"כ לא מיניה ולא מקצתיה מהריחוק שבין המחודש שקדמו ההעדר, לגבי הקדמון שהיה מאז מעולם, שכל כפילות חשבון בלי גבול שיכולני לומר הכל בכללו והוא עודף על זה עד הקדמות ממש, וכיון שכן שבהכרח גם לפי דבריהם יותר אין ערוך המחודש לגבי הקדמון ממה שאין ערוך הגבול לגבי בלי גבול. אם כן שפיר מוכרח לצייר ממשל השורות אילנות הנ\"ל. דכמו שרבוי שורות העצים הגבוליים אינן מצטרפים לבלי גבול, כש\"כ וק\"ו שרבוי הדורות המחודשים אחר ההעדר עם שהם בלי גבול מה שזה אינו אמת, לא יצטרפו בשום אופן להיות המין קדמון. ולכן כמו כשנאמר שאין שום שורה שהיא בעצמה בלי גבול כ\"א בגבול אזי בכלל זה שגם בצירוף כל רבוי השורות הכל חשבון"],[3000730322,"גבול, כי היא ג\"כ כנגד כולן. כך ממש כשנאמר ויאמרו גם הם שאין שום דור מהדורות שחלפו שהיה קדמון באיש רק מחודשים אחר ההעדר, יהי' הקדימה בזמן או בזמן ונוסף ע\"ז גם למעלה מהזמן כו', עכ\"פ כולם מחודשים. א\"כ בכלל זה שגם בצירוף כל הדורות יחד יהי' הכל רק מחודשים היינו כל המין, והדור היותר ראשון הוא כנגד כולן. כ\"ז ברור ופשוט אם כל הדורות היו קיימים באיש, נראה כן בחוש. וגם אם הי' גוף א' מכל דור קיים באיש ואפילו רק גרגיר חרדל מגוף אחד, בענין שתפול עליו השאלה אם הוא מחודש וישיבו שהוא מחודש א\"כ כל המין מחודש אף אם היו דורות בלי גבול, מאחר שעכ\"פ כולם מחודשים אחר ההעדר וכולם לפנינו כשורות האילנות כנ\"ל. וזהו אפילו לפי דבריהם האומרים שהזמן אינו מחודש, וכ\"ש לפי האמת שהזמן נברא. ולא שייך כלל חשבון בלי כפילות הבלי גבול כו' ואין ערוך כלל הבעל גבול לגבי הבלתי בעל גבול. א\"כ אי אפשר כלל שעברו דורות בלי גבול כו', אך כאן ר\"ל שאפילו לשיטתם ההכרח שכל הדורות ומין האנשים וכן כל מין הבעלי חיים הנולדים מזכר ונקבה מחודשים, וכבר הי' זמן שלא היו בעולם כלל.\n<b>(קיצור</b>. דגם לשטתם שהזמן אינו מחודש יותר אין ערוך המחודש לגבי הקדמון ממה שאין ערוך החשבון מוגבל לגבי בלתי מוגבל. וא\"כ כיון שבמשל השורות הנ\"ל אין הרבוי יהיה מה שיהיה פועל כלל להעלות ולהצטרף מגבול לבלתי בע\"ג, כ\"ש שרבוי הדורות אף אם היו ללא תכלה כיון שכולם מחודשים א\"כ כל המין מחודש ולא פגע ולא נגע לענין הקדמות כלל. ולכן המושכל ראשון אמת שזה שקר שילך אל קדמות, ולפי האמת הוא שקר גם שילך אל לא תכלה כ\"א יש להם מספר וכמו ממשל שורות האילנות הנ\"ל, ואפשר שלזה כיונו במשנה ספ\"ב דעדיות האב זוכה לבן כו' ובמספר הדורות לפניו כו', כלומר שמזה אנו רואים בחוש שהעולם מחודש דעל כרחך יש מספר דורות לפניו).\nיב <b>והנה</b> על זה ודאי לא יחלוק שום אדם מהפילוסופים שאם כל האישים שחלפו או אחד מכל דור החולף היו קיימים באיש גם עתה, יודו שכל הדורות שהיו היו מחודשים, ואין שייך חשש קדמות כלל, מהטעם שנתבאר. אלא שהם טוענים כיון שעכ\"פ אינן קיימים באיש, ואין איש כלל לפנינו מכל הדורות החולפים, ע\"כ יוכלו לספק שמא חלפו דורות בלי גבול, כמו בשנים וימים של הזמן. ועל זה נשיב דהא כאשר נעמוד על תוכן וענין הראיה והמופת הנזכר מאות חי\"ת עד סוף אות יו\"ד. שאם כולם קיימים באיש הודית כן בלי שום פקפוק שבהכרח גם בין כולם הכל מחודש ואין שייך קדמות כלל. תוכן הטעם וסופו הוא רק שכיון שכל האנשים שהיו בעולם הם קיבוץ הרבה דורות ושורות זה אחר זה, וכל דור ושורה היה מחודש, ולכן גם כשנקבצו יחד סך הכל ג\"כ רק מחודש, שמקיבוץ הרבה מחודשים לא יתהוה הקדמות. זהו תוכן הטעם. אלא שהכרחנו זה שיהיה העין רואה כן, מפני שגם דור היותר ראשון לפנינו והוא מחודש, והוא כולל כל הבאים אחריו. א\"כ קיבוץ כולם לא עדיף יותר ממנו לבד. וכיון שהוא מחודש הכל מחודש. הנה זה הוא הגדלת הענין וחיצונית שלו שיהיה ניכר ונראה כן לעין ממש שהכל מחודש. אבל כשנעמוד על טעם הדבר למה הכל מחודש, הוא לא משום שהדור הראשון קיים גם עתה שזה אינו רק מראה ומגלה לנו שהכל מחודש עד שלא נוכל להכחיש הדבר. אבל הטעם המכריח החידוש, הוא רק מפני שכל קיבוץ הדורות שחלפו, הכל מקובץ מחלקים מחודשים, היינו כל דור החולף הוא חלק אחד, ונקבצו חלקים רבים זה אחר זה עד שנעשה מהם עולם מלא ישן מכמה דורות. ומקיבוץ חלקיים הרבה מחודשים לא יתקבץ הקדמות בשום אופן כמו שמקיבוץ חלקים גבולים לא יעלה בידך הבלתי בעל גבול, זהו ודאי תוכן הטעם והפנימית של הדבר שמפני כך הוא העולם"],[3000730326,"מחודש, אלא שלא נוכל להראות זה לעינינו ממש אא\"כ כולם קיימים באיש, והיינו משום דאם לא כן יקשה עלינו מחלקי הזמן שהפלסופים מדמים שאינו מחודש כדלקמן, אע\"פ שמקובץ ג\"כ מימים. אבל כשהדורות היו קיימים באיש, אזי בהכרח יראה גם הסומא שהכל מחודש, ואל ירתע מטענת חלקי הזמן, כיון שמ\"מ נראה ודאי ברור כשמש שהאנשים מחודשים, נמצא זה מהני ומועיל רק שיהיה נראה כן. אבל אם כל זה גם אחר שראינו כן, כשנתבונן מה טעם הדבר, למה הכל מחודש, נמצא שהטעם ברור כנזכר לעיל שקיבוץ הרבה מחודשים אף זה אחר זה, יהיה הרבוי כמה שיהיה, לא יתקבץ בשום אופן רק למחודש, ואינו ענין לדבר קדמון כלל וכלל, זהו טעם הדבר וסיבתו. ומה שהדורות כולם קיימים באיש, זהו המראה ומגלה לנו כן. ואף אם תאמר שעברו דורות בלי גבול ממש ושהיה זמן החולף בלי גבול ובו דורות בלי גבול מ\"מ בהכרח שכולם מחודשים, שכן נראה בחוש אם כל הדורות או אחד מכל דור קיים באיש כנ\"ל ועיין לעיל אות י\"א. וטעם הדבר רק מפני שכיון שעכ\"פ מקובץ מכמה דורות וכל אחד מחודש אם כן הכל מחודש.\n<b>(קיצור.</b> הפלסופים ג\"כ לא יחלוקו כלל אם כולם קיימים באיש, ולא נסתפקו רק מפני שאינן קיימים ע\"כ מדמים זה לחלקי הזמן. וע\"ז נשיב דהא מה שהודית כשכולם קיימים באיש, שהכל מחודש, כשתמצי לומר טעם וסיבת הענין הוא מפני שמקיבוץ הרבה מחודשים זה אחר זה לא יתקבץ כלל רק משך מחודש יותר גדול הרבה, אבל אינו ענין לקדמות כלל. ומה שהצרכת שיהיו כולם קיימים באיש זה אינו מוסיף כלל בהטעם וסיבת הדבר, כ\"א רק זה מראה לך שכן הוא בלי ספק ולא יבלבל אותך ולא יעמוד לך לנגד ענין הזמן וחלקיו, שלא יוכל לבלבל אותך כיון שמ\"מ נראה כן בחוש הראייה ממש).\n<b>וכיון</b><sup data-n=\"116\">*</sup> שכן מאחר שעלה בידינו שברור כשמש שמקיבוץ הרבה דורות זה אחר זה לא יתקבץ בשום אופן רק מחודש גדול ולא פגע ולא נגע בבחינת הקדמון כלל. וטעם הדבר וסיבתו הוא רק זה שמאחר שכל חלקיו כולם מחודשים אחר ההעדר, א\"כ גם הכל שהוא המקובץ רק מהחלקים ההם הוא כולו מחודש, רק שהוא גדול יותר מכל חלק בפני עצמו. אם כן הוא הדין והוא הטעם אף אם הדורות שעברו חלפו ואינן קיימים באיש. מ\"מ כל האנשים שהיו מעולם, הכל שלהם ג\"כ מחודש אחר ההעדר מאחר שאינו מקובץ רק מחלקים גבוליים שכל א' מחודש, אי אפשר רק שיהיה הכל גם כן רק מחודש. ואף שאין שום אחד מהדורות ראשונים שחלפו קיימים באיש, אין ההפרש רק שאיני רואה הסוף היינו הקצה הראשון של החידוש לעין כמו שהייתי רואה כשכולם קיימים באיש. משא\"כ כשאינן קיימים, יש לומר שההמשכה היה עוד מקודם, אבל עכ\"ז הכל מחודש. והרי זה כענין ההפרש בין מים שיש להם סוף למים שאין להם סוף בגמרא סוף יבמות, שהוא כשאינו רואה ארבע רוחותיו, שמ\"מ אע\"פ שאינו רואה לעיניו ממש הסוף עכ\"ז ודאי יש לו סיף. כי אי אפשר מקיבוץ חלקים גבוליים שיומשך לאין סוף ממש, כמ\"כ כאן אף שאין הדורות קיימים באיש, אין ההפרש בין אם היו קיימים, רק מה שעכשיו שאינן קיימים איני רואה הסוף. אבל עכ\"ז ודאי יש להם סוף ר\"ל קצה הראשון שהוא מחודש היינו אדם הראשון, כיון שנראה בחוש שמקיבוץ דורות מחודשים אף שיהיו רבים מאד לבלי גבול בלתי אפשר שיתקבץ רק מחודש גדול. וזה נראה לעין מאם שהיו קיימים באיש, שמה שהכל מחודש רק מפני טעם זה לבד לא זולת. והרי טעם זה שייך ממש כמו כן אם אינן קיימין באיש בלתי שום יתרון זה על זה, בענין הגדלת הטעם כלל, דכך ממש שייך זה הטעם כשאינן קיימים כמו כשהיו קיימים.",[["116","*","<b>וכיון</b>: בהוצאה ראשונה נעשה קטע חדש, אבל בגוכתי\"ק נראה שאין כאן קטע חדש. וכ\"ה בבוך 1095."]]],[3000730330,"<b>(קיצור.</b> וכיון שכן הוא הדין אף אם הדורות אינן קיימים באיש כלל, מ\"מ הטעם שוה, כיון שכל הדורות שהיו מן העולם, יהיה הרבוי כמה שיהיה אף לבלי גבול, היו כולם מחודשים וקדם לכולם ההעדר. אם כן הכל מחודש אחר ההעדר, ממש כמו אם היו קיימים באיש. דהטעם שוה בשניהן ממש, רק שכשקיימין נראה כן בעליל. אך ממנו נקח גם לכשאין קיימים כיון תוכן הטעם שוה לגמרי בשניהן)\nיג <b>שמא</b> תאמר אם כן גם בענין הזמן נאמר כן, שהרי הוא מחובר מימים ושנים, וכל זמן החולף אף את\"ל שהיה בלי גבול, מ\"מ לא היה בו רק ימים ושנים. וכיון שכל יום מחודש וקדמו ההעדר וכן כל שנה, וכבר אמרנו שכיון שכל דור ודור היה מחודש א\"כ הכל מחודש א\"כ כמ\"כ כיון שכל יום ויום שחלף היה מחודש אם כן כל המקובץ מהם שהוא הזמן החולף הכל מחודש. ואף שהימים שחלפו לא שייך עליהן לומר שהם קיימים באיש עתה, כמו שיש לומר בדורות אנשים, מ\"מ כבר אמרנו שאין חילוק רק תוכן הטעם מפני שמקיבוץ הרבה מחודשים אף בבוא זה אחר סור זה לא יקובץ רק מחודש גבול. א\"כ גם מכל הימים והשנים שחלפו מימי עולם שברור שכולם היו מחודשים א\"כ הזמן המקובץ מהם הוא ג\"כ רק מחודש, והרי הפלוסוף מכחיש זה. א\"כ אולי מחמת זה א\"כ אולי יסתפק ג\"כ בענין הדורות. ע\"ז נשיב ונאמר כבר אמרנו שבענין הדורות אם היו קיימים באיש גם הוא לא יספק ע\"ז שהכל מחודש. וכדי להעמיד דבריו בענין הזמן יחלק ביניהם כמשי\"ת לקמן אות<sup data-n=\"117\">*</sup>, אף שהחילוק אינו כדאי. וכבר אמרנו שבענין הדורות גם כשאינן קיימים שוה לכמו שהם קיימים, מהטעם שנתבאר, ויתבאר עוד לקמן בעזרה\"י. ואם אחר כך תקיש לזה גם כן ענין הזמן לומר שבאמת גם הוא מחודש מהאי טעמא, נקיש ונקיש, שהרי על זה אנו דנין ודעת גדולי המחקרים הגאון רב סעדיה בספר האמונות מאמר א' והחבר בספר הכוזרי מאמר חמישי והרמב\"ם במורה נבוכים, והרלב\"ג, והעקרים, ובעל נוה שלום ובעל העקדה כולם ס\"ל שהזמן מחודש. רק שאין לנו הכרח מופת חזק שיהיה נראה לעין ממש כ\"כ מהזמן. והגאון רב סעדיה והחבר בכוזרי ודעימייהו הנזכרים ס\"ל שיש ג\"כ מופת על זה, רק הרמב\"ם ס\"ל שאין מופת גמור על זה כדברי הפילוסוף רק שנוטה השכל יותר לזה. א\"כ גם לדבריו אחר שמהדורות יש לנו מופת גמור על זה שכולם מחודשים, אם עי\"ז נקיש הזמן ג\"כ לזה, הרי טוב וישר. ואם יתעקשו ויאמרו שעכ\"ז אין הזמן שוה לענין הדורות ולא נמשיך מזה על זה, עכ\"פ אין זה נוגע כלל לספק ולבלבל עלינו ענין הדורות שודאי כולם מחודשים ונעשה חילוק בין זה להזמן על דרך שיחלק הפילוסוף בין אם הדורות היו קיימין באיש ובין הזמן.\n<b>(קיצור</b><sup data-n=\"118\">*</sup><b>.</b> שמא תאמר אם כן גם בענין הזמן יש לומר כן ולהקישו לדורות שאין קיימים באיש, שהרי כל זמן החולף לא היה רק חיבור ימים ושנים וכל יום וכל שנה מחודשים וקדמם ההעדר, א\"כ כל הזמן מחודש, והרי הפילוסוף מכחיש זה. ע\"ז יש להשיב, הרי באמת כן דעת גדולי החכמים שהזמן מחודש ויש דס\"ל שיש מופת על זה ועמ\"ש לעיל סוף אות ה', רק הרמב\"ם ס\"ל שאין מופת גמור על זה ומ\"מ ס\"ל כן. א\"כ כיון דמ\"מ ס\"ל כן אם מהדורות יומשך היקש על הזמן ג\"כ מה טוב. ואף לדברי הפילוסוף דלא ס\"ל כן בענין הזמן, על כרחו בענין הדורות אם היו קיימים יוכרח להודות שהם מחודשים, ויחלק ביניהן ובין הזמן. וא\"כ הדורות אף כשאינן קיימים גם לדבריו יש להקישן יותר לדורות כשהן קיימים ולא לענין הזמן, מהטעם שנתבאר אות ח' י\"ב ויתבאר עוד אי\"ה מטעם שי\"ל רואין אנו כאלו הם קיימים איש א' מכל דור עכ\"פ משא\"כ בזמן שהוא דבר שאין בו ממש כלל לא שייך לומר כלל רואין ועוד שהאנשים",[["117","*","<b>כמשי\"ת</b>: אות — שלאח\"ז."],["118","*","<b>(קיצור</b>: בגוכתי\"ק חסר סיום המוסגר."]]],[3000730334,"נולדים זה מזה, משא\"כ הזמן. וא\"כ דורות האנשים<sup data-n=\"119\">*</sup> הם כמו עלות ועלולים שאי אפשר לומר שילכו אחרונית אל לא תכלית ולכן לא דומים להזמן וא\"כ הדורות אף כשאין קיימין באיש יש לדמותן לכמו שהן קיימין באיש, ולא לדמותן להזמן.\nיד <b>טעם</b> שני מה שיש לומר שהדורות אף גם כשאינן קיימים באיש דומה לכמו שהם קיימים ולא לענין הזמן, משום דעכ\"פ אפשר לומר רואין כאלו הם קיימים, או עכ\"פ כאילו איש אחד לבד מכל דור ודור הוא קיים באיש, או עכ\"פ איש אחד מהדורות או מהדור היותר מוקדם קיים באיש. וכל דבר שאפשר לומר עליו רואין אנו כאלו הוא כן, היינו שעל כל פנים אפשר היה שיהיה כן קיים ממש, הגם שבסיבת מה לא נעשה כן, מ\"מ מאחר שהיה באפשרי שיהיה כן, א\"כ שפיר יש לצייר כאלו נעשה כן, מאחר שמה שלא היה כן הוא מסיבת דבר אחד, לא שבלתי אפשר להיות כן. א\"כ לענין הדין שדנין עליו, יש לדון כאילו היה קיים באיש, מאחר שמצדו היה אפשר גמור שיהיה כן. והנה דין רואין מבואר בגמ' בכמה מקומות פ\"ק דעירובין דף י\"ג ופ\"ב דסוכה ובשאר דוכתי. אך א\"צ ראיות על זה כי הוא ענין שהשכל נותן כן. וגדולה מזו כתב הרמב\"ם במ\"נ ח\"ב פרק ראשון בד\"ה עיון שלישי וז\"ל והאפשר במין אי אפשר בהכרח מבלתי היותו כמו שידעת כו' עכ\"ל. והביאו ג\"כ בעל העקרים מאמר שני פרק חמישי. משא\"כ הימים והשנים של הזמן שהוא ענין שאין בו ממש אי אפשר בשום אופן לצייר בו ענין רואין כאלו העבר ישנו עתה, שהיום דאתמול אין מתקבל בשכל הציור שיהיה קיים עתה, יותר ממה שאי אפשר לעייל פילא בקופא דמחטא, וכ\"ש המשך הבלתי משוער בתנועת הגלגל, א\"א לצייר שהעבר יהיה בהוה. כי ענין הזמן כל מהותו אינו דבר יש וממש כי אם ענין רוחני, מה שהוא הוה ועבר ועתיד, שאין כל עתותיו באים כי אם דוקא זה אחר סור זה. א\"כ הציור שיהיה העבר וההוה יחד, זהו נמנע יותר משני הפכים בנושא אחד. וכמ\"ש בתשו' ר' ידעיה שנדפס בהרשב\"א ח\"א סי' תי\"ח וז\"ל והחלק השני הנמנע כו' כאמרנו בהמצאת זמן עבר ועתיד יחד מצד אחד, ואיך כי העבר הוא שלא נשאר חלק ממנו שלא נפסד והעתיד הוא שלא התחיל חלק ממנו להתחדש ואיך ימצא יום שיקרא תמול ומחר יחד שלא על שתי הבחינות זה בודאי מאמר סותר עצמו והוא מבואר המניעה שלא תשתנה עכ\"ל. ואף שבאמת פי' שם הוי\"ה היינו היה הוה ויהיה בהשוואה אחת זהו לפי שהוא יתברך למעלה מהזמן לגמרי, או לדעת הרשב\"א שם שחולק על ר' ידעיה הנ\"ל וסבירא ליה שאצל הבורא ית' אין שייך לומר שום מניעה אף על שני הפכים בנושא אחד. אבל בערכינו אנו הדבר פשוט כדברים הנ\"ל שהנמנע היותר גדול שיהיו תמול ומחר יחד. וא\"כ אין שייך כלל לדון על הזמן ע\"ד שאנו רואין כאילו כל הימים שחלפו ועברו קיימים עכשיו, כיון שזה מהדברים שאין להם ציור במציאות ואעפ\"כ יש לדון על הזמן מצד שהוא מקובץ מימים ושנים שהם מחודשים וכנזכר לעיל אות י\"ג, אבל על דורות האנשים*, שיש בכל אחד ממש ומהות וכל אחד נולד ונתהוה ממי שלפניו והוא ג\"כ חלק ממש ממנו כמו ברא כרעא דאבוה הוא, ועובר ירך אמו הוא, וגם גדל הבן עם אביו ואמו זמן רב עד שאחר כך בסיבת ההרכבה של הגוף נפסד ומת האב. א\"כ הציור יכול לקבל שיהיו כל האנשים שהיו מימות העולם יחד ובבת אחת. וכמו שנאמר ואכל מעץ החיים וחי לעולם. או עכ\"פ אחד מכל דור ודור יהיה קיים, לכן יש בדין עליהם לענין חדוש כאלו כולם קיימים.\n<b>(קצור.</b> עוד טעם כי בדורות אף כשאין קיימים באיש דומה ממש לענין הדין כאלו הם קיימים מאחר שאפשר הי' שיהיו קיימין, והאפשר במין דנין עליו כאלו ",[["119","*","<b>האנשים</b>: כ\"ה בגוכתי\"ק, והמו\"ל הראשון הדפיס: הראשונים."]]],[3000730338,"הוא כן. משא\"כ בימים החולפים של הזמן לא לבד שבלתי אפשר שיהיו גם עתה אלא גם אין על זה שום ציור בשכל כלל, כי הזמן הוא דבר אשר אין בו שום ממש שיהיה שייך המשכת מציאות החולף גם עתה, משא\"כ באנשים). \n<b>ועוד</b> אף את\"ל שגם זה קשה לקבל הציור שיהיה הדור החולף מזמן רב קיים עתה חי, כי כל מורכב בהכרח שיהיה נפסד, אף שבאמת יכול להיות קיים ע\"י רצון הבורא יתברך, וכמו שכתבו החכמים שרבים מן הנבראים ומחודשים יהיו נצחיים ברצון הבורא יתברך, מ\"מ נניח זה דאין צורך לזה כאן, דעכ\"פ זה ודאי יכולים אנו לצייר שיהיה אדמת עפר הנשאר מגוף של הדורות החולפים או של אחד מכל דור עכ\"פ יהיה קיים עומד וצבור בפני עצמו, ולא יתערב בגוף אחר הנולד אחר כך, וכגון אילו קברו את המתים בתוך עומק הארץ עמוק עמוק עד שלא יעלה עפר שלו בשום אופן בהצמחים והאילנות הצומחים מן הארץ אפילו לאחר אלף דור ויותר. וכ\"ש שמצינו בתורה שלמה שכן היה המנהג מקודם לקבור המתים במערות וכוכין שבעומק הארץ הרבה כמ\"ש בתורה פ' חיי שרה, ובמשנה וגמרא ספ\"ו דב\"ב, שהן ודאי בעומק הארץ הרבה ועיין מענין מערה בערובין ספ\"ה דס\"א סע\"א נמצא קל תוכה מעל גבה. הרי יוכל להיות דיורין ממש תוך המערה ועל גביהן עפר, מסתמא ודאי העפר גדול וחזק שלא יפול. א\"כ ודאי שהעפר מהמתים הנקברים בכוכין הנ\"ל שבמערות ההם לא יעלה כלל בצמח הארץ, בענין שאי אפשר לספק שהתרכב בגוף אחר האוכל הצמח, ונזכר בגמרא פ\"ק דנדה דף ח' ע\"ב איזוהי בתולת קרקע כו'. וכמ\"כ אם היו נקברים בשקלייעפ שעושין תחת החומה, ובעומק מאד שם ודאי היה עפרו קיים בפ\"ע בלי יורכב בגופות אחרים לעולם. וכש\"כ שיכולים לצייר שנקבר עכ\"פ איש אחד מכל דור ודור בדורות שחלפו קיים באיש בפ\"ע. מה גם המלכים שקוברים בקברות המלכים, או מי שנטבע בים המלח וכה\"ג. ובודאי קרוב הדבר שנעשה כה\"ג בהרבה אנשים ולכל הפחות באיש א' מכל דור עכ\"פ שנשאר גם עתה עפרו צבור לגמרי בפ\"ע. ועוד אף אם לא עשו כן גם באיש א' מכל דור, לא מפני זה יתבטל מה שיש לומר לענין הדין רואים אנו כאלו נעשה כן, כיון שהיה אפשר ונקל להעשות כן, שיהיה עכ\"פ עפר איש א' מכל דור קיים באיש מיום היות אדם על הארץ. וכמו עפר הארץ הגשמיות שקיימת באיש למן היותה עד עתה. וכיון שכן יש לדון על זה כאלו א' מכל דור קיים באיש, שאזי לא יכחיש שום אדם שכל מין האנשים מחודש.\n<b>(קיצור.</b> אף אם נאמר שקשה לקבל הציור שיהי' א' מכל דור קיים חי באיש, עכ\"פ זה ודאי נקל לצייר שעפרו צבור בפ\"ע קיים. א\"כ ה\"ל כאלו אחד מכל דור קיים באיש כמ\"ש לעיל אות חית, ואזי גלוי לכל שכל מין האנשים מחודש).\nטו <b>ואם</b> תאמר איך נאמר רואין, שהוא ג\"כ דבר שאי אפשר להיות כן. דאם היה אפילו אחד מכל דור קיים עפרו בפני עצמו, ואם הדורות היו בלי גבול, א\"כ יהיה גשמים בלי גבול ביחד וזה בא מופת על המנעו כמש\"ל אות<sup data-n=\"120\">*</sup> אך זה אינו שובר על דברינו דהא על זה אנו דנין וכל מגמתינו שיתגלה איך שהיו דורות רק בגבול כפי האמת, וא\"כ זה שיהיה אי אפשר שיהיו גשמים בלי גבול הוא ג\"כ לנו לסיוע שלא היו דורות בלי גבול, שהרי זה ודאי יוכל להיות בקל שיהיה עפר של אחד מכל דור קיים. וא\"כ היו גשמיים בלי גבול מה שזה אי אפשר א\"ו שהיו דורות מספר גבולי. ומיהו שיהיה זה מופת ג\"כ שהדורות הי' בגבול י\"ל שאינו מופת ממש, כי הם יאמרו שאף אם רואין כאילו עשו כן או שבאמת נעשה כן שנקבר אחד בכל דור בעומק, עכ\"ז אם הדורות היו בלי גבול, והרי הארץ כולה היא יש לה גבול ומדה",[["120","*","<b>גבול</b>: אות — ד' (ע' 62) [בגוכתי\"ק מקום חלק]."]]],[3000730342,"כמארז\"ל שית אלפי פרסי הוה עלמא. א\"כ עכצ\"ל שאחר ריבוי הנקברים בעומק הארץ כיון שהגיע שיעור וכמות אדמת עפר שלהם לשיעור חצי כדור הארץ א\"כ כבר הוכרחו לקבור למעלה יותר עד שדחקו והגיעו העפר מהנקברים קרוב לעליונית הארץ ממש עד שמהעפר שלהם צמחו הצמחים והזרעים, ולכן אין עפר במציאות בלי גבול, אף שהיו דורות בלי גבול, כי כולם נמשכים ומתנועעים על אורך בעל תכלית הוא יסוד העפר וכמ\"ש בספר מנוח הלבבות שעל חובת הלבבות שער היחוד פ\"ה. ואף שכל זה כמעט הפך הנראה בחוש שנראה שלא היה במציאות כן ובתולת קרקע יוכיח, מ\"מ אין לחשוב זה מופת עליהם. אבל ודאי עכ\"פ אין מזה סתירה על ענין רואין שאמרנו. דאף לפי זה עכ\"פ היותר קדמונים וראשונים נשארו מונחים בעומק הארץ ועפרם קיים בפני עצמם, כ\"א אחרון אחרון עלו בצמח הארץ הנאכלים לבעלי חיים ומדברים ועי\"ז הורכבו בגופות אחרים וכיון שכן על כרחם שהאישים מהדורות היותר קדמונים ודאי עפרם נשאר קיים באיש, אם יונח שאחד מכל דור נקבר בעומק הארץ או שנאמר רואין. וא\"כ אף שניתן להם טעותם שהם בלי תכלית ומתנועעים על אורך בעל תכלית, עכ\"ז אם היה המנהג מימות עולם למן היות אדם עלה ארץ שעכ\"פ אחד מכל דור נקבר בעומק על כרחך שהדורות היותר קדמונים הם ומהם שעפרם בעומק הארץ ולא עלה בצמח הארץ כלל. וא\"כ כיון שמהדורות היותר קודמים שאפשר יש איש א' קיים באיש היינו עפרו בפני עצמו א\"כ ודאי הכל מחודש כמשנ\"ת למעלה.\n<b>(קיצור.</b> לכאורה יש להקשות שא\"א לומר רואין שהרי זהו מהנמנע שיהיו גשם או גשמים בלי גבול. ואם נאמר שא\"כ אדרבה זהו עוד ראיה שהיו הדורות רק בגבול, ע\"ז ישיבו לא כי אף שהם בלי גבול מתנועעים על אורך בעל תכלית. וא\"כ על כרחך כשרבו הנקברים בעומק עלה עפרם מן הארץ ועלה בצמחים וזרעים. וא\"כ אין ביכולת לומר רואין כאלו עפר של א' מכל דור קיים בפני עצמו. אך זה אינו דעכ\"פ האיש מהדורות היותר קדמונים נשאר עפרו בעומק הארץ ומה שעלה הוא רק מהאחרונים אף שאין שייך ראשון בדבר שבלי גבול. על כרחן עכ\"פ אין זה שובר לטענת רואין מטעם הנ\"ל דלא יצוייר ענין הכרח העלייה בצמח רק אחר רבוי רבבות דורות לאין שיעור מהנקברים תחלה)\n<b>עוד</b> יש לחזק הענין דרואין כאלו כן הוא, אף אם לא עשו כן למעשה מפני שלא רצו לטרוח אין זה ביטול לענין הדין בסברא דרואין כנזכר למעלה. ויש להוסיף, דעל כרחנו קדמות האישים והדורות, הוא קודם להקבורה דהרי החיות והלידה קודם להמות. אלא ששפיר יש ראיה גם מהמות על הלידה והחיות, היינו שאם גופם קיים באיש על כרחנו נודה שהיה מין האדם וכן הבעלי חיים מחודש. ואם כן אף כשאין גופם קיים דהיינו מפני שלא נזהרו וטרחו בענין הקבורה, אין זה מבטל הראיה על הקודם דהיינו על הלידה שהיו כולם מחודשים, דמה שלא עשו כן בזמן העתיד מה שאפשר היה להעשות כן, אי אפשר שיהיה זה שולל ומונע ומבטל הענין שבזמן הקודם שהרי אז בזמן הקודם היה ודאי אפשר ואפשר שבזמן האחרון יעשו כן ויקברו אותו בעומק. וא\"כ היה ודאי מחודש בזמן הקודם. וא\"כ כיון אם היו קוברים כן בעומק מוכרח שבלידתם שהוא קודם לזה היו כולם מחודשים והי' כל המין מחודש, אין מה שלא נעשה כן אח\"כ מבטל ענין הקודם ולכן זהו ודאי טעם נכון שנדון עליהם בדרך רואין כאלו איש אחד מכל דור מהדורות החולפים קיים באיש.\n<b>(קיצור.</b> עוד טעם יש לחזק ענין רואין שהרי הראיה הוא מענין העפר שהוא אחר זמן המיתה על הקודם, ובזמן הקודם היה ודאי הדבר שקול שאפשר שיעשו"],[3000730346,"בזמן המאוחר באופן שיהי' עפרו קיים. א\"כ מה שלא עשו כן בזמן המאוחר אין זה שולל האמת מזמן הקודם).\n<b>ועמשל\"ק</b> בנייר<sup data-n=\"121\">*</sup> שגם מ\"ש הרמב\"ם תחלת חלק ב' הקדמה השלישית שמציאות עלות ועלולים אין תכלית למספרן שקר. אין לזה טעם רק מפני שכיון שהם מתהוים זה מזה רואין אותן כאילו כולם קיימים איש. וכיון שכן אם כל א' מהם מחודש מזולתו, א\"כ כולם מחודשים, וקיימים באיש, א\"א שיהיו בבע\"ת וע\"ש בהרש\"ט שהטעם הראשון שלו אין לו שחר ומוכחש מדעתם בענין הזמן שהחלק כמו הכל, כמש\"ל. והטעם השני, כי אם לא ימצא הראשון לא ימצא האחרון, זהו עצמו ענין מ\"ש רואין אותן כאלו כולן קיימים באיש, דפי' לא ימצא ראשון היינו שהוא מחודש, וא\"כ מי המציאו. וא\"כ גם באישי האדם שייך לומר כן ומש\"ש הרש\"ט וג\"כ בטלנו כו' ראובן הנמצא עתה כו' עכ\"ל זהו הבל הבלים כמ\"ש בשם האו\"נ בפירושו לח\"ה פ\"ה ס\"ק י\"ד ואדרבא באישי האדם האמת שייך יותר לומר רואין כי הם באמת קיימים באיש. בספר האמונות והדעות מ\"א פ\"א בהפירוש הנק' חקר דעת סד\"ה כל מה שלא קדם החדוש, כ' שהפלסוף לא ירחיק מציאות עלות ועלולים יחד בב\"ת כמספר בבא זאס\"ז כו' רק בב\"א. הנה הרש\"ט ריש ח\"ב גבי והקדמה הג' כ' בהפך וז\"ל שא\"א שיהיו עלות ועלולים יחד בב\"ת או שהי' נמצאים בזה אחר זה, כי בכל אם הראשון לא נמצא האחרון לא נמצא עכ\"ל, וכ\"כ המנוח הלבבות בפירושו לח\"ה פ\"ה ואף כי מציאות עלות ועלולים לבב\"ת אפילו שימצאו בזאס\"ז שקר כו' עכ\"ל, רק המ\"ה חילק שם דבאישי האדם שאני שתכליתם הוא החומר הראשון. ולפמ\"ש שיסוד טעם זה משום רואין א\"א גם באישי האדם ובע\"ח שייך כן.\nטז <b>ומלבד</b> ענין רואין יש לומר עוד שהם ממש כאלו קיימים באיש לא איש אחד מכל דור לבד כי אם יותר כמו שנבאר אי\"ה מכמה טעמים. האחד דהנה כבר נתבאר שאפילו אם היה גרגיר חרדל עפר מגוף אחד שבכל דור עומד בפני עצמו בארץ זהו ענין שהדורות קיימים באיש להביא מזה מופת על המבוקש. ובודאי שרחוק מאד לומר שלא יהיה נשאר אפילו גרגיר חרדל אחד בפני עצמו מכל אדמת עפר של אלף מילייאן אנשים שבכל דור לשטתם, והוא הפך האמת. דכיוצא בזה איתא בספר האמונות והדעות לרב סעדיה מאמר שביעי פרק א' בענין תשובה על הטענה בתחיית המתים, שהגוף החי אחר מותו כבר נמקו החלקים אשר היו בו מן היסודות הארבעה, אשר הגיע כל חלק מהם יסודו השרשי ונמזג בו, ואחרי כן התחברו החלקים מן היסודות ההם והתרכב מהם גוף שני ואח\"כ נמקו במותו, איך יהיה הראשון על שלימותו והשני על שלימותו והשלישי על שלימותו וחלקי כל אחד מהם כבר נכנס בהאחר בעת שהתרכב. וע\"ז השיב שהבורא ית' יכול לשום חלקי הגוף השני חלקים מן היסודות אשר לא שמש בם בגוף הראשון, וכן ירכיב השלישי מחלקים לא היו נמזגים בשני, וכן יחביר הרביעי מחלקים לא התערבו בשלשי, ומפני רוחב עולמי היסודות ומוצאיהם ויעזוב נמוקי הגוף הראשון והשני והשלישי ומה שאחריהם בעצמם לא ישתמש בחבורי העתידים עכ\"ל. וכ\"ש וק\"ו שאין לומר שאפילו גרגיר אחד עפר מכל דור לא נשאר בפני עצמו מה שלא נכנס בגופות שאר דורות זהו ודאי עקשות ושקר. ועוד שהרי הרכבה זו שיכנס העפר מגוף הראשון בגוף השני הנולד מאב ואם ולא מהעפר, אי אפשר אלא רק ע\"י שתאמר שנכנס העפר במה שצומח ממנו תבואה ועשבים ופירות שהן מאכל האנשים. והרי המתים נקברים בעומק עד שאפשר וקרוב שאין עולה מהעפר שלהן בצמח הארץ וכ\"ש במקומות",[["121","*","<b>ועמשל\"ק בנייר</b>: קטע זה ליתא בבוך 1155.\n*)החסר קודם סי\"ח — ראה בהוספות [ע' 214]."]]],[3000730350,"שקוברין בכוכים שבתוך המערות כמ\"ש לעיל אות י\"ד. וגם יש הרבה מתים בכל דור אנשים במקום אשר אין זרע וקציר כמו במדבר בארץ מלחה, או ביערות שאף את\"ל שהיו מאכל לבעלי חיים עכ\"ז עכ\"פ לא הורכבו בגופות אנשים מדברים. ועוד שהרי העצמות אינן ראויים לאכילה גם לבעלי חיים, א\"כ עפר העצמות שבשם לא הורכב בשום דבר, וכן בים המלח וכן שייך לומר כן על עצמות החיות שבשם שאינן מאכל לחיות, ואין שם זרע וקציר, א\"כ בהכרח לא הורכבו כלל בגוף שני. וא\"כ לפי האמת ודאי יש הרבה חלקים עפר מהרבה מאד גופות אנשים שבכל דור ודור שלא נכנסו כלל בגופות הדורות שאחר כך, ועומדים בפני עצמם, עד שיש לומר שיש מכל הדורות שחלפו קיימים באיש. וכן הוא נראה שבית עלמין שהוא אפילו יותר מזמן שלשת אלפים שנה ידוע הוא בפני עצמן וקיים אדמת עפר שלהן לגמרי. ואף שלשטתם מוכרח לומר שלא נשאר גרגיר עפר מכל דור בפ\"ע כנז' לעיל אות ט\"ו כבר כתבתי שלא מפני הטעות והשקר שלהם נכחיש ונקרב בזרוע את המרוחק מהשכל ויותר ודאי יש לקרב האמת שנשאר עפר מכל דור, ושהיו הדורות בגבול, משיקרב את המוקצה מהדעת.\n<b>(קיצור.</b> שבודאי עכ\"פ באמת לפחות נשארו כמה חלקים עפר מכמה גופות שבכל דור מדורות שחלפו מה שהוא טמון ומכוסה תוך האדמה ולא נכנס בגוף אחר כלל מהדורות הבאים אחריו).\n<b>ועוד</b> דאף אם היינו נותנים להם לומר שיוכל להיות שאין שום גרגיר עפר אפילו אחד נשאר מכל דור שלא הורכב כמה פעמים בגופות דורות שאחריו, הנה אם נניח שהורכב כן רק בגופות שבמספר מוגבל, אף שיהיה מספר רב ועצום כמו אלף אלפי אלפים רבוא רבבות גופות זה אחר זה, זה אינו מעלה ומוריד כלל לפחות המופת דלעיל. דהנה כשתצייר שיש הרבה גרגירי עפר מאד בגבול או בלי גבול, וכל גרגיר היה נושא לאלפי אלפים גופות עד\"מ זה אחר סור זה, עכ\"ז מאחר שכל האלפי אלפים גופות של גרגיר האחד כולם מחודשים, וכל הגרגירים הבלתי גבול שכל א' כולם קיימים, ובכל א' היו גופים בגבול, ה\"ז כל האישים שהיו עומדים לפנינו, ומוכרח שכל המין מחודש ואין לכפול הדברים, המבוארים לעיל אות חת טית יוד י\"א. ואין לגמגם מלומר שכל הדורות שחלפו עומדים קיימים באיש אא\"כ תאמר שכל גרגיר הורכב כן בגופות זה אחר סור זה לבלתי גבול ממש. וגם זה אינו מבטל הדבר לפמ\"ש לעיל אות ג' ואות ב' ואות י\"א שלשטת האומרים שהזמן אינו מחודש צריך לומר שיש בלי גבול גדול מבלי גבול כמה פעמים עד\"מ אלף מילייאן פעמים בלי גבול כו' והקדמות גדול הרבה יותר לאין שיעור מסתם בלי גבול, שיש בלי גבול ואעפ\"כ הוא מחודש ויש קודם לו כו' כנ\"ל, וכיון שכן אף אם הורכב בגופות זאס\"ז בלי גבול מאחר שגרגיר זה עומד לפנינו ואנו רואים שהגופות בלי גבול שהיו ממנו כולם מחודשים. א\"כ כל המין מחודש, אף שהיו דורות בלי גבול. דהא לשטתם בעצמו מוכרח שבלי גבול המחודש אינו ערוך להקדמות, שהרי ביכולתינו לומר בהזמן החולף, אלף אלפי אלפים פעמים בלי גבול, שזה מוכרח לשטתם שהזמן אינו מחודש. וא\"כ לגבי בחינה זו דקדמות אף שהיו דורות בלי גבול ממש כיון שהיו כולם מחודשים וכאלו עומדים לפנינו ע\"י גרגיר זה, א\"כ כל המין מחודש.\n<b>(קיצור.</b> ואף אם נניח שהורכב ונכנס בגופות מהדורות הבאים אחריו אפילו אלף פעמים זאס\"ז או הרבה יותר אם הוא מספר גבולי פשוט שאינו שום נפקותא כלל למבוקשינו כאלו לא נכנס בגוף אחר כלל. והנה אפילו יאמרו שהורכב ונכנס בגופות זאס\"ז בלי גבול פעמים, מ\"מ ממ\"נ לשטתם שהזמן אינו מחודש חזר בלי גבול המחודש "],[3000730354,"כמו גבול המחודש, שבבחי' קדמות יוכלו לומר בלי גבול פעמים אין מספר. וא\"כ ע\"כ הדורות מחודשים אף שהיו בלי גבול. ואם תאמר שהזמן מחודש א\"כ א\"צ לכל זה וזהו מבוקשינו). \n<b>לא </b>נשאר לומר רק שמא היו בו גופות בלי גבול כ\"כ עד בחינת קדמות, וע\"ז נשיב כיון שזה רחוק מאד בתכלית מטעם המבואר אות י\"ב ואות י\"ד, א\"כ כיון שעכ\"פ מכל הגופות שהיו בו נשאר ממש והוא גרגיר זה. וא\"כ יהיה בו רבוי כמה שיהי' נראה כאילו כולם לפנינו ונחלק עד\"מ עפר זה לפרורים דקים בלי תכלית אף שא\"א לומר כן בפועל מ\"מ במחשבה נחשב וכאלו כל א' מהגופים שהיו בו עומד לפנינו יהיו בל\"ג פעמים בל\"ג. מ\"מ כיון כולם לפנינו ע\"י עפר זה שלהם שנשא את כולם וא\"כ כולם וכל המין מחודש. כי בהכרח בל\"ג למטה ממדרגת קדמות, ולא דמי לרגעי הזמן אף לשטתם שאינו מחודש, מחילוק הנזכר לעיל אות י\"ד. דהכא עכ\"פ נשאר העפר ממש מכל דור שהיה בעולם, אלא שהיה נושא עוד לדורות שאחריו. משא\"כ הזמן החולף לא נשאר ממנו מאומה, וגם בעצם אין בו ממש כלל, שיהיה שייך לומר רואין את החולף כאלו ישנו א\"כ אין שייך עליו כל כך השאלה והתשובה הנ\"ל אבל בגופות דורות החולפים שיש בהם ממש ונשאר קיים לפנינו מכל הדורות שחלפו ואין שום אחד שיאמר עליו שלא נשאר ממנו רושם עתה ואם כן אף שהיו נושא לגופות רבים במאד מאד מ\"מ הריני רואה עפר זה כאילו עד\"מ מתחלק לפירורים רבים במאד מאד כשיעור כל הגופים שנשא יהיה הרבוי כמה שיהיה. וא\"כ כולן עומדים באיש וכל המין מחודש. ועוד דאם לא כן תאמר שהגוף היותר ראשון נידון כחולף לגמרי וכאילו לא נשאר ממנו רושם כלל. וזה דבר שלא ניתן להאמר, דהא ודאי אין העפר נושא לגוף השני יותר מלהראשון, ואדרבה בכל מקום הראשון עיקרי וחשוב יותר, והרי אם היה נושא רק לגופות במספר מוגבל על כרחנו הוא נושא לגוף הראשון יותר עד שהרי זה כאלו כולם עומדים לפנינו ממש שיהי' גלוי מזה לעין כל שכל המין מחודש. א\"כ כמ\"כ ממש כשתאמר שהוא נושא לגופים בלי גבול ברבוי מאד עכ\"פ היותר מוקדם נחשב ונרמז בו ג\"כ שמפני שנשא אחריו גופות אחרים לא נעקר ממנו היותר קודם, וה\"ז כאלו כולם עומדים באיש ועי\"ז גלוי לכל רואה שהמין מחודש. ואף אם נאמר שכיון שאין לכל דור עפר מיוחד ממש אין זה גלוי לכל כמו אם היו קיימים ממש באיש. מ\"מ בלאה\"נ סברא זו רחוקה שיהי' נושא לגופים בל\"נ כ\"כ. ועכ\"פ מהני טעם לחזק הטענה דרואין הנז' אות י\"ד והטענה הנז' אות י\"ב\n<b>(קיצור.</b> לא נשאר רק לספק ספק רחוק מאד שמא היו בו גופות לבלי גבול כ\"כ, עד מדרגת הקדמות. ע\"ז נשיב ונאמר סותרו, כיון עפר זה הוא הנושא לכל הגופות, ויותר נשא לגוף ראשון ראשון, נראה כאילו הם כולם לפנינו וא\"כ כולם מחודשים. ואם לא נרצה להכחיש שלא היו בלי גבול כ\"א בגבול. אך זה ודאי שהם מחודשים וגם י\"ל שיכול לחלק במחשבה העפר לפרורים דקים בלי גבול עד שיהיה נראה כאלו כל סכי הגופות בלי גבול שהיו בו כולם לפנינו).\nיז <b>עוד</b> אפשר לומר משל הנ\"ל, מהגרגיר עפר שנשא לגופות זאס\"ז ברבוי מאד, בענין אחר להכריח מזה החדוש והוא שאני רואה גרגיר זה, כאלו הוא גוף אחד ארוך מאד וזקן מרבוי הזמן ההוא, וקיים כולו באיש מאז היות ממנו גופים עד עתה, כיון שכל הגופים הרבים היו נשואים על עפר זה האחד א\"כ הוה להו כל הגופים הרבים הנ\"ל כגוף אחד ארוך מאד ר\"ל זקן מזמן רב מאד היינו מאז היות בו הגוף היותר מוקדם עד עתה הכל נחשב גוף אחד מחמת שהרי חומר כולם היה גרגיר עפר הזה, רק שפשט צורה וחזר ולבש צורה אחרת וחזר ופשט צורה ולבש צורה וכן חוזר חלילה. עכ\"פ מאחר שהחומר אחד אף שהצורה משתנה רבוי פעמים"],[3000730357,"מאד. א\"כ מצד שנושא כולם הוא חומר אחד יש להחשיבם גוף אחד, ואזי ודאי מוכרח שהוא מחודש, דזה אין מספקים אף הם שמא יש איש אחד שהיה קדמון באיש, ומודים הם ג\"כ שכל פרטי האישים היו מחודשים, אבל כיון שנאמר שלא היה רק איש אחד על כרחן הוא מחודש.\n<b>(קצור</b>. שי\"ל כיון שכל הגופים היו נשואים רק על גרגיר עפר הזה הוה להו רק גוף אחד ואיש אחד. והכל מודים שקדמון באיש לא היה א\"כ הכל מחודש). וא\"כ פשוט שאינו דומה לשעות ורגעי הזמן דהתם אין להם נושא אחד א\"כ הם חלקים רבים אבל הכא י\"ל שהם גוף אחד וא\"כ הוא מחודש. והרי זה עד\"מ כמו חתיכת כסף אחת גדולה שעשו ממנה גביע. והנה הגביע ודאי מחודש שהוא מעשה ידי אדם ואין גדל כן בארץ. והנה אם נצייר שאח\"כ שברוה והתיכוה ועשו מהן גביע אחר או קערה, פעמים רבים זאס\"ז, כלים מכלים שונים, או הכל גביע זאס\"ז, מ\"מ אין ספק שכל הגביעים יהיו כמה שיהיו הכל מחודש, כיון שהחתיכה כסף אחת היא והיא קדמה בהכרח גם להגביע היותר קדמון, ובהכרח היה זמן שהיה חתיכה זו בלי צורת גביע, עד שאח\"כ עשו ממנה גביע. וכיון שכן ע\"כ הגביע היותר ראשון ג\"כ מחודש, מאחר שיש דבר קדם לו הוא חתיכת כסף, ואף שעשו ממנו גביעים רבים זאס\"ז עכ\"ז הכל מחודש. שכמו אם עשו ממנו גביע רק פעם אחד וחזרו והתיכוהו ומונח כן מאז בלי צורה כלל ודאי הגביע מחודש כמו כן אין חילוק אף אם עשו ממנו באמצע כמה רבוים גביעים זאס\"ז או כלים מכלים שונים הכל מחודש. דה\"ז ממש כאלו הגביע הראשון עומד לפנינו גם עתה שהרי חומרו כאן, ובודאי הגביע הראשון מחודש, דנלך אחר הטעם. דכמו אילו היה מונח כן הגביע הראשון ממש עשוי או מהותך היינו יודעים שבודאי אינו קדמון כ\"א מחודש מפני שאין גדל כן גביע בארץ רק בהכרח נעשה מן חתיכת כסף ע\"י אדם, כמו כן גם כשנעשה ממנו עוד רבוי פעמים כלים זאס\"ז הלא עכ\"פ ידוע ומוכרח לנו שכל ענין כלי שהיה בו הכל מחודש, וקדם לו החתיכת כסף. \n(קיצור. ונמשיל כמו חתיכת כסף גדולה שעשו ממנה כלים מכלים שונים בזאס\"ז, שעכ\"ז הכלים מחודשים כלים, מאחר שיש דבר קדם לו הוא חתיכת הכסף, וכמו אם עשו ממנה כלי רק פעם אחד).\n<b>והנה</b> כמו כן גופות האנשים שיסודם מעפר, כמ\"ש וייצר ה' אלקים את האדם עפר מן האדמה. וגם כל טענת הפלסופים להכחיד החדוש זהו באמרם כי על גופות האנשים עם שהיו לפי דבריהם בל\"ג הם מתנועעים על אורך בעל תכלית הוא יסוד העפר כמש\"ל אות ט\"ו בשם מנוח הלבבות (ושם נקט החומר הראשון אבל הענין הוא יסוד העפר) שא\"א להכחיש שהנשאר מהגוף הוא עפר, וכמ\"ש ואל עפר תשוב. וכיון שכן על כרחם ערך העפר אל הגופים הוא ממש כמו חתיכת הכסף לגבי הגביע שכמו שהכסף קדם להגביע כן לדבריהם שטענת הקדמות באנשים הוא מיוסד על שהעפר הוא הנושא לכל הגופות א\"כ הוא נושא להם כמו הכסף לגבי הגביע. א\"כ ע\"כ הגופים הם מחודשים ובהכרח שקדם להם העפר מן האדמה ועיין לעיל ח\"א סעיף ך' ך\"א בענין ראיה שלישית של רס\"ג, וכמו שבענין הכלים בהכרח קדם הכסף אף אם עשו כלים רבים זאס\"ז כמו אם עשו רק כלי א'. כמ\"כ לענין גופות האנשים אין חילוק אם הורכב ממנו רק גוף אחד ועומד כך אדמת עפר מעת שפשט צורתו הראשונה, היינו גוף הראשון ששב אל העפר, שודאי הוא מחודש שהרי העפר קודם אל גוף זה כמו כן אף אם היו ממנו גופים רבים זאס\"ז, ע\"כ קדמם העפר. א\"כ שבנו אל מה שהתחלנו שכיון שעפר אחד שלפנינו בהכרח היה נושא לכל הגופים א\"כ כל הגופים שהיו בו חשבינן להו כגוף אחד ארוך, לענין שעל כרחך קדמם החדוש, שמעפר זה נבראו"],[3000730360,"ונתהוו ונתהוו, כמו שהכלי נעשה מחתיכת הכסף.\n<b>(קיצור.</b> שגופות האנשים לגבי העפר, ככלים לגבי הכסף. וא\"כ כמו שעשיית הכלים בהכרח מחודש היינו שקדמו הכסף, כמ\"כ גופות האנשים קדמם העפר. וא\"כ ע\"כ הי' זמן שלא היה אדם עדיין רק עפר, א\"כ האדם מחודש)*.\nיח <b>ולכאורה</b> י\"ל שעשיית הכלים מהכסף לא דמי ממש לגופות האנשים לגבי העפר. כי עשיית הכלים זאס\"ז אינו דומה לעשיית גופים זאס\"ז ששם מן הכסף ממש עושים הכלי, והכא בא ע\"י גלגול רב שאב ואם אוכלים תבואת הארץ שיש בה יסוד העפר כו', ועשיית הכסף מהארץ ודאי נתחדש, ומוכרח שקדם אל הכלים. ועוד שעשיית הכלים זא\"ז אינו דומה להתחדשות הראשון כי עשיית הכלים זהו יש מיש, רק שינוי הצורה לבד, והכסף מהארץ שינוי גמור והויה חדשה. על כן כיון שהויה חדשה נעשית ונתחדש רק פעם א' ודאי הוא מחודש אף ששינוי הכלים זא\"ז אח\"כ היה בל\"ג פעמים, מ\"מ ע\"כ קדם להם מעשה הכסף מהארץ. אבל בגופות בנ\"א שהתהוות הדורות זה מזה הכל בסגנון אחד, ואת\"ל שעברו בל\"ג פעמים אף שע\"כ הכל מעשה ידי אדם שמא מ\"מ אין הכל מחודש, ע\"ז נשיב בס\"ד, דהא אנו אין מביאין ראיה רק מחתיכת כסף אחר שכבר נעשית כסף שגם היא בהכרח קדם לכל הכלים לבד מה שקדם לה העפר שממנה מהפכים לכסף, כ\"א גם קדימת החתיכת כסף לגבי כל הכלים שעשו ממנה, ע\"ז י\"ל דדומה ממש לענין הגופים לבד העפר, ואף שהגופים מהעפר באים ע\"י גלגול רב משא\"כ בעשיית הכלי מהכסף, מ\"מ לענין המבוקש, אין לחלה, שמ\"מ העפר יסוד להגוף כמו הכסף להכלי, אף שבהגוף מתערב עוד אר\"מ עכ\"פ עיקר יסודו הוא העפר. ואף שגם מהעפר אל הגוף נמשך ע\"י ממוצעים התבואה ואב ואם, מ\"מ לקושטא דמילתא אין נפקותא, שבשני הענינים הטעם שוה שבהכרח החומר קדם אל הצורה קדימה זמניית ממש, דממנ\"פ לדבריהם שעיקר טענתם על הקדמות באנשים הוא לא מצד אב ואם עצמם כ\"א מצד שמעפר יסודם. א\"כ העפר הוא לאנשים כמו הכסף אל הכלי. ולפי האמת אשר לא כן כ\"א גופות אב ואם הוא המקור לבניהם אחריהם, ולא שייך העפר לזה, בלאו הכי מוכרח שכל הגופים מחודשים.\n<b>(קיצור.</b> מה שלכאורה יש לומר שאין הגופות לגבי העפר כמו הכלים לגבי הכסף, משני טעמים הא' שהגופות באים ע\"י אמצעיים רבים מהעפר, משא\"כ הכלים מהכסף. הב' שאל הכסף יש עוד דבר קדום היינו העפר שממנו נעשה, א\"כ שם מוכרח יותר החידוש בהכלים. ושמ\"מ אין שום חילוק, כי החילוק האחד אין נפקותא שמ\"מ העפר יסוד להגוף כמו הכסף להכלי, ומה שהוא ע\"י ממוצעים אין נפקותא לדינא. והחילוק הב' ג\"כ אין נוגע לנו מאחר שדי לנו בקדימת הכסף על הכלים לבד הקדימה הראשונה של העפר להכסף, דדל מהכא קדימה זו אף אם יצוייר שיש כסף ממש בארץ שלא קדמו עפר, עכ\"ז די להכריח שהכלים מחודשים).\nיט <b>ומכל</b> זה נדחה הטענה של הפילוסוף שיוכל לומר ראובן בן יעקב ויעקב בן יצחק ויצחק בן אברהם כן אל לא תכלה כו' מחמת הטענה מהזמן שלדבריהם אינו מחודש, והוא בא ג\"כ שעות רבות זאס\"ז אל לא תכלה כמ\"ש הרמב\"ם במ\"נ ח\"א פע\"ג בד\"ה ההקדמה הי\"א, ובהקדמה לח\"ב הקדמה ך\"ו. וכבר כתבתי לעיל אות י\"ג לחלק ביניהן אף לדבריו. וכאן נוסיף בס\"ד, דהתם שעות ורגעי הזמן הם חלקים מובדלים, ואין להם נושא אחד לכולן אבל הכא שעל כרחך כל הגופים יסודם מהעפר, והעפר קדם להם בודאי, כמו הכסף להכלים, א\"כ הם ודאי מחודשים. ונמשיל עוד משל לענין עשיות כסף וכלי כסף מעפר הארץ שרוב הכסף והזהב אין"],[3000730363,"גדילים בארץ כמו שהן, כי אם שעושים אותם בני אדם ע\"י תחבולה שמהפכין העפר ההוא לכסף וכדומה. והרי עי\"ז אנו יודעים שהכסף והזהב מחודש מבני אדם וקדמו ההעדר, ואם עשו ממנו מטבע זאס\"ז רבות פעמים ודאי כולם מחודשים. ומזה ג\"כ טענה על קדמות דא\"כ ע\"כ היו דורות שלא הי' אצלם מטבעות כסף וזהב כלל כיון שהכסף והזהב מחודש וכ\"ש המטבעות. והרי הפלסוף אומר שעולם כמנהגו נוהג מימות עולם מלא מבני אדם, כמו שכתב רס\"ג מאמר א' פ\"ד בד\"ה והדעת העשירי, שהם אומרים כי הדברים כולם לא סרו על מה שאנחנו רואים מהארץ והשמים והצמח והחיים ושאר המקריים אין להם תחלה ולא סוף עכ\"ל. ואיך אפשר כן, לומר שהיו מטבעות כסף וזהב, בשוה מעת היות הארץ. מאחר שהטבעות מחודשים מן הכסף והזהב, וזהב קדם לו ההעדר שנעשה מן העפר, איך אפשר ליתן לשניהם קדימה שוה. וכמו שאי אפשר שאברהם ויעקב נכדו נולדו שניהן כאחת כן הדבר הזה.\n<b>(קיצור.</b> מן כסף וזהב ונחושת שהם מחודשים ונעשים מן העפר והעפר קדם להם בהכרח והכסף והזהב והנחשת כמעט קיימים באיש מזה יש שובר למאמיני הקדמות שאומרים שעולם כמנהגו נוהג מימי עולם. וזה אי אפשר שעל כרחנו היה זמן שלא היה עדיין כסף וזהב, שהרי העפר והאנשים שעשאו מהעפר את הכסף ע\"כ קדמו זמן להכסף. וכן י\"ל בבנין בתים ועיירות וכמ\"ש מזה במ\"א).\nאך נניח זה כאן. ונחזור לענינינו ונאמר אם הכסף הנ\"ל, שעשו מהעפר ועשו ממנה כלי או שעמד כך נסכא כסף, עמד זמן רב כ\"כ עד שנרקב ושב אל העפר לפמ\"ש הרמב\"ם שגם המתכת בזמן רב ע\"כ ישוב לעפר, וז\"ל אפילו הזהב והאודם אי אפשר שלא יפסד ויחזור ליסודותיו, וישוב מקצתו לאש, ומקצתו למים ומקצתו לרוח ומקצתו לארץ, הואיל וכל הנפרד יפרד ליסודות אלו למה נאמר לאדם ואל עפר תשוב, לפי שרוב בנינו מן העפר עכ\"ל פ\"ד מה' יסוה\"ת הלכה ג\"ד, וכ\"ש בכסף וזהב שיסודם יותר מהעפר מן האדם, שהדומם ודאי יסודו מעפר יותר מן החי והמדבר. וא\"כ כשהכסף והזהב יפסד וישוב לעפר, וכשנעשה עפר ודאי יכולים אח\"כ לעשות ממנו עוד כסף כמו שעושים לכתחלה מהעפר לכסף, או אם הושלך במקום שמהעפר עושים כסף, ואח\"כ חזרו ועשו ממנו כסף ומהכסף כלי, וכן חוזר חלילה פעמים רבים לבל\"ג, נביט ונתבונן אם אעפ\"כ מוכרח שכל הכסף שהיה בו הכל מחודש. ובודאי דהכל מחודש מאחר שעכ\"פ מתחלה אין הכסף קדמון באיש, כ\"א מחודש בידי אדם מהעפר. וא\"כ אין הפרש בין אם תאמר שהכסף וזהב לא נרקב ועשו ממנו כלים רבים בזא\"ז בל\"ג פעמים דמ\"מ ודאי כל הכלים מחודשים שהרי קדמם הכסף הפשוט הנסכא כסף, ואל הנסכא קדם העפרות כסף וזהב, ואין מה שעשו כלים זא\"ז בל\"ג פעמים גורע ההכרח שעכ\"ז הכלים מחודשים מהטענה שעכ\"פ קדמם הנסכא כסף והעפר. א\"כ כמ\"כ באופן השני שתאמר שאחר שעשו מהעפר נסכא כסף וכלי אח\"כ שב לעפרו וחזרו ועשו ממנו נסכא וכלי וחוזר חלילה כן בל\"ג פעמים. עכ\"ז כל הכלים מחודשים, כמו באופן הראשון, מאחר שבהכרח קודם העפר להכסף והכסף להכלי, ומה לי אם אופן עשיית הכלים מכסף זה בל\"ג פעמים היה ע\"י שלא נרקב ושב לעפר או ע\"י שנרקב ושב לעפר דכשם שבאופן הראשון מוכרח שכל הכלים מחודשים כך באופן השני כיון דמה שעברו עליה התהוות בל\"ג זא\"ז אינו גורע שהכל מחודש, וטעם א' לשניהן. והרי גם באופן השני אין הענין רק שעברו עליה התהוות פעמים בל\"ג והרי זה היה כמ\"כ באופן הראשון ועכ\"ז הטענה דהכסף אין קדמון באיש מכריח שהכל מחודש כך לי באופן הראשון כך לי באופן השני."],[3000730366,"<b>קיצור.</b> עוד משל לגופות האדם מן העפר כמו עשיית הכסף והזהב מעפרות כסף וזהב. ולהרמב\"ם ע\"כ גם הכסף והזהב יפסד וישוב אל עפר שממנו לוקח, ואח\"כ יוכלו להפך העפר לכסף כמקדם, ואם יעשו כן פעמים רבים זא\"ז אף לבל\"ג עכ\"ז מוכרח שהכסף מחודש וכ\"ש המטבעות והכלים הנעשים ממנו מאחר שהכסף אינו קדמון באיש, וזה שוה לאם הכסף לא נפסד ועשו ממנו כלים זא\"ז פעמים רבים דהכל מחודש מטעם וטענה אחד שהכסף אינו קדמון באיש כ\"א עשוהו מהעפר.\nך <b>וכיון</b> שיצא לנו שגם באופן השני שהכסף נפסד לעפר וחזרו ועשו ממנו כסף כו' הכל מחודש ולא קדמון, א\"כ הרי התהוות הגופות זאח\"ז מאב ואם זהו עכ\"פ דומה ממש לאופן השני בעשיית הכסף מהעפר, שהכל השתלשלות שוה ממש שהגופות שבו לעפר ואח\"כ חזר ונעשה מהעפר גוף ע\"י מלאכות כמו שמהפכים העפר לכסף ע\"י תחבולות ומלאכות, כמ\"כ כאן מהעפר של הגוף הראשון נכנס בצמח ומזון ובאו למאכל איש ואשתו ונהפכו לדם, ומהדם לזרע ומהם נעשה גוף וכך חוזר חלילה רבות פעמים. ולכן באמת אף גם את\"ל שנעשה ממנו גופות זאס\"ז לבל\"ג ה\"ז ממש כמשל אופן השני מעשיית הנסכא כסף מהעפר שנפסד וחזרו ועשו ממנו לבל\"ג פעמים כנ\"ל, ועכ\"ז הכרחנו שכל עשיות הנסכא כסף מחודש ולא קדמון, מטעם שקדמו העפר, וה\"נ כיון עכ\"פ לכל גוף שהיה בהכרח קדמו העפר, דהרי כל עיקר נקודה זו גורם הספק לומר שכל הגופות מתגלגלים על עפר אחד, דאל\"כ פשיטא שהכל מחודש כנז' לעיל אות ט\"ו, דאם עפר גוף הראשון לא נעשה ממנו גופות אחרים לבל\"ג פשיטא שהכל מחודש ורק הספק משום שהם יאמרו שנעשה ממנו גופות רבים זא\"ז בלי גבול. וכיון שהנקודה הגורם הספר, א\"כ ע\"כ עכ\"פ אף לפי זה העפר קודם לכל הגופים כקדימת העפר להכסף, וא\"כ עכ\"פ מוכרח שכל הגופים שהיו מחודשים, שהרי יש דבר שקדם להם שממנו נעשו הוא העפר, וכמו באופן הראשון של עשיית הכלים מהכסף דשם שנראה בעליל שהכל מחודש ואין לבלבל ולספק על זה, כמו כן באופן השני בעשיית הנסכא כסף זא\"ז מהעפר' וגופות בנ\"א דומים לאופן השני אשר הוא דומה לענין הדין לאופן הראשון בזה שהכל מחודש.\n<b>קיצור.</b> שגם לדבריהם התהוות הגופות זה אחר זה מעפר גוף ישן ע\"י השתלשלות אכילת אב ואם וזיווגם הוא כמשל עשיית נסכא כסף מעפר הבא מהכסף שנפסד ושב לעפר כו', ולכן עכ\"פ כמו שהעפר קדם להכסף כן העפר קדם קדימה זמניית לכל הגופים.\n<b>ואם </b>יאמר האומר אם כן נחזיק מזה אמיתית הראיה שלישית של רס\"ג הנזכר לעיל ח\"א ס\"ך. שכמו שאנו מכריחין שהכסף מחודש מפני שהעפר קדם לו, כמו כן על כרחך המקריים מחודשים שהרי העצם קדם לכל מקרה והרי יש חולקים על ראיית רס\"ג כמש\"ש א\"כ הם ע\"כ יחלקו גם על ראייה זו, אף אתה אמור לו, דהם הבינו שכוונת רס\"ג להכריח שהמקריים מחודשים הוא מטעם אחר אבל לפמש\"כ הרי נראה בחוש שהעפר קדם אל חתיכת כסף הנעשה ממנו וא\"כ יהיו גם דברי רס\"ג שרירין וקיימין.\nךא<sup data-n=\"122\">*</sup> <b>וז\"ל</b> הכוזרי מאמר חמישי סי' י\"ח אמר החבר תחלה<sup data-n=\"123\">*</sup> מה שצריך להעמיד חדוש העולם (פי' יסוד כל השרשים והאמונות הוא בירור חידוש העולם, שהעולם הזה וכל אשר בו נתחדש אחר שלא היה ושאינו קדמון חלילה), ולקיים הדבר בבטול הקדמות (ר\"ל תחלה יבאר שאינו קדמון ומאחר שאינו קדמון ע\"כ הוא מחודש), אם היה החולף אין לו ראשית (ר\"ל מה שחלף מן האישים ומן הזמן) הנה האישים הנמצאים בזמן החולף עד העת הזאת אין תכלית להם (ר\"ל פרט כל מין ומין",[["122","*","<b>ךא</b>: סעיף זה הוא לשון הכוזרי והבא בסוגריים הם קיצור הלשון מפי' האוצר נחמד עם הוספות מכ\"ק אדמו\"ר הצ\"צ."],["123","*","<b>תחלה. . העולם</b>: בדפוסים הנפוצים נוסף: ”(נ\"א תחלה מה שצריך להעמיד החדוש לעולם, הדבור בבטול קדמות העולם)\"."]]],[3000730369,"מצומח חי מדבר כל אשר מוליד בדומה לו, שחלפו והלכו בזמן אשר חלף ועבר לפנינו עד העת הזאת הם בלתי תכלית למספרם, לפ\"ד המין) ומה שאין לו תכלית לא יצא אל הפועל (מספר שאין לו קץ ותכלה אי אפשר שיצא אל הפועל, כמו שאנו רואים שמעכשיו עד סוף כל הדורות אף אם יתקיים לנצח ולעולם אי אפשר שיצא אל הפועל אישים וזמן מספר שאין לו קץ כי אם הכל מספר גבולי. א\"כ כמ\"כ מהחולף עד עכשיו ג\"כ אי אפשר שיצא אל הפועל מספר אישים שאין לו קץ דמאי שנא) ואיך יצאו האישים ההם אל הפועל והם אין להם תכלית מרוב (לדעת המין המאמין בקדמות שיאמר כי כל איש נולד מאיש כמותו וזה מזה אחורנית בלי קץ ותכלה א\"כ יצא בעולם אל הפועל מספר אישים בלי תכלית, וזה אנו רואים שמעתה עד העתיד אי אפשר כלל. כמ\"כ אי אפשר מהחולף עד העתה כנ\"ל, דמאיזה טעם אי אפשר שיצא אל הפועל מעתה עד העתיד נצח סלה ועד רק מספר גבולי זהו מפני שמקיבוץ רבוי חלקים גבוליים לא יתקבץ בלי גבול רק הגבול גדול יותר, א\"כ מניעה זו היא ג\"כ שייך על החולף עד עתה, שאם תאמר שהיו אישים ודורות וזמן בלי גבול, ע\"כ הענין שהחלקים גבוליים הם היו מרובים כ\"כ עד שמהם נתקבץ המספר שבלי גבול, וזה נראה בחוש שהוא שקר גמור. וא\"כ הרי הכל מודים שיש כאן דבר נצחי מתמיד בלי גבול הוא א\"ס ב\"ה, הנה הוא למעלה מהזמן שאין זמנו מקובץ מחלקים גבוליים וכמשנ\"ת באריכות לעיל אות ג'. והנה כמו שאנו רואים שיש לנו ספרים שחוברו מזמן רב כמו חיבור התלמוד בבלי ותלמוד ירושלמי, ומדרש רבה שחוברו ערך זמן יותר מאלף וחמשה מאות שנה<sup data-n=\"124\">*</sup>, וחיבור המשנה שקדם לזה יותר, וחיבור ספר יצירה וספרי הנבואה נביאים וכתובים, שחוברו האחרונים מהם ערך שני אלפים ושלשה<sup data-n=\"125\">*</sup> מאות שנה, והראשונים קדמו יותר הרבה וספר התורה שהוא שלשת אלפים ומאה שנה ויותר. א\"כ לדבריהם אמאי לא נמצא ספר שיהי' מחובר מן זמן מאה אלף שנה או ממילייאן שנה, וגם היה ראוי להיות ספרים שממחברם עד עתה עברו שנים בלי גבול, כי הי' דורות בלי גבול שהם שנים רבים כ\"כ היינו שלשים פעמים בלי גבול שנה, ובודאי הי' חכמים כמו עתה, א\"כ היה מההכרח שימצא ספר, שמזמן כתיבתו וחיבורו עד עתה יש עכ\"פ בלי גבול אחד של שנים או של ימים עכ\"פ, ואף שלא שייך המנין והמספר לבריאת עולם לדבריהם, תצייר מספר אחר כמו שמחברו הי' בזמן יציאת מצרים עד\"מ דוגמא כזו בזמן הקודם. והי' מהראוי שמזמן ההוא עד עתה יעברו ימים עכ\"פ או אפילו שנים בלי גבול, שמתחלה יהי' המנין מילייאן ליצ\"מ ולמחבר ההוא עד שיבוא לבלי גבול, והרי לא נמצא ספר כזה ישן. וא\"כ שלא הי' דפוס ונאבד הספר ישאר העתקה בכתב. ועוד דהיא גופא קשיא אמאי לא היה דפוס דבשלומא כפי האמת שהעולם נברא וימים ידברו ורוב שנים יודיעו חכמה, ע\"כ אתי שפיר שחכמת מציאת הדפוס לא נתגלה עד זמן שנתגלה, שכל מה שמתרבה הזמן מתרבה החכמה המעשיית. אבל לפי שקרותם שכבר עבר זמן בלי גבול, א\"כ לא שייך שבמשך זמן הרב לבלי גבול לא נתגלה זו המלאכה עד עתה, דאמאי לא, וזה גופא ראיה שהעולם מחודש. ועכ\"פ אמאי ליכא העתקה ספר א' בכתב מזמן ההוא הרי זה ראיה ברורה שלא עברו דורות בלי גבול כ\"א בגבול, לכן לא נמצא שום ספר מזמן בלי גבול ומלבד דליכא ספר כזה, אי אפשר כלל שיהיה ספר כזה שיכתוב עליו זמן חיבורו באיזה אופן שתצייר ענין הזמן, ושעתה יהי' מזמן ההוא עד עתה בלי גבול ימים, וכנ\"ל שא\"א שיצא זמן בלי גבול אל הפועל, וכיון שלדבריהם היה מוכרח להיות נמצא ספרים רבים ישינים כאלה, שיהיה ממחברם עדינו זמן בלי גבול ולא סגי בלאו הכי כיון שלדבריהם עולם כמנהגו נוהג מימות עולם, א\"כ היה מחוייב להיות",[["124","*","<b>שחוברו</b>: יותר מאלף וה' מאות שנה. אולי טעות המעתיק הוא (וכן בהוספות) וצ\"ל: וד' מאות [לקמן ע' 250]."],["125","*","<b>אלפים</b>: ושלשה — כנראה צ\"ל: ושני. וכן הוא בהוספות מהד\"ב לחלק זה סי\"ז."]]],[3000730372,"ספרים וחיבורים רבים שעבר עליהם שנים או ימים עכ\"פ בלי גבול. וכיון שזה אינו נמצא, גם מלבד שאינו נמצא אנו רואים שאי אפשר בשום אופן שיהיה נמצא. אף אם נניח שהיה הדפוס נמצא מעולם, אי אפשר שיהיה ספר כזה. כמו שאי אפשר שמשנה העברה ועד עתה עברו ימים בלי גבול, כך אי אפשר שיהיה חיבור וספר שממחברו עד עתה עברו שנים או ימים בלי גבול, אף אם היה הדפוס מצוי. וכיון שלדבריהם הי' מוכרח שיהיה נמצא ספר כזה, ולא ספר אחד אלא ספרים רבים. ואנו רואים שזה אינו נמצא ואי אפשר שימצא. א\"כ זהו ראיה ומופת שלא היו דורות ואישים כי אם בגבול, ושהעולם מחודש.) ואין ספק כי לחולף ראשון ולאישים הנמצאים מספר, יגיע אל תכלית (היינו ע\"כ שיש להמין הנחלף ועבר ראשון ד\"מ אדם הראשון יציר הבורא ית' וממנו התחילו בני אדם לרוב על פני האדמה ומעתה לכל אישי הנמצאים מאז ועד עתה ג\"כ דהיינו מבריאות עולם ג\"כ מספר) כי בכח השכל למנות אלפים ואלפי אלפים כפולים עד לאין תכלית זה בכח אבל שיצא<sup data-n=\"126\">*</sup> אל גבול הפועל לא, כי מה שיצא אל גבול הפועל ונמנה אחר כן המנין היוצא אל הפועל יש לו תכלית בלי ספק, ומה שאין לו תכלית איך יצא אל גבול הפועל.\n<b>קיצור </b>שאם היה החולף והעבר של העולם אין לו ראשית, א\"כ דורות האנשים הנמצאים בזמן החולף אין תכלית להם, וזה אי אפשר שיצא אל הפועל, עד שיגיע ההויה אצלינו כי בכח השכל למנות אלפים ואלפי אלפים כפולים לענין שלא יופסק המנין מלמנות עוד ועוד אבל שיצא אל גבול הפועל מנין בלי גבול זה לא אפשר. ועמ\"ש מזה לעיל אות ב' בשם רס\"ג.\nךב<sup data-n=\"127\">*</sup> <b>אם </b>כן לעולם התחלה, (אמור מעתה שלעולם היה עת חדושו וכל התולדות שלפנינו כך נבראו בקומתן ובצביונן) ולסבובי הגלגל מספר מגיע אל תכלית. (כשם שעולם השפל וכל מה שבארץ נבראו כך הגלגלים וכל צבאם נבראו שאל\"כ ע\"כ שתאמר שיהיו כך מתנועעים בלי התחלה הרי הגלגלים נותנים קצבה לזמן החולף ועובר הרי שחלפו ד\"מ ימים בלתי תכלית וזה אי אפשר. כ' המפרש האוצר נחמד וז\"ל וזאת הראיה נשענת על דברי אפלטון שאמר כאשר תחודש בכאן תנועה לא היתה הנה לא ימלט אם שתהיינה התנועות אשר לפני זו התנועה אין התחלה להם. ואם שתהיה להם התחלה, ואם שלא היה להם התחלה הנה מציאות זאת התנועה הרמוז אליה, מגונה. ר\"ל התנועה שלפנינו עתה<sup data-n=\"128\">*</sup>. וזה כי היו אלו התנועות אשר כבר ימצאו לא ימצאו עד שיכלו לפניהם תנועות אין תכלית להם ושלימות וכליון מה שאין לו תכלית מגונה עכ\"ד. וזאת דעה קדמונית. ועם היות שהבאים אחריו השיגוהו ואמרו מאחר שהתנועות לא יעמדו יחד רק תבא זאת אחר סור זאת אין זה שלימות וכליון לבלתי תכלית כבר כתבתי שהחבר לא נמנע להעביר לפני הכוזרי כל הנאמר בזה מימי עולם ומשנים קדמוניות והוא יבחר יקרב את הקדוש והמבורר שאין עליו תשובה. ומ\"ש כבר כתבתי<sup data-n=\"129\">*</sup>, זה לשונו לעיל מיניה. ועם היות שהמורה בפרק ע\"ד מחלק ראשון, העביר לפניו אלו המופתים אשר התחיל בהם החבר והשליכם מעל פניו וכנה אותם למופתי אנשים מדברים ר\"ל כמדבר ולבו בל עמו, עכ\"ז לא מנע החבר להזכירם לפני הכוזרי כולם מחמת שאלתו, למען יבחר יקרב האוכל והמובחר שבהם כי הנה המופת מצד אישי המין וכפי אשר סיים בו בסוף הפרק הוא חזק מכל חזק וכל טענות שזכרו המורה לא יצליחו עדו כפי אשר יתבאר. ואף גם שאר המופתים שזכר בזה כבר יצא הרלב\"ג בששי ממלחמותיו לנתוץ טענת המורה שזכר שם ולהעמידם על תלם. ר\"ל להעמיד",[["126","*","<b>שיצא</b>: בדפוסים הנפוצים: שיוציא אותו."],["127","*","<b>ךב</b>: סעיף זה המשך לשון הכוזרי דלעיל סי' כא."],["128","*","<b>עתה</b>: באוצר נחמד, כאן הסוף מוסגר."],["129","*","<b>ומ\"ש כבר כתבתי</b>: זהו ביאור מכ\"ק אדמו\"ר הצ\"צ."]]],[3000730375,"המופתים ע\"ד החדוש, ושהזמן נברא ומחודש, ע\"ש מפרק יוד עד סוף פרק י\"ב. מלבד המופתים שהביא שם על חידוש העולם מפרק שישי עד סוף פרק תשיעי. ועיין מ\"ש ע\"ז בספר נוה שלום מאמר ראשון פרק אחד עשר. ולפע\"ד ג\"כ המורה פרק ע\"ד הנ\"ל לא הביא כלל הטענה שאמר החבר ומה שאין לו תכלית לא יצא אל הפועל, ואיך יצאו האישים הנ\"ל אל הפועל, רק הביא מ\"ש החבר לקמן ומזה כי מה שאין לו תכלית אין לו חצי ולא כפל כו' ואנחנו נדע כו'. זה לבד הביא, וע\"ז השיג. אבל על הטענה הראשונה לא נמצא תשובה בדבריו. וכמ\"ש מזה לעיל אות ג). ומזה כי מה שאין לו תכלית אין לו חצי ולא כפל (ר\"ל עוד יש מאלו מופתים כי מה שאין לו תכלית אי אפשר ליקח החצי ממנו שהרי אין לו תכלית ואיזה מספר יהיה חציו וכן אי אפשר לכפול אותו אחר שאין לו תכלית מה יועיל בו הכפל הרי לא יתרבה), ולא ערך מספרי (כגון שלישי או רביעי וכדומה לו) ואנחנו נדע כי סביב גלגל השמש חלק משנים עשר מסבובי הירח. (ר\"ל אם נתן לב אל כל הסבובים והתנועות שעשו הגלגלים לדעת המין והם בלתי תכלית. ומאחר כשהשמש גומר פעם אחת דהיינו בשנה, הירח גומר גלגלו בזמן ההוא בכמו י\"ב פעמים דהיינו בכל חודש) וכן שאר סבובי הגלגלים קצתם אל קצתם (ד\"מ מאדים בשש שנים צדק בי\"ב שנים שבתאי בשלשים שנים ויש ערך לזמן סבוב קצתם אל קצתם) ויהיה זה קצת זה. (כלומר מספר הסבובים שעשה שבתאי הם פחותים ממספר הקפות של צדק, ושל צדק משל מאדים ומאדים משל חמה, וכולם פחותים משל ירח, ויהיה מספר הפחותים קצת מן המרובים) ואין במה שאין לו תכלית קצת, (איך שנאמר ד\"מ שסבובי השמש הם קצת מסבובי הירח הרי גם לסבובי השמש אין תכלית למספרם ואיך נאמר עליהם קצת. ובפשיטות יותר היינו עד\"מ ששנים הם בלי גבול, היינו סבובי השמש, וחדשים הם שנים עשר פעמים בלי גבול, שהם סבובי הירח, וימים הם שס\"ה פעמים בלי גבול. א\"כ יש בלתי בעל תכלית אחד רב מחבירו וזה אי אפשר) ואיך ישוב זה כמו זה (איך יתכן שישוה השמש עם המרובה ממנו ועם הפחות ממנו וכל אחד מהם בלי תכלית והרי כולם שוים כי אפשר שיהיה בלתי בעל תכלית אחד גדול מבלתי בעל תכלית חבירו). ובן גילו אין לו תכלית והוא קצת ממנו או גדול ממנו רוצה לומר שהוא יותר מספר או פחות מספר. (ועל ראיות אלו השיב המורה ס\"פ ע\"ד מחלק א'. וביאר דבריו ה\"ר ש\"ט ועמ\"ש תשובה על תשובתו לעיל סוף אות ג')<sup data-n=\"130\">*</sup>.\nךג<sup data-n=\"131\">*</sup> <b>ומזה </b>איך הגיע מה שאין לו תכלית אצלנו, אם היה לפנינו מן הברואים מה שאין תכלית למספרם, איך הגיע המספר אלינו. (לכאורה הוא ענין אחד עם מה שאמר בתחלת דבריו ומה שאין לו תכלית לא יצא אל הפועל כו'. אך באמת אינו כן ושני דברים הם האחד מה שלדברי המין צריך לומר שיצא בעולם אל הפועל מספר אישים בלי תכלית, וזה אי אפשר. והיינו אף בדברים שאין זה מקור שלאחריו כמו בתנועת הגלגל, היינו בענין הימים. והטעם השני הוא איך הגיע ההתהוות אצלינו, וכמ\"ש רס\"ג מאמר א' ד\"ה והראיה הרביעית, וז\"ל ידעתי כי ההויה עברה על הזמן עד שהגיע אלי. ולולי שהיה הזמן תכלית לא היתה ההויה עוברת בו עכ\"ל. וז\"ל האוצר נחמד הפעם הראה החבר כל אותותיו וזה המופת הוא שריר וקיים אי אפשר לדחותו והוא מוסד על הקדמה אחת מה שאפילו בעלי הריב מודה בה שאע\"פ שאפשר ויכול להיות תנועות בזה אחר זה ר\"ל בזה אחר סור זה בלתי תכלית מאחר שהבלתי תכלית אינו נמצא יחד. עכ\"ז הכל מודים שאי אפשר ולא יתכן שימצא בפועל וביחד רבוי בלתי תכלית לו. שמאחר",[["130","*","<b>אות ג')</b>: בגוכתי\"ק יש מקום חלק לכתוב קיצור."],["131","*","<b>ךג</b>: המשך לשון הכוזרי דלעיל. וראה גם לעיל ל, א."]]],[3000730378,"שיצא אל גדר הפועל ע\"כ יש לו תכלית. והמורה גם הוא הסכים להקדמה בראש ח\"ב (בד\"ה והקדמה השנית. והרש\"ט הביא מופת ע\"ז והוא עצמו המופת שכ' הח\"ה בשער היחוד פ\"ה גבי וברור ההקדמה השנית כו' ואם נעלה במחשבתינו דבר שאין לו תכלית בפועל כו' ע\"ש), והחסיד בעל ח\"ה ביארה במופתים בפ\"ה משער היחוד, ואין צורך לבארם הנה מאחר שאין מחלוקת בזה. ומעתה יתבאר מצד אישי המין הנמצאים לפנינו מאדם ובהמה וצמחים שהם נמשכים בזרעם ותולדותם שעל כרחך יש ראשון לכל אחד מהמינים אשר לא נולד מאשר שלפניו, שאלו תאמר שכך נתהוו אחורנית זה מזה עד בלי ראשית ותכלית הרי א\"כ אלו האישים הנמצאים לפנינו הוצרכו לכל אותן שלפניהם ושלפני פניהם עד בלי קץ, נאמר לבעל הריב אלו חסר אחד מכל המין הרבוי העצום לפני אלף או אלפים דור מן אבות או אמות משל כל אחד מהאישים שלפנינו הימצאו כל המון הנולדים שלפנינו. על כרחך שיאמר לא, כי היה נפסק שלשלת התולדה בכל אחד. א\"כ כל אותו ההמון העצום הבלתי תכלית צריכים לאישים שלפנינו לתולדתם הרי שהודית בלתי בעל תכלית בפועל מאחר שכל אחד ואחד מהאישים לא היה יוצא לגדר הלידה זולת עזר בלתי תכלית שלפניו. ומאחר שאי אפשר שיושלם בלתי בעל תכלית, ויצא דבר מבלתי בעל תכלית אנה נמצאו האישים שאנו רואים. וזה שאמר איך הגיע המספר אלינו, כלומר מאין אנו רואים לפנינו המון תולדות הנמצאות עכ\"ל) וכאשר יהיה לדבר תכלה אי אפשר לו מבלי התחלה ואם איננו כן יהיה כל אחד מן האישים צריך במציאותו להמתין למציאות אישים לפניו אין להם תכלית, (ר\"ל שאל\"כ היה כל אחד שנולד לפנינו צריך להמתין עד שעברו אישים בלתי תכלית לפניו. ומאחר שזה אי אפשר שיצאו לגבול הפועל מספר בלתי בעל תכלית. א\"כ לא היה נמצא שום איש, והרי נמצאים לפנינו) ולא ימצא איש. ועיין מ\"ש לעיל אות ב' ביארתי דברי החבר שהראה הכרח מורגש לחוש יותר ממה שפי' האוצר נחמד בדבריו. ועל דברי האוצר נחמד יש מי שחולק כמו שיתבאר משא\"כ מה שביארתי שם סעיף ב' אי אפשר לדחותו כלל כ\"א להקשות על זה דגם לדידן אינו מובן. וכבר נתבאר שם ישוב נכון על זה אות ד' ה'. ע\"כ דברי החבר חזקים כראוי מוצק כמ\"ש האוצר נחמד, ולא מטעמיה לבד. ומ\"מ דברי האו\"נ ג\"כ נכון וחזק, כמו שיתבאר אי\"ה.\nךד <b>והנה </b>לכאורה בעל מנוח הלבבות בפירושו לח\"ה פ\"ה משער היחוד חולק על דברי האו\"נ, במ\"ש הרי שהודית בלתי בעל תכלית בפועל כו', שהרי הוא כתב וז\"ל ואף כי מציאות עלות ועלולים לבלתי בעל תכלית אפילו שימצאו בזה אחר סור זה שקר מ\"מ מה שנתחדש תמיד זה אחר זה על החומר הראשון אף שיומשך זה מזה ויהיה זה עלה כאלו אמרת ראובן בן יעקב ויעקב בן יצחק אל לא תכלית לא נקרא זה עלות ועלולים לבלתי תכלית שהרי יש להן תכלית כי תכלית כולם הוא החומר הראשון ובו יתחדש כל מה שיתחדש ויחזור חלילה בתנועה סבובית, כמו שאמר המורה בהקדמת ח\"ב בהקדמה כ\"ו באמרו שם ולפי זאת ההקדמה יהיה המתנועע בעל תכלית מתנועע על אורך בעל תכלית פעמים אין תכלית להם בחזור על האורך ההוא חלילה עכ\"ל, ועלת חומר הראשון הוא הש\"י הרי שיש תכלית לעלות עכ\"ל בעל מ\"ה. ולכאורה טענת האו\"נ דלעיל הוא שמדמה אישי המין לעלות ועלולים. וע\"ז חולק מ\"ה משום דבעלות ועלולים הטעם כי אם לא היה העלה הראשון נמצא לא היה האחרון נמצא. וכיון שהאחרון נמצא ע\"כ שהראשון נמצא. משא\"כ באישי המין ס\"ל דלא שייך לומר כן כי אף שאין הראשון נמצא עכ\"ז האחרון נמצא כי סמיכתו הוא על חומר הראשון. אך נראה דכוונת האו\"נ"],[3000730381,"אינו מצד שמדמה לעלות ועלולים כו', כי אם דעכ\"פ מוכרח כאילו כל אישי המין הם בפועל, מאחר שכולם צריכים לאישים שלפנינו כו', ושיהיו יחד בפועל אי אפשר אפילו אינן עילות זה לזה. גם בלאו הכי החילוק שכתב המ\"ה בין אישי המין ובין עלות ועלולים הוא חלש מאד ואין בו כדי חלוקה. וגם קצת מהמופתים שהביא ע\"ז הרש\"ט בהקדמה ג' כי יתחייב מזה שיהיה החלק כמו הכל כו' זהו שייך ג\"כ על אישי המין, וכמ\"ש בח\"ה שם וכשנחלק כו' מן האישים מימי נח כו' ע\"ש. אלא שהרש\"ט שם חילק ביניהם בזרוע וע\"פ מה שמאמין באמונה יתירה בדברי תלמידי ארסטו, ולא ע\"פ שכל. עוי\"ל דכוונת האו\"נ דמדמה זה לעלות ועלולים ממש וכמ\"ש בפירושו לח\"ה שער היחוד פ\"ה ס\"ק י\"ד ומ\"ש מ\"ה דשאני הכא דיש להן תכלית היינו החומר הראשון ועלת חומר הראשון הוא הש\"י הם דברי הבל ורעות רוח שהרי האנשים אינן מתהוים מהש\"י כ\"א ע\"י מיצוע אב ואם דוקא לשטתם. והרי האב ואם אין להם תכלית. וא\"כ אין להם על מה שיסמכו, שהרי לשטתם בלי אב ואם א\"א להם שיתהוו מהשי\"ת כו' וה\"ז ממש כמו בעלה ועלול.\nךה <b>ועוד</b><sup data-n=\"132\">*</sup> יש להוסיף לחזק דברי האו\"נ בענין המופת מצד אישי המין שהוא שריר וקיים ולחלק בינו ובין הזמן אף לדברי בעל הריב, והוא כי על כרחך בכל גוף איש ואיש יש בו חלק ממשי מאביו ואמו. וא\"כ ודאי בהכרח שמכל הדורות שחלפו יש חלק מעט מזעיר בכל איש, שהרי ע\"כ מאב ואם יש חלק מה בהבן, והדורות שחלפו הן אבות ואמהות לאישים שלפנינו. ואם כן אם תאמר שהאבות ואמהות שלפני האישים שלפנינו היו בלי תכלית, א\"כ החלק שבאיש מאבות ואמהות שלו, נתחלק לחלקים בלתי בעל תכלית שהרי מאם שלו שעברו בינה לבינו דורות בלי תכלית א\"כ החלק שנמשך ממנה בבנה או בתה הסמוכה לה עד שהגיע לאיש של עתה בהכרח זהו שנתחלק חילוק אחר חילוק פעמים אין תכלית. וכבר הסכימו הכל שא\"א שיתחלק איזה גשם לחלקים בלתי בעל תכלית בפועל. ובאור הדבר כי הנה הבן הנולד מטפת האב שהוא דבר גשמי עכ\"פ א\"כ יש בו חלק גשמי מאביו, מלבד שבהטפה נמשך הכח מכל הרמ\"ח איברים וכמ\"ש הרמב\"ם<sup data-n=\"133\">*</sup> שכבת זרע היא כח הגוף ומאור העיניים כו', ובבטן האם נעשה ממנה ולד ואז עדיין עובר ירך אמו הוא ממש, פ\"ג דחולין דף נ\"ח ע\"א ופ\"ה דב\"ק דף מ\"ז ע\"א דגופה היא, ואין צריך ראיה, כי נראה בחוש שהוא חלק מגופה ממש, והוא קודם גמר לידתו משקלו ערך חלק אחד מארבעים או פחות ממשקל וכמות גוף האם. עכ\"פ הלא דבר הוא חלק מה מגופה ממש. א\"כ גם לאחר שנולדו ונפרד להיות בריה ודבר בפני עצמו, עכ\"ז א\"א להכחיש שהוא חלק מהאם ממש, מה שמתחלה היה החלק צפון במעיה ואחר זה יצא ממנה ונתחלק ממנה, וכמרגלא בפומיה דאינשי, כי ברא כרעא דאבוהו הוא. ובח\"ה שער ג' בהקדמה כי הבן נתח מהאב. והנה אח\"כ כשנתגדל הבן עד שנוסף עליו בשר וגידים ועצמות עוד ל\"ט פעמים כמו שהי' עד\"מ והיה כמו אמו ואביו, עכ\"ז היסוד שלו הוא החלק אחד מני ארבעים שנולדה בו רק שזה החלק הוא הולך וגדל. וכשזו הבת הולידה בן שזה הבן הוא ג\"כ חלק אחד מארבעים מגופה, על כרחך יש בו ג\"כ חלק א' מני ששה עשר מאות מאם אמו.\n<b>ועוד </b>א\"כ יש בכל אדם חלק מעט מזעיר מכל אביו ואמו שחלפו. א\"כ הרי זה כולם קיימים באיש היינו לומר כי גם מהדור היותר מוקדם ישנו גם עתה בדור שלפנינו חלק משהו ממנו ממש. כמש\"ל כי הבן והבת יש בהם ממש חלק מגוף אביו ואביו, ויותר ניכר מהאם שהוא חלק ארבעים ממנה כנ\"ל. א\"כ גם אחר",[["132","*","<b>ועוד יש להוסיף</b>: ראה לקמן ע' 246."],["133","*","<b>מאביו</b>: הרמב\"ם — הל' דעות פ\"ד הי\"ט ושם הל': כח הגוף וחייו ומאור כו'."]]],[3000730384,"שנעשה בריה בפני עצמו ואמו מתה עכ\"ז בבן הזה יש חלק מגוף האם ממש שהוא כל עצמו של הבן הזה שעיקרו הוא רק אותו חלק אחד מני ארבעים מגוף האם רק שנתגדל יותר, א\"כ הוא כאמו ממש לענין הנזכר לעיל שיש לומר על אמו שהיא קיימת באיש, היינו בן זה שהוא חלק מגופה ממש. דמה לי גוף האם כולו או חלק ממנה, אשר מהגוף של האם ממש כמו שהיתה בזמן העיבור של זה הבן, נשאר גם עתה חלק קיים באיש ממש הוא הבן. והנה גם אמו של הבן או הבת הנ\"ל היתה עד\"ז חלק מגוף אמה. א\"כ גם זה הבן יש בו ממש חלק מאם אמו כי אמו היתה חלק אחד מארבעים מאם אמה כו'. א\"כ יש בגוף הבן חלק מאם אמו ממש. ועד\"ז עד כל הדורות שלפניו יש בו חלק משהו דמשהו מגופם ממש, בלתי אפשר להכחיש זה, וזה המשהו עומד בפנינו ממש, תוך גוף זה, תמעיט המשהו מאי דאפשר, עכ\"ז אינו אין ואפס ממש כ\"א יש משהו. א\"כ כל הדורות שעברו יש משהו גם מהיותר קדמון בגוף של כל אחד מהדורות דעתה, וזה המשהו דמשהו שלפנינו, נשאל עליו אם הוא מחודש או קדמון, ובעל כרחך תשיב שהוא מחודש, שהרי הכל מודים שכל האישים וכל הדורות שהיו, היו מחודשים, אלא שאתה מקיש אותם לרגעי הזמן, לומר שהמין קדמון. אבל אם היו הדורות כולם קיימים באיש, היו הכל מודים שגם כל המין מחודש ולא דמי לזמן, והיה החידוש נראה בעליל לעין כל. וא\"כ כיון שבדור זה יש בפועל משהו דמשהו מכל הדורות שעברו, לא נעדר אחד מהם. א\"כ ה\"ז כולם קיימים באיש, וכולם מחודשים אחר ההעדר, שבהכרח גם כל המין כולו של אנשים מחודש, גם הנה כח הראיה וכח השמיעה שבבן בא ונמשך מהאב כמדליק נר מנר, ובהאב מאבי אביו כו' א\"כ כח הראיה הזה יש בו ממש הארה והמשכה מכל הדורות שהיו לפנינו. הרי א\"כ יש כאן כח הראיה של הדור היותר מוקדם, עד שנוכל לומר כאלו כל הדורות שעברו קיימים באיש, מאחר שנשאר רושם וכח מהם ממש, וזה ע\"ד מ\"ש לעיל אות כ\"ג בשם האוצר נחמד בפי' הכוזרי מאמר חמישי סי' י\"ח ספ\"א גבי הרי שהודית בלתי בע\"ת בפועל כו' ע\"ש. אלא שע\"ז י\"ל שאין כח הראיה של הדור היותר ראשון עומד בפ\"ע כי אם זהו הארה דהארה ממנו. מ\"מ עכ\"פ זהו מחובר ואדוק יחד עם כל הדורות עד עתה, ע\"ד שנזכר לעיל אות י\"ז. ואף לפ\"ז הכל מודים שהכל מחודש. וכמו שא\"א להיות עלות ועלולים בלי תכלית, כמ\"ש המורה ח\"ב פ\"א בהקדמה השלישית. שאף שכתבתי לעיל אות כ\"ד שבעל מנוח הלבבות חילק בין אישי המין ובין עלות ועלולים כו', הנה חילוקו הנ\"ל שייך רק על הגשמיות של הגוף לומר כי תכלית כולם הוא החומר הראשון. דאף שבלא\"ה חילוקו חלוש מאד, עכ\"ז נ' שעל הרוחניות שבגוף היינו כח הראיה כח השמיעה וכ\"ש כח השכל, אינו שייך לומר כי תכלית כולם הוא החומר הראשון, שהחומר הוא גשמי ודומם, והכוחות שבגוף הם כוחות רוחניים, שכליים. עכ\"ז דומים לעלות ועלולים, שמציאות עלות ועלולים, לאין תכלית הוא שקר לכל הדיעות.\nכו <b>במ\"נ </b>ח\"א פע\"ד הדרך הראשון שאיזה ענין שימצא לגשם אחד יתחייב שידונו בה על כל גשם עכ\"ל, והש\"ט כ' וכש\"כ אם יקרא האדם עולם קטן. וע' מענין שהאדם הוא עולם קטן בחובת הלבבות שער הבחינה רפ\"ה. והנה הרש\"ט כאן סיים וזה הדרך הוא חלוש מאד כו', ולא דק, כי גם אם נודה לו שאין לדון ולעמוד יסוד מאיש אדם א' על כל העולם, דהיינו שאין לדמות גשם אחד לגשם אחר אך נלך בזה בסדר והדרגה, מתחלה נדון שיש להביא ראיה מאיש אדם אחד על מין האדם כולו, שהרי הם אישים שוים, וגשמיים ורוחניים שוים"],[3000730387,"ממש, ונאמר שכמו שאישי ראובן ושמעון הם מחודשים אחר ההעדר, כמ\"כ בודאי על כל מין האנשים מחודש אחר ההעדר, מה גם שאף לדברי בעלי הקדמות מודים שכל פרטי האישים שהיו מהעולם עד עתה כולם מחודשים, אלא שיתעקשו שמ\"מ מין האנשים קדמון, אף שכל פרטי האישים אין בהם אחד שלא יהי' מחודש. וא\"כ ע\"ז ודאי קרוב מאד לסמוך על ההקש הלז שאיזה מין שימצא לכל האישים כולם, יתחייב שידון כן על כל המין אנשים, ור\"ל כיון שמוכרח שכל האישים שהיו היו מחודשים, א\"כ נחייב כן בהקש שכמ\"כ כל מין אנשים בכללו מחודש. ודרך זה אינו חלוש כלל, כי אם בריא וחזק, כראי מוצק, להקיש המין כולו, לכל האישים, שאין זה הקש מגשם אחד לבד, כ\"א מכל הגשמיים כולם של כל המין, מקישים כולם להמין. ואין לך הקש קרוב ואמיתי יותר מזה, כי גם בלאו הכי אין השכל מקבל שאע\"פ שכל האישים כולם היו מחודשים, יהי' המין קדמון, ואיך מקיבוץ מחודשים יתהוה הקדמות. ע\"כ ההקש מכל הגשמיים הפרטיים על המין כולו הוא דבר הגון ומתקבל. וכן תעשה ההקש בכל בעלי חיים, שמאחר שכל פרטי האישים שהיו כולם מחודשים, יש להקיש שכמ\"כ כל המין מחודש, ואפ\"ל כמ\"כ במיני הצמחים. וא\"כ נרויח מזה הקש קרוב למופת, שמין צומח חי מדבר נתחדשו אחר ההעדר. ומכולם יחד קרוב להקיש, שכמ\"כ כל העולם השמים והארץ הם מחודשים, כאשר בלא\"ה מוקצה מן הדעת שהשמים והארץ יהיו זמן בלי תכלית בלי צומח חי מדבר. ואח\"כ נתחדשו אלו מזמן בעל תכלית, אלא ודאי הכל מחודש, וא\"כ הקש זה הוא מוסיף על שאר המופתים שהעולם מחודש.\nכז <b>במ\"נ </b>ח\"ב פכ\"ב ועם הודאתינו לו בזאת המחשבה והסברא, איך היו השכליים סבה לחיוב הגלגלים מהם, ואיזה ערך בין החומר והנבדל אשר אין לו חומר כלל עכ\"ל. ור\"ל שהתהוות הגשמיות מן הרוחניות אין לך התהוות יש מאין ואפס, ודבר מלא דבר, גדול מזה, וא\"א שיהי' ע\"י השתלשלות עילה ועלול בשום אופן, וכמ\"ש אאזמו\"ר נ\"ע באריכות בת\"א בד\"ה יביאו לבוש מל', ובאג\"ה בד\"ה איהו וחיוהי. וא\"כ זו תשובה שהשיב הרמב\"ם ע\"ד אריסטו המאמין בקדמות, ושהעולם כצל מהשם ית', הלא גם לדבריו ע\"כ צריך להודות בהתהוות יש מאין ממש, מה שנתהווה גשמיות העולם מהרוחניות. וא\"כ לא הרוויח כלום על אמונת החידוש יש מאין, שגם לשטתו צריך להודות בהכרח בהתהוות יש מאין. וא\"כ יקל זה יותר לפי האמת שהעולם נתחדש אחר ההעדר, בכוונת מכוין, שהרי זה היכולת לברוא יש מאין, הוא יכולת בלתי בעל תכלית, רק הכל יכול, הוא הבורא הקדמון, ולא שייך יכולת זה רק בכוונת מכוין שהוא בורא ופועל, ומראה כחו ויכלתו הבבע\"ת. לא כן לפי שטות אנשי הקדמות שהעולם נמשך ממילא ממנו ית' כצל מהשמש, איך יצייר זה שיומשך בחי' צל מה שאין ערוך כלל להמקור, ולא יועילו לזה אלף אלפים השתלשלות, כ\"א יכולת בבע\"ת, איך יהי' כ\"ז בלי כוונת מכוין. ומ\"ש הרש\"ט כל אלו הבטולים כו' יתחייב ג\"כ לדעת החידוש כו' לא דק כלל, כי בכוונה שאני כמ\"ש הממני יפלא דבר, הלא אין ערוך כלל בין בע\"ג לבלתי בע\"ג, מהבורא הבלתי בעל גבול, הלא אין ערוך כלל בין בע\"ג לבלתי בע\"ג. ואלו היו נמשכים ממילא כמו האור הנמשך מהשמש, וכן הצל מהמיצל, היו ראוים שיהיו ג\"כ בלתי בע\"ת, ואיך יהי' הזיו והצל בע\"ג, מהמקור הבבע\"ג, אע\"כ שהי' בכוונת מכוין שהוא הכל יכול, וכמ\"ש בע\"ח בענין הצמצום שצמצם האור כו', ועיין בספר נוה שלום מאמר א' ס\"פ י\"ג שבזה נשתבש חכם א' מישראל, באמרו שאין אמונת חדוש העולם עקר לתורה, כיון שאפילו לדעת מאמיני הקדמות יוכרח להם להודות בריאת"],[3000730390,"יש מאין מאחר שנתבאר גם לשטתם שאין שום דבר מחוייב המציאות מצד עצמו. אלא השם יתברך לבד הוא המחוייב המציאות מצד עצמו, ושכל הנמצאים זולתו, נאצלו ממנו. א\"כ אף שיהיו קדומים כבר נודה בהכרח על מציאות גשמי, נאצל מצורה רוחניות, והצורה ההיא אם כן מאצילה ונותנת מה שאין דומה לה, והיינו בכח המחוייב המציאות מצד עצמו. וזהו ענין התהוות יש מאין כו' שמוכרח אף לדעת מאמיני הקדמות. וע\"כ נשתבש לחשוב שאין חדוש העולם אחר ההעדר עקר לתורה. והמחבר נוה שלום שם פרק י\"ד סתר דעתו לגמרי, איך שהחדוש הוא עקר לתורה, מלבד מה שביאר תשו' הרמב\"ם על אריסטו כנ\"ל:\n<b>ועיין </b>בעקרים מאמר ראשון פי\"ב וע\"ש פכ\"ג מ\"ש ואיך יהי' השכל הנבדל עלה למציאת החומר כו' אין לך יש מאין גדול מזה כו' עכ\"ל ופי' המפרש שר\"ל שא\"כ בנקל להאמין אמונת חדוש יש מאין לגמרי אחר ההעדר, כיון שלכל הדיעות מוכרח זו דהתהוות יש מאין כנ\"ל, וא\"כ אמונת התהוות יש מאין מקדם רחוק וקשה יותר לקבלו מלבד הראיות גדולות המכריחות חדוש העולם.\n<b>ועיין </b>מזה ג\"כ בכוזרי סי' א' בהמפרש א\"נ שם דף ד' ע\"ג וכי החומר העכור וכו' יהי' אור מא\"ס ב\"ה וזיו ממנו כו' ויהי' הזיו כך רחוק במדרגה, וע\"ש עוד סוף העמוד. כח ז\"ל הכוזרי מ\"א סי' נ\"ג אמר החבר האתה רואה שהלשונות קדומות אין להם תחלה עכ\"ל וכ' המפרש החבר הוסיף אומץ לבאר חדוש העולם אף בזולת דרך המקובל שזכר עד כה. ואומר האתה רואה שהלשונות קדומות ר\"ל אם יש מקום לשכל שיאמין. כי כל הלשונות אשר בכל עם ועם כך היו מעולם בלי התחלה. רק הטבע המחייבת סדר התנועות וההרגש לאדם, היא המחייבת הלשון. וכמו שישתנה תואר כל עם לפי מושב ארצם בטבע הארץ ההיא, כן ישתנה הלשון והכל מעצמם בטבע, ויאמרו מאמיני הקדמות שכך היו הלשונות מעולם בלי התחלה עכ\"ל.\nנ\"ד<sup data-n=\"134\">*</sup> <b>אמר </b>הכוזרי אבל הם חדשות (פי' אין מקום להסתפק בזה כי ודאי שהיה עת נתחדשו הלשונות ההם לכל עם ועם אחר שלא היו מקודם), מוסכם עליהם (פי' אין כאן ענין שימשוך בטבע ויהיה איזה טעם או ריח להנחת הלשון באופן זה מלבד שכך הסכימו), מורה על זה חבורם (פי' הראיה על זה חבורם<sup data-n=\"135\">*</sup> חבור חלקי הלשון בבינה והשכל בשלשה חלקים) השמות והפעלים והמלות (פי' השמות שם דבר מה כמו שמים וארץ. שאין שום סכל בעולם שידרוש טעם לזה בכל לשונות העמים על מה נקרא בשם זה ורק שכן הסכימו עכ\"ל המפרש. ולכאורה אף אם ההסכמה היה מחמת איזו טעם ג\"כ מוכרח שהלשון חדש, שהסכימו כן מחמת איזו טעם, כמו שארז\"ל במד\"ר פ' בראשית ס\"פ ד' בענין שמים שהם אש ומים או ששמים מעשיהן של בריות. וע' פרדס תחלת שער האותיות, ובשל\"ה במקום שהביא דברי הפרדס. מיהו כ\"ז בלשון הקודש לפי שבו נברא העולם אבל בשאר ע' לשון ודאי גם השמות כולם רק הסכמיים, כמ\"ש הפרדס והשל\"ה שם<sup data-n=\"136\">*</sup>: והפעלים, כמו אכל בנה שמר והדומה להם, והמלות, הם מלות קצרות המחברים והמורים הכוונה כמו שמור לי אוכל זה) והם מן האותיות הלקוחות ממוצאי הדבור עכ\"ל<sup data-n=\"137\">*</sup>. (ר\"ל נראה כי הוא מסודר במלאכת מחשבת שנראה הלשון מחובר מחמש מוצאים שהניחו המדקדקים. ואלו היה בטבע לא היה בכל תיבה רק בתנועה אחת כמו א „א או במדרגת צפצוף או בהדרגת הנגון בלי חתוך אותיות והכל ממוצא הגרון והאדם כסוס עגור יצפצף יהגה כיונה וע\"כ נעשה בהסכמה לסדר הלשון באופן קל ומובן עכ\"ל).\nבשולי הגליון בגוכתי\"ק: ע' בד\"ה ויעש דוד מענין האותיות. ע' מלחמות<sup data-n=\"138\">*</sup> מאמר שישי דנ\"ח ע\"ד ביאר ראיה זו ביתר שאת.",[["134","*","<b>נד</b>: סי' נד בספר הכוזרי. והבאה בסוגריים הוא לשון האוצר נחמד."],["135","*","<b>חבורם</b>: תי' זו הוא מלשון הכוזרי."],["136","*","<b>והשל\"ה שם</b>: לכאורה צ\"ל כאן סוף מוסגר, שתי' ”והפעלים\" הוא מלשון הכוזרי."],["137","*","<b>עכ\"ל</b>: מהכוזרי."],["138","*","<b>מלחמות</b>: לתועלת המעיין נפדס בהוספות ע' קפ."]]],[3000730393,"<b>קיצור.</b> שהכריחו שהלשונות היה להם עת שנתחדשו בהסכמה מבעלי מחברי הלשון, ואינן קדומות. \n<b>סי' נ\"ה</b><sup data-n=\"139\">*</sup> אמר החבר הראית בודה לשון מלבו (וכתב המפרש, החבר חכה להמלך בדברים ואמר לו מאחר שנתבאר שאין הלשונות קדומות לכו<sup data-n=\"140\">*</sup> נא ונוכחה מי הולידה ומאין באו. האם ראית עם אשר לשון עמו יעזוב אשר נתגדל מעליו מעודו, ויבדה לו לשון חדש ישתמש בו) או שמעת עליו. (האם שמעת כדבר הזה בשנים קדמוניות). סי' נ\"ו אמר הכוזרי לא ראיתי ולא שמעתי. (אין בזה שום ספק. האם גוי כולו ישנו טעמם ויסירו שפת לשונם בלי צורך כי מלבד פעולה בטילה בהבל יסודתה. מבואר ההיזק הגדול אשר יגיע להם כי כל הספרים הנכתבים להם מאז היתה לגוי הן בדברי חכמה הן בדברי הימים מי קורא בהם, והרי כולם יאבדו מהם וכמ\"ש הרב בעל קול יהודה ראיה זאת בשם הרלב\"ג אשר אף הוא פנה להכריח חדוש העולם מצד הלשונות בדרך זה). ואין ספק שהגיעו אליה בדור מן הדורות. (ר\"ל הלשונות אשר לכל עם ועם ודאי שהיה עת מתי שהגיעו עליהם) ולא היתה קודם לשון שהסכימו עליה. (לא שנאמר שעזבו לשונם המוסכם להם מאז, והמציאו להם לשון חדש. אבל לא היה להם לשון כלל מן הלשונות אשר אנו מוצאים עתה בכל אומה ואומה), מהסכמת עם מבלתי עם על לשון מבלתי לשון. (כלומר לא היה מקודם לזה לשונות חלוקים בעמים, וכל עם מוסכם להם לשון, מזולת המוסכם לעם אחר. אבל קודם לזה היה לשון אחד ושפה אחת לכולם והוא לשון הקדש מוסכם מאדם הראשון אשר רוח ה' דבר בו בסדר לשון הקדש והנחתו כמ\"ש ויקרא האדם שמות וגומר. ונאמר וכל אשר יקרא לו האדם נפש חיה הוא שמו. והמורה בפ\"ל מח\"ג כתב וז\"ל וממה שצריך שתדעהו ותתעורר עליו אמרו ויקרא האדם שמות וגומר. למדנו שהלשונות הסכמיים לא טבעיות כאשר חשבו זה עכ\"ל, וא\"כ לא רחוק הדבר כי בטרם דור הפלגה כל הארץ דברו בשפת אביהם אדם הראשון וכאשר נשכחה לשונם בדור הפלגה כל העמים איש לדרכו פנה בהסכמת לשונו. מלבד עבר ואברהם אבינו ושאר יחידי סגולה אשר ריחם לא נמר ועמד לשונם בהם כמאז, ומהם נמשך לבני ישראל עד היום. ומעתה נתחזק המופת על מציאת אדם הראשון וחידוש העולם ויסוד האמונה, מצד דור ההפלגה ובלבול הלשונות עכ\"ל) עכ\"ל הכוזרי והמפרש.\n<b>וכיון</b> שהוכרחנו שהלשונות הנמצאים עתה הם מחודשים ולא קדם להם לשונות אחרים, א\"כ בהכרח שגם כל מין האנושי המדברים הם מחודשים, שהרי ודאי לא היו זמן בלי גבול מבלי שום לשון, כי זה בלתי אפשר לקיום העולם בלי שום דבור בין איש לרעהו, ובודאי לא קדמו רק איזה זמן מוגבל עד שהמציאו והסכימו על לשון. וכיון שהלשונות כולם מחודשים, ומין האנושי לא קדם להם רק איזה זמן מוגבל, א\"כ מוכרח שכל מין האנושי מחודש כי מה שיקדם זמן שיש לו תכלית וגבול למחודש הוא גם כן מחודש בהכרח. הנה אם כן יהיה המין האנושי מחודש בהחלט, כן סיים הרלב\"ג מאמר שישי פט\"ו. גם א\"א לומר שעברו דורות בלי גבול, והלשונות נתחדשו אח\"כ וג\"כ עברו עליהם שנים בלי גבול, רק לא כפי מספר הדורות בלי גבול כי הדור הוא כ\"ה שנים. וא\"כ הדורות הם כ\"ה פעמים בלי גבול שנים, והלשון נתחדש אח\"כ מזמן כ\"ד פעמים בלי גבול שנים, דמ\"מ עברו שנים בלי גבול בלי שום לשון וזה אי אפשר. וגם את\"ל הלשונות ג\"כ עברו כ\"ה פעמים שנים בלי גבול, רק משהו פחות מהדורות. כ\"ז אינו נכון דמאחר שהלשונות מחודשים בהכרח, א\"כ אינם קדמוניים, שהקדמון אינו מחודש, והם שני הפכיים. וכיון",[["139","*","<b>סי' נ\"ה. . סי' נ\"ו</b>: לשון הכוזרי עם פי' האוצר נחמד."],["140","*","<b>לכו</b>: כ\"ה בגוכתי\"ק, אבל באוצר נחמד: לכה."]]],[3000730396,"שהלשונות מחודשים והאנשים אי אפשר שיקדמו להם רק זמן מוגבל הרי הכל מחודש. ועוד אם הלשונות עברו עליהם זמן בלי גבול שנים או ימים היה ראוי להיות במציאות ספר באיזה לשון שיהיה מזמן חיבורו ימים בלי גבול, וזה אי אפשר. והוא מהענינים הנמנעים בתכלית המניעות, ואיך יתכן שדבר שהיה מחוייב שיהיה כן הוא מתכלית הנמנעות, הרי זה שני הפכיים. אלא ודאי הלשונות מחודשים, ומין האנושי כולו מחודש.\nכט <b>ויש </b>לבאר יותר הדבר שיהיה מובן המופת היטב. הגע עצמך אם היה נמצא איש אחד לפנינו זקן במאד מאד חי, או אפי' מת רק שעצמותיו מונחים. וזה האיש נרשם אצלו ונודע ברור שלא קדמו לו אנשים רק מעט ערך עשרה דורות או יותר רק עכ\"פ מספר בעל תכלית. אז נכריח ונדע בבירור אשר מין האנשים כולם מחודשים, ולא קדמון במין כדברי המכחישים, וזהו פשוט, כי זה האיש הרי הוא ודאי מחודש שנולד מאב ואם. ומאחר שהוא ודאי מחודש ועומד לפנינו הרי זה רחוק מענין הקדמות, כמו שאנו כל המחודשים באיש הנמצאים עתה רחוקים מן הקדמות. דאף שהוא זקן במאד מאד לא ידוע כלל מספר שניו, עכ\"פ הרי הוא מחודש. ועוד דאף את\"ל שעברו עליו שנים בלי גבול, מעת לידתו עד עתה, מה שאי אפשר לאוזן לשמוע ולפה לדבר, עכ\"ז, הרי אינו ערוך לענין הקדמות, כיון שהוא מחודש כמונו ועומד לפנינו. וע\"ז יודה גם ארסטו דלא נסתפק בשבוש הקדמות במין האנשים רק בבא זה אחר סור זה. ע\"ז נסתפק לומר שאע\"פ שכל פרטי האישים הם מחודשים עכ\"ז המין האנשים קדמון. אבל באיש פרטי המחודש וקיים באיש, יודה גם שאין להסתפק שממנו עד עתה עברו שנים בלי גבול. שזה בלתי אפשר, כמו שאי אפשר שמאתנו עד הנולדים יעברו בפועל שנים בלי גבול כדלעיל סי'<sup data-n=\"141\">*</sup><sup data-n=\"142\">*</sup>, כך כיון שזה האיש קיים באיש אי אפשר שממנו עד עתה עבר זמן בלי גבול, כי אם רק זמן מוגבל. וכ\"ש וק\"ו שאין לספק עליו בקדמות כמו ממש שאין לספק עלינו המחודשים, בקדמות, כיון שידוע שהוא מחודש, שהרי כל איש מחודש, והוא עומד לפנינו, לא עדיף מהמחודשים באיש הנמצאים עתה רק שזקן יותר הרבה. זה ודאי ברור וכמו נתפס בחוש המישוש. וכיון שלא קדמו לו אנשים רק עשרה דורות, או שאר מספר מוגבל, א\"כ בהכרח שכל מין האנשים מחודשים. וע\"ז לא יחלוק שום אדם, אילו היה נמצא כן איש אחד, וטענתם הכוזבת הוא רק מפני שהאנשים באים זה אחר סור זה כו' ומדמים זה להזמן. וכבר כתבתי להשיב ע\"ז לעיל באריכות. והנה הלשונות כיון שנתברר שהם מחודשים, והרי הם קיימים באיש, ר\"ל כל לשון שנתחדש כמ\"כ קיים עתה. א\"כ ה\"ז הלשון דומה לאיש אחד זקן הקיים בגופו באיש. דהרי ענין הלשון יש בו כמה תיבות וכמה שרשים וכמה ענינים ודבר גדול ועצום הוא כנודע ליודעים בענין לשון הקדש. ואף שבשאר לשונות אין חכמה כמו בלשון הקדש מ\"מ גם בהם יש חכמה גדולה להעמיד הלשון על מתכונתו. וא\"כ כל לשון ולשון משבעים לשון לא גרע כל אחד, מאיש קיים בגופו דכמו כן זה הלשון קיים, וגם לא גרע מעיר אחת אילו יצוייר שקיימת מעת היות עיירות הראשונים בעולם ולא קדם לה שום עיר. וא\"כ כיון שזה הלשון מחודש, והוא מחודש גמור כמונו רק שיש לו שנים רבים יותר מזמן חדושו, וגם בהכרח שלא קדמו לו אנשים רק זמן מוגבל כמשנת\"ל שזה לא יתכן שהיו אנשים זמן בלתי גבול בלי שום לשון מדבר. וא\"כ לא קדמו אנשים להלשונות רק איזה זמן מוגבל. וכיון שהלשונות מחודשים וקיימים באיש והאנשים לא קדמו להם רק זמן מוגבל הרי ברור כשמש שכל מין האנשים מחודשים, ולא קדמון במין, כי אם שמין האנשים כולו מחודש מעיקרו.\n<b>וגם </b>זה דומה לאם היו כל בתי העיירות וכל העיירות כולם קיימים באיש מיום",[["141","*","<b>כלדעיל</b>: סי' ב' ואילך (ע' 56)."],["142","*","<b>כלדעיל סי'</b>: בגוכתי\"ק מקום חלק, וראה לעיל סעי' ה ואילך."]]],[3000730399,"הווסדם, ר\"ל תצייר עד\"מ שכל בתי חומה שבירושלים עד\"מ או בשאר כל עיר ועיר כולם הם החומות שהיו מעת הווסדם, ולא שחרבו וחזרו ונבנו וכן העיירות הן הן שהיו מימי עולם אפס זולתן, לא שהיו עיירות אחרים שנחרבו, כן תצייר עד\"מ. וא\"כ כיון שלא קדמו להם בתים אחרים כלל, כ\"א הן לבדן הן הבתים והחומות מימים ראשונים היות בתים בעולם, והם על כרחך מחודשים שהרי הן מעשה ידי אדם, וגם אי אפשר להבנות כ\"א ע\"י אנשים רבים וחכמים במלאכת הבנין. א\"כ על כרחינו שהבתים כולם מחודשים, ואם הם קיימים באיש ממש, הרי הם מחודשים כמונו ואח\"ז נשכיל שבודאי מין האנשים לא קדם למציאות בנין הבתים רק זמן מוגבל. דמדוע יעבור זמן רב כ\"כ בלתי בנין בתים שהוא הכרחי מאד למין האדם בפרט במקומות הקרים אי אפשר להיות בלי בית בחורף א\"כ ודאי האנשים לא קדמו להבתים רק זמן מוגבל. וכיון שהבתים כולם מחודשים על כרחך גם מין האנשים כולו מחודש, רק שעל הבתים תוכל לדחות שהיו זה אחר סור זה בלי תכלית. מה שג\"ז שקר וכמש\"ל. אבל עכ\"פ הלשונות שהם דומים לפחות לבתי העיירות והן ודאי קיימים באיש, לכן מזה מופת גמור שכל מין האנשים מחודש כנ\"ל:\n<b>ועמ\"ש</b> לעיל ח\"א סי' ך' ך\"א (הג\"ה וע' לקמן סי' ל\"א נתבאר שגם בהעיירות א\"א לומר שהיו זאס\"ז בל\"ת דמ\"מ האויר שבתוכם המוקף מחיצות הוא אחד ממש וחשוב כמו בית ועיר א' קיים באיש מעת הווסד וכמו איש אחד הקיים באיש עכ\"ה).\nל <b>ובזה </b>התיישב לי מה שהיה קשה לי על הכוזרי והרלב\"ג למה כשרצו להכריח החדוש עולם מענין הלשונות הוכרחו לטענה שאי אפשר שיהיה לשון לפני לשון, עד שהכריחו שלא קדם לשון אחר ללשונות האלו, ולמה לנו לטורח הזה דלכאורה אף לו יהי כן שקדמו לשונות אחרים ללשונות אלו. עכ\"ז מאחר שזה מוכרח שכל לשון יהיה איך שיהיה הוא הסכמיי ובהכרח שיסדו אותו האנשים, א\"כ בהכרח שקדמו האנשים קדימה זמניית להלשונות, וכיון שכן על כרחך הלשונות אינם קדמונים כ\"א מחודשים שהרי בהכרח מין האנושי קדם להם. ואי אפשר שיהיו שניהם קדמונים ר\"ל מין האנשים וגם הלשונות, דאיך יהיה הלשונות קדמונים כיון שבהכרח קדם להם מין האנושי, ואי אפשר שיהיו שני דברים שאחד מהם קדם לחבירו זמן רב, עכ\"ז יהיו שניהם קדומים. זה ודאי שקר גמור אלא דאם האחד קדם לחבירו, וא\"כ חבירו היה זמן שלא היה בעולם וקדמו ההעדר, א\"כ הוא מחודש ולא קדמון. וא\"כ לפ\"ז כיון בהכרח אף אם היה לשון לפני לשון, עכ\"ז מין האנשים קדמו זה נכון לכל הלשונות שהיו בעולם א\"כ מין הלשונות מחודש ולא קדמון. וכיון שהאנשים לא קדמו להם רק זמן מוגבל, א\"כ מי שהוא קדם אל המחודש רק זמן מוגבל הרי גם הוא ודאי מחודש ולא קדמון, דאין שייך שהקדמון יהיה קדם רק זמן מוגבל אל המחודש זה לא יאמר אדם.\n<b>וצ\"ל</b> דס\"ל שמזה לא היה אפשר להכריח כ\"כ החדוש בלי שום פקפוק, דטענה זו שאי אפשר שיהיו שני דברים קדומים אם האחד קדם לחבירו זמן מוגבל, אף שהוא אמת לאמתו עכ\"ז לכאורה יש לפקפק עליה ממין האנשים גופא, לדברי המכחישים המסתפקים בקדמות המין האנשים, בטענה לפי שהם באים זה אחר זה לכן מדמים זה לענין הזמן שהוא בא רגע אחר רגע זה אחר סור זה. ולדבריהם הזמן אינו מחודש, וכמ\"כ מין האנשים. והרי לדבריהם ג\"כ הרי כל האנשים שהיו מימות עולם ועד עתה כולם היו מחודשים. אין גם אחד שהיה קדמון באיש, כ\"א הכל מחודש ואעפ\"כ עולה על דעתם שהמין קדמון, ומביאים ראיה מהימים של הזמן שג\"כ כולם היו מחודשים ואעפ\"כ ס\"ל שמין הזמן היה קדמון. הגם שבאמת זה ג\"כ שקר דהזמן מחודש, אך המכוון להשיב הכרח מהלשונות אף לשטתם. וא\"כ אם היה לשון לפני לשון אל לא"],[3000730402,"תכלית, חזרו הלשונות להיות כפרטי האישים, וכפרטי הימים של הזמן, שאף שהיו כולם מחודשים אתה אומר שהמין קדמון. נמצא אף שכל האישים שהיו בעולם היו מחודשים, וא\"כ אם אעפ\"כ המין קדמון, יקשה שהרי היותר קדמון באיש לא קדם לבנו ולבן בנו שהיו מחודשים רק זמן מוגבל, ואיך יהיה המין קדמון אם לא קדם לפרטי האישים המחודשים רק זמן מוגבל בהכרח. כמ\"כ תוכל לומר בלשונות אם היו זאס\"ז בלי תכלית מחודשים, עכ\"ז המין קדמון, אף שמין האנשים קדם להן י\"ל הלשונות לגבי האנשים לגבי האב, והרי הבנים ודאי מחודשים וכל האנשים כן, עכ\"ז המין קדמון. ואף שהדבר קשה לקבלו הם מביאים ראיה ע\"ז מהימים של הזמן ועיקר שקרם מפני שהדבר המחודש כשבא זאס\"ז יוכל להיות שיהיה המין קדמון. והקושיא שא\"א שיהיה שני דברים קדומים, אם על כרחך השני מחודש אחר הראשון תסבול באין תירוץ. וקצת י\"ל שע\"כ גם בענין הזמן כן הוא, שהרי אם הזמן אינו מחודש א\"כ עברו שנים בלי גבול, ועל כרחך עברו ימים שס\"ה פעמים בלי גבול. וא\"כ הימים קדמו להשנם שהרי הן שס\"ה פעמים במספר כמו השנים, והדבר שזקן מחברו שס\"ה פעמים הוא קדם לו. וא\"כ ה\"ל הימים קדמו להשנים, ואעפ\"כ אתה אומר ששניהם קדמונים, כמ\"כ י\"ל בהלשונות עם האנשים, אם היה מקום לומר שהיו לשון לפני לשון אל לא תכלית, (הג\"ה, ועכ\"ז לא דמי דהבן והאב מין אחד כמו ימים, משא\"כ הלשונות לגבי האנשים הם כמו מקרה מתחדש מהעצם, וס\"ל להרס\"ג בראיה שלישית, דכיון שהמקרים מחודשים והעצם קדם להם א\"כ הם מחודשים ושוב מוכרח שגם העצם מחודש כיון שלא קדמו רק זמן מוגבל וכמו שנתבאר לעיל ח\"א סי' ך' ך\"א, ומ\"מ כיון שיש חולקים על ראיות הגר\"ס אף שדבריו עיקר ע\"כ הביאו הראיה מהלשונות ע\"י שהכריחו שלא קדם לשונות ללשונות אלו, עכ\"ה). אכן כיון שהכריחו הכוזרי והרלב\"ג שלא קדם לשון אחר אל הלשונות שלפנינו. וא\"כ כל לשונות אלו העומדים לפנינו המחודשים באיש, לא קדם להם לשון אחר. א\"כ לא דמי כלל למין האנשים שבאים זה אחר סור זה, וכ\"ש דלא דמי לימים של הזמן, שהרי הימים שעברו אינן במציאות עתה. וכן האנשים שחלפו וזה הלשון נמצא לפנינו עתה כמו שהיה, א\"כ הוא איש אחד, וידוע שזה האיש המחודש ולא קדמון. א\"כ הוא ודאי מחודש ממש כדלעיל באריכות. וכיון שמין האנשים לא קדם להלשונות רק זמן מוגבל לבד א\"כ גם כל מין האנשים כולו מחודש. לכן מובן שמופת זה הוא אף לפ\"ד האומרים שהזמן אינו מחודש. עכ\"ז מענין הלשונות יש להכריח אשר מין האנשים כולו מחודש. ואחר זה מטענה זו ג\"כ יש לדמות כמ\"כ על מין האנשים מצד עצמן כדלעיל סי' י\"ד לבד מטעם הלשונות, והוא משום שיש לחלק ולהבדיל בין הזמן לאישי האדם יעו\"ש. אך כי גם טעם זה שבבתים שאף שבאו זאס\"ז מ\"מ פנימיותם אחד ממש כאילו הכל מה שהי' הוא בית אחד ועיר אחת כמ\"כ י\"ל באדם כי הרי בפנימיות הבן יש בו מכח האב ממש, רק פשט צורה ולבש צורה, א\"כ הפנימיות הכל אחד ממש. וזה כעין מש\"ל סעיף כ\"ג בשם האו\"נ ועמש\"ל ססעי' כ\"ה.\n<b>במ\"נ</b> ח\"ב פ\"א עיון שני כו' כשימצא דבר מורכב כו' זהו ע\"ד כל דבר שהיה בכלל ויצא מן הכלל ללמד, לא ללמד על עצמו יצא אלא ללמד על הכלל כולו יצא. כמ\"כ עד\"מ כשנמצא הדבש בפ\"ע יצא מן הכלל שהי' מורכב בעוד דבר, יצא ג\"כ ללמד גם על החומץ שנמצא ג\"כ בפני עצמו יעו\"ש. ועי' בשבת פרק כלל גדול ד\"ע א' הבערה בכלל היתה ולמה יצאת להקיש אליה כו'. ועמ\"ש מזה בבוך בראשית א' דף פ' ע\"א בד\"ה במדרש רבה פ' בראשית פ\"ח. שמה שהקשה הרש\"ט מהדבור והחיות לק\"מ. דבאמת נמצא הדבור בפ\"ע בלי חיות גופני והיינו במלאכי השרת. וכמ\"ש במד\"ר שם"],[3000730404,"דהדבור שבאדם הוא מארבעה דברים שהוא דומה בהן למלאכי השרת כו', והקושיא מעצם ומקרה תירץ הרש\"ט עצמו בטוב.\n<b>מענין </b>הבתים הסברא נותנת בלא\"ה כיון שבנה בית על מכונו ה\"ז כבית אחד.\n<b>ודע </b>שאפילו אם בכל העיירות שבעולם תהי' רק עיר א' או בית א' שנבנה על מכונו ועל תלה מספיק המופת, דע\"כ עיר זו מחודשת והרי שאר העיירות לא קדמו לה, זמן בלתי מוגבל כו'.\nלא <b>[והנה</b><sup data-n=\"143\">*</sup> הדבור דומה לעיר וכנודע מענין שני אבנים בונות שני בתים] רק שבדבור יש מופת חזק, כי בבתים י\"ל שעברו כמה בתים זא\"ז לבל\"ג הגם שהם מחודשים בהכרח, וגם י\"ל כמה עיירות נחרבו, אבל הדבור ע\"כ ע' לשונות אלו מחודשים וזולתם לא הי' לשון אחר. א\"כ בהכרח שכללות הדבור מחודש. וא\"כ זה מופת שא\"א לומר שעולם כמנהגו נוהג מימי קדם כו' ובטלה דעת מאמיני הקדמות. וכ\"ש לפמ\"ש לעיל בענין בונה בית על מכונו דחשוב הכל א' ממש עם הבית הראשון שסתרו. וכ\"ה ע\"פ הדין במשנה פ\"ח דסוטה וגם בכל עיר י\"ל כן שאע\"פ שמתחדשים הבתים מ\"מ הוא עיר על מכונה הראשון שאויר שטח העיר המלא בתים אינו דומה לאויר השדה, והעיר הכל אחת ממש מיום הווסדה אף שנשתנו הבתים מ\"מ כללות העיר לא נשתנה שענינה אויר מוקף מחיצות וגג. ומעשה זה שוה ואחד ממש מעת הראשון שנתייסדה העיר, שאזי נשתנה האויר ונעשה מוקף מחיצות וגג ואף שאח\"כ נשתנו סדר המחיצות מ\"מ האויר אחד, א\"כ העיר ודאי מחודש ע\"י אנשים הבונים, והיא כאיש א' זקן שידוע שהוא מחודש. א\"כ היה זמן שלא היו עיירות כלל מאחר שנחשבם בהדרגת עיירות ראשונות מעולם ולא בהדרגות בוא זה אחר סור זה, מטעם האויר שבתוך הבתים שהוא ראשון ואחרון, והרי הוא מחודש וקדמם ההעדר, ובהיות כן שהעיירות כולם מחודשים הנה זה מכריח שהיה זמן ג\"כ שלא היו אנשים כלל כיון שבודאי האנשים לא קדמו אל העיירות רק זמן מוגבל כנ\"ל. וזה ראיה מהחוש עם השכל לבטל ולסתור דעת הקדמות, והעולם מחודש. הרי נת' גם לפי קט שכלי עשרה מופתים על חדוש העולם, ועכ\"ז העיקר היא האמונה פשוטה שהיא טוב יותר וכמ\"ש הכוזרי תחלת מאמר חמישי, רק למי שלבו נוקפו אזי טוב יותר לעיין בהמופתים שנזכרו כאן משישאר נבוך. כ\"כ הכוזרי שם. ועיקר חיזוק האמונה הוא ע\"י עסק התורה שהתורה נק' אמת והוא מקור האמונה, כמאמר אמת ואמונה כל זאת, גם עיקר<sup data-n=\"144\">*</sup> האמונה הוא לאמין בהאמת, ולכן ארז\"ל ניכרים דברי אמת וא\"צ ע\"ז ראיה. וע' עוד בהרמב\"ן בפירוש החומש פ' בא<sup data-n=\"145\">*</sup>.\n<b>ע'</b> בהרמב\"ן ס\"פ בא ועתה אומר לך כו' וכאשר ירצה כו' כי המופת כו'. ומובן עפמ\"ש במ\"א שגשמיות מרוחנית א\"א להיות ע\"י השתלשלות עילה ועלול. א\"כ התהפכות ים ליבשה עד\"מ מורה אכח בלתי בע\"ג כל יכול דוקא. וביותר ירידת המן שהתמיד מ' שנה ושבשבת לא ירד ורמה לא הי' בו משא\"כ בחול כשהותירו ממנו עד בוקר וירם ויבאש תולעים ע' בהקדמת ספר האמונות לרס\"ג כ' וז\"ל ואני רואה כי ענין אות המן כו' ע\"ש (ובעל ספר הברית עשה א\"ע כאילו לא ידע ספר הנ\"ל וכ' כן במאמר והאדם ידע ודרך אמונה מדנפשיה). ומופתי דניאל בגוב אריות וחמו\"ע בכבשן האש העיד הרמב\"ם שכתובים ג\"כ בקראניקעס דפרס כמ\"ש ס\"ה הנ\"ל וכ\"כ בספר יוסיפון. וריבוי המופתים שבש\"ס ואפי' דורות האחרונים כמו המגיד להב\"י (ונבואת הילד<sup data-n=\"146\">*</sup>) דבר הפלא. והאריז\"ל והבעש\"ט והה\"מ שראו מסוף העולם עד סופו כאשר שמעתי מרבינו ז\"ל לפני הסתלקותו שבנו ר\"א הי' בא אליו מחוואסטעוו לראוונע בעש\"ק וביום א' הי' נוסע לביתו והי' הה\"מ מלוה אותו ע\"י ראייה מביתו עד כניסתו לביתו בחוואסטעוו: ובמ\"א<sup data-n=\"147\">*</sup> כתבתי דההעתקה מדור לדור ה\"ל כעדות דראיה וידיעה כו' ואין זה כעדים מפי עדים כו' כ\"א כל דור ב\"ד גדול של ס\"ר ויותר כו'.",[["143","*","[והנה. . בתים]: שורה זו השמיט המו\"ל הראשון. ראה לקמן קח, א השמטה לכאן."],["144","*","<b>כמאמר</b>: גם עיקר — עיין בכ\"ז הערות הצ\"צ לתניא פי\"ח ס\"ק יג."],["145","*","<b>פ' בא</b>: בגוכתי\"ק נמצאו כאן הקטעים נדפסו בעמוד שלאחר זה, ואח\"כ נמצא ע' שנכתב עליו קטע ”ע' ברמב\"ן\"."],["146","*","<b>ונבואת הילד</b>: ראה לקמן במ\"מ."],["147","*","<b>ובמ\"א</b>: ובמ\"א — ראה ד\"ה עדות (לקמן ע' 126 ואילך)."]]],[3000730057,"א)<sup data-n=\"148\">*</sup> <b>עד</b> סוף כל הדורות א\"א שיהיו אנשים בלי גבול, וממנו למפרע נצטרך לומר שהי' מאה מילייאן פעמים בלי גבול, כי על כל א' מוכרח לומר שאין גבול לאבותיו. וא\"כ בעולם יש אלף מילייאן אנשים. לפחות מוכרח שיש מאה מילייאן (עשר למשפחה) בלי גבול, ואיך ממנו עד צאצאינו א\"א אפי' פ\"א בלי גבול, וממנו עד זקנינו יהי' מאה מילייאן פעמים בל\"ג. הרי אתה מכניס המאה מילייאן פעמים בל\"ג, בחלל הטבעת שהוא הגבול שממנו עד צאצינו כו'. ובגמ' אמרו אין ספק מוציא מידי ודאי.\n<b>זה</b> ודאי א\"א. וזה אצלינו אינו מושג לא נתבאר המנעו. א\"כ כיון שא\"א להמלט מא' משני אלה, ההכרח לומר שזה הוא השקר שיהי' הדורות בל\"ג כו'.\n<b>ועוד</b> כי לפי הנ\"ל תוכרח לומר שהבל\"ג נכנס בגדר מספר כהנ\"ל מאה מילייאן פעמים בל\"ג, וגם האחדים יבואו למספר בל\"ג. א\"כ ה\"ה שי\"ל בל\"ג פעמים בל\"ג, כמו שתאמר בל\"ג פעמים אחד, וכן תאמר עוד בל\"ג פעמים בל\"ג פעמים בל\"ג כו' כדמוכרח הוא. וא\"כ אם זקניו של ראובן דעתה הי' עד\"מ רק בל\"ג פ\"א א\"כ אבותיו מחודשים והעולם מחודש. ושתאמר שהיו בל\"ג פעמים בל\"ג אין קץ זה שקר שבהכרח אבותיו של כל בני העולם הם מאה פעמים מילייאן יותר מאבותיו של ראובן לבדו, א\"כ בהכרח שנשאר זמן עודף יותר מאה פעמים מילייאן על אבותיו של משפחה א'. א\"כ לפ\"ז הם מחודשים כו'. ועוד א\"כ לפי הנ\"ל עשית הבל\"ג כענין גבול, שהרי נכנס בגדר מספר, כמספר א' או שנים, ואין כאן רק שינוי השם שנק' בל\"ג, ובאמת הוא מספר ויש בו רב ופחות כו' וכ\"ז שקר, וכמו לנמנע טבע קיים. משא\"כ ענין למעלה מהזמן אצל הבורא ית' נכון הוא.\nב) <b>וכן</b> הוא האמת שבה\"ק שבעיר זו עד\"מ מזמן מאה שנים, וזו מזמן יותר כו' הכל בגבול.\nג) <b>וע\"כ</b> י\"ל שהבריאו' שברא הקב\"ה שאישיו מחודשים ר\"ל שנולדים מאב ואם הם מעידים על החידוש, ממילא גם על הברואי' כשמים וארץ כו' כי אין שום ספק ח\"ו על הקדמות אלא את\"ל שעולם כמנהגו נהג, כמו עתה כן הי'. וזה ודאי א\"א שעכ\"פ המדבר והחי הנולדים מזו\"נ, קדם להם ההעדר, גם על הצומח י\"ל כן. וא\"כ רוב העולם מחודש, א\"כ מסתמא הכל מחודש.\nד) <b>כמו</b> כן גרגרי' בלי גבול ויש א\"כ בלי גבול גרגרי' בפועל מה שמכ\"א הורכבו מילייאן אנשי' והוא ע\"ד לגדודי' אין ה) דה\"ל בפועל ושם מכריחים דא\"א שיהי' בפועל בל\"ג וכאן באנשים נניח זה דאף את\"ל שהיו בל\"ג איני מכריח רק שהיו מחודשים כמו שהם וא\"כ כש\"כ שיש לחלק כן בין הזמן מצד שי\"ל רואין כנ\"ל משא\"כ בזמן, ואח\"ז נשוב ידינו שגם הזמן מחודש, ועוד י\"ל שהן ממש לפנינו כי אפי' את\"ל.\nו) ועוד א\"כ הקדמות תלוי במה שקוברי' המתי' לא בעומק הארץ כ\"כ.\nז) <b>ומעתה</b> נשוב ידינו גם בענין הזמן כי גם כל עיקר החילוק בין בא זה אחר סור זה כו' הוא חלוש מאד, דכמו שבא המופת על המנע מציאות גשמיי' אין תכלית למספרם בזמן א'. כמ\"כ נ' דה\"ה בבא זאס\"ז כו'. וכל הגורם להכריח לחלק כן הוא ענין הזמן, וגם ע\"ז י\"ל הענין דלומר שהזמן בלתי בע\"ג הוא כמו לנמנע טבע קיים כו' משא\"כ ענין למעלה מהזמן כו', ועוד אף את\"ל אזמן י\"ל כן, מ\"מ אין זה סותר המופתים דלעיל, דלכאורה נת' המונעם והוא מש\"ל, וע\"ש",[["148","*","האותיות הם מהמו\"ל הראשון, והם קטעים נפרדים שנכתבו בין המחקים."]]],[3000730099,"בכוזרי כי מה שיצא אל גבול הפועל ונמנה אח\"כ המנין כו' יש לו תכלית בלי ספק כו', וזהו מופת ברור על המנע בא זאס\"ז פעמי' רבי' בב\"ת עכ\"פ. דרמב\"ם כ' שלא בא המנעו על בב\"ת פ\"א דאז לא שייך מ\"ש הכוזרי כי מה שיצא כו', אבל לומר שיוכל להיות בב\"ת פעמים רבים זא\"ז נ' שהוא א\"א דאל\"כ אמאי א\"א להיות מנין בב\"ג מאתנו עד צאצאינו כו', והגם דא\"כ יהי' מופת אף על המנע פ\"א בב\"ת אך י\"ל שז\"א מופת כ\"כ כי העבר צ\"ל עודף מעט מהעתיד שיצא לפועל כיון שאפשר בו עוד לצאת לפועל, אבל אנו שיירנו הרבה עודף לעבר על העתיד כשת\"ל שבעתיד יצא לפועל פ\"א בב\"ת ובעבר יצאו לפועל מאה מילייאן פעמים בב\"ת או בל\"ג פעמים בל\"ג כו' וכיון שאפ\"ה א\"א שיצא בעתיד בל\"ג אף פ\"א א\"כ נ' שזהו מופת ברור על המנע בעבר בב\"ת כ\"כ רבו' פעמים כו' ולכן העולם מחודש (ואת\"ל שא\"כ בלעתיד יוכרח ג\"כ בל\"ג פעמי' בל\"ג וא\"כ מהו עודף לעבר י\"ל העודף דע\"כ חזר הבל\"ג כא' וא\"כ כל מה שתאמר בל\"ג פעמים בל\"ג ה\"ל כמו אלף פעמים אלף ויכול להיות עוד ובעבר הי' יותר ואינו מובן איך כמו עכשיו על א' כו' ועוד עכ\"פ ראינו שא\"א להיות מנין מא' עד בל\"ג בפועל וא\"כ א\"א לומר כן בעבר ג\"כ) והנה אף אם הענין הי' שקול, א\"כ כיון עכ\"פ סברת הקדמו' רחוקה יותר מסברת החידוש. א\"כ יספיק ע\"ז המופת דהר\"ר יוסף יעב\"ץ שנז\"ל שאין עליו שום סתירה מטענות אלו, להכריע דעת החידוש. כיון שאף בלעדי זה המופת, קשה יותר לומר ההיפך מענין החידוש, כש\"כ כשנוסף ע\"ז ראי' ברורה חושיי' זו.\n<b>ועוד</b> יש ראי' על החידוש מענין הלשונות של כל עם שבלי ספק הם מחודשים אחר שלא היו מקודם כו' כמבואר בכוזרי מאמר א' סי' נ\"ג עד סי' נ\"ו ובאוצר נחמד שם. ועפ\"ז נ' טעם בענין דבשבת כתי' ודבר דבר, כי שבת היא עדו' על חידוש העולם. מש\"ה צריך לשתוק מדיבורי חול, להיות כי הדיבור ג\"כ מחודש שהלשונו' מחודשי' כו'. וגם למעלה ענין דבר ה' הוא מחודש בשי\"ב כו' משא\"כ קודם שנברא העולם לא שייך בחי' דיבור כו'.\nט) <b>וכ\"ז</b><sup data-n=\"149\">*</sup> ראי' לחידוש. דאל\"כ הי' הריבוי לאין קץ ממש אף אם בכל דור לא נוסף בו רק איש א'. (וכ\"ש לולי מלחמות. ונודע שא\"א להיות רבוי בלי גבול בפועל א\"כ המביא אל הבטל בטל)\nיוד) <b>כ\"ז</b> ראייה חושיית לחידוש. ג\"כ ראיה מהתחדשות שבכל דור כמו מציאת הדפוס הזייגערש וכיוצא, שתוספות שלימות לא שייך רק בדבר המחודש שלכך רוב שנים יודיעו חכמה, משא\"כ בדבר שעבר כבר זמן בבע\"ג, היה ראוי שמה שיהי' עכשיו הי' ג\"כ מקודם.\nיא) <b>דאין</b> לומר שא\"א לומר רואין כל האנשים כאלו נמצאים עתה, מפני שא\"כ יהי' נמצא בלי גבול בפועל מה שאי אפשרר דזה אינו מבטל כלל ענין הרואין כמשי\"ת. ועוד משיטתך אני משיבך דלשטתם ע\"כ צ\"ל שעברו כ\"פ בלי גבול אנשי' כנ\"ל. א\"כ אמאי לא נוכל לומר ג\"כ רואין כאלו הן קיימין. ואם מפני שזהו בפועל בב\"א הלא הפרש זה גופא מי אימת לך. ועוד כשת\"ל שא\"א לומר כן א\"כ זה יבטל שלא הי' כלל אנשי' בל\"ג אבל ענין אמירת רואין לא יתבטל מפני זה שהרי אין זה מניעה לשלא תוכל לומר רואין אלא הוא ראי' שלא הי' כלל בלי גבול.\nיב) <b>והנה</b> על זה ודאי גם הם יודו שאם הדורות היו קיימים באיש או אפילו רק אחד מכל דור מוכרח שכל המין מחודש ובעל גבול. שהרי הרמב\"ם כתב שמוסכם מהפלוסופים שאי אפשר להיות גשמים בלתי בעל תכלית יחד בפועל כמ\"ש לעיל",[["149","*","<b>יג)</b>: קטע זה מהדו\"ק וכנראה שכ\"ז נמחק."]]],[3000730138,"אות ד' בשמו, רק שבבוא זה אחר סור זה כתב שלא בא המופת על המנעו, אמנם זהו לפי המופת שכיון הוא. אכן ע\"פ מה שביארנו לעיל מאות ח' עד כאן נראה שאין שום חילוק בין אם היו הדורות קיימים עתה, ובין כפי מה שהוא ששבו לאדמתם.\nיג)<b>*</b> <b>ואע\"פ</b> שלשטתם מוכרח לומר שלא נשאר גרגיר עפר מכל דור בפ\"ע דאל\"כ אלא שנשאר עכ\"פ גרגיר א' בפ\"ע מכל דור א\"כ לשטתם שי\"ל שהיו דורות בל\"ג א\"כ היה צ\"ל גרגירי עפר בפועל בלי גבול מה שזה בא המופת על המנעו כנ\"ל. אך באמת לא מפני הטעות שלהם שאמרו שי\"ל שהיה דורות בלי גבול נכחיש ונקרב בזרוע את המרוחק מהדעת לומר שלא נשאר אפילו גרגיר א' עפר מגופות כל דור בפ\"ע כיון שזה אין הדעת סובלתו ואם זה א\"א אא\"כ היו הדורות בגבול יותר ודאי יש לקרב האמת שהיו הדורות במספר וגבול כו' משיקרב את המוקצה מהדעת.\nיד) <b>וכיון</b> שכן מאחר שמכל הגופים שעברו וחלפו נשאר בהכרח דבר שיש בו ממש היינו עפר ואדמה א\"כ הרי זה קיימים באיש עד שיפול עליהם השאלה. דלא דמי לענין בא זה אחר סור זה דענין רגעי הזמן, אף ששם ניתן להם שאינו מחודש, היינו מפני שלמחר לא נשאר מאומה מיום האתמול אחר שסר וחלף, וכ\"ש מהזמן שעבר מכבר יותר וחלף והלך לו. וגם אינו ענין גשמי ומששי שיהי' שייך לומר שנראה הזמן העבר כאילו הוא עכשיו גם כן לענינינו. ע\"כ אין שייך עליו כל כך השאלה והתשובה הנ\"ל. אבל בגופות דורות החולפים שיש בהם ממש ונשאר קיים לפנינו מכל הדורות שעברו ואין שום אחד שיאמרו עליו שלא נשאר ממנו רושם כלל עתה. וא\"כ אף שהי' נושא לגופות הרבה מאד מ\"מ הריני רואה עפר זה כאלו יש כל הגופות שהיו בו לפנינו (והרי<sup data-n=\"150\">*</sup> הוא כגוף אחד ארוך מאד לבלי גבול, והוא מחודש ונולד מאב ואם. דודאי אלו נאמר שהוא כן פשוט שכל המין מחודש, ובודאי הכרח שהוא כן שהוא לא גרע מגוף אחד ארוך מאד). דאם לא כן תאמר שהגוף היותר ראשון נידון כחולף לגמרי וכאילו לא נשאר ממנו זכר עפר כלל, וזה דבר שלא ניתן להאמר. דאדרבה ישנו וישנו זכר ממנו, ואינו נושא לגוף שאחריו יותר לגוף הקודם.\n<b>ואדרבה</b> הוא נושא יותר לגוף היותר קודם דוקא, שהרי אם היה נושא רק לגופות במספר מוגבל על כרחן הוא נושא לגוף הראשון יותר עד שהרי זה כאלו כולם עומדים לפנינו שאכריח מזה שכל המין מחודש. א\"כ ממש כשהוא נושא לגופים בלי גבול עכ\"פ היותר מוקדם נחשב ונרמז בו יותר שמפני שנשא אחריו גופות אחרים ג\"כ לא נעקר ממנו היותר קדום. והנה כמו שהארץ עם היותה גשמיות מאד היא קדמות לשטת הטועים. כך וכל שכן שנוכל לומר שגרגיר עפר זה נושא לגופים בלי גבול וכאלו כולם בו עד שהוא כגוף אחד שמזמן בלי גבול, כי הבלי גבול פחות מהקדמות לשטתם כנ\"ל. ואי לזאת יכול אני להכריח שכל הגופות שהיו בו כולם כאילו קיימים באיש. ושנשאל עליהם אם הם מחודשים ויבא התשובה שבהכרח כולם מחודשים, ואזי כל המין מחודש. ואין שום נפקותא אם היה גרגיר עפר מכל דור עומד בפני עצמו ממש, שלא היה נושא לגופות אחרים כלל וכלל, וצורת הגוף שהיה בו מחודש א\"כ ודאי הכל מחודש כמו שנת' לעיל אות י\"א ממשל שורות האילנות. כמו כן אמת המשל הנ\"ל ומכוון להנמשל אף גם אם ניתן להם שכל גרגיר נשא גופים רבים זה אחר סור זה אף לבלי גבול אם היה אפשר להיות כן, כיון שהרי זה לענין מבוקשינו כאלו כולם עומדים לפנינו. ועוד שאדרבה מה שהאחרונים אינם כאלו עומדים לפנינו לא איכפת לן ומבוקשנו רק שהיותר ראשון בו נדין כעומד לפנינו, המשל כגון אם היה נושא לעשר גופים נניח לו שהתשעה לא איכפת לן אף כאילו אין רושם ממנו רק הוא רושם להראשון מהעשרה. ועד\"ז כשהוא נושא לגופים בלי תכלה נימא הכי",[["150","*","<b>(והרי. . מאד)</b>: בעמוד שלפני זה מציין הצ\"צ בגוכתי\"ק שצריך למחוק שורות אלו."]]],[3000730165,"שהעיקר שהוא רושם וזכר להגוף הראשון שנשא מה שממנו עד כאן עבר זמן בלי תכלה, ומי יקח ממנו שלא יהי' רושם וחלק ממנו ממש וכיון שזה מוכרח שהוא נדון ממש כאותו הגוף שעבר ממנו עד כאן זמן בלי תכלה. והרי עם היותו כן הכל מודים שהוא הגוף הנ\"ל היה מחודש אם כן הכל מחודש. והרי זה עד\"מ כמו בשורות אילנות הנ\"ל אם נקצץ מהשורה היותר גבוה מה שמתחת ונשאר ממנה רק מה שלמעלה בגובה ועכ\"ז כשנמדוד הגובה הנ\"ל והאויר במקום שנקצץ והכול בגבול. כמו כן אם נאמר שבעפר הנ\"ל אין רושם מן הדורות שאחר הגוף שעבר ממנו זמן בלי תכלה וה\"ז כאלו נקצץ השורה אבל עכ\"ז כיון שעכ\"פ הוא רושם ויסוד של הגוף שעבר ממנו זמן בלי תכלה. וכשנמדד אותו וכל הבאים אחריו והכל מחודש א\"כ הכל מחודש.\nטו)<sup data-n=\"151\">*</sup> <b>וקרוב</b> זה למשארז\"ל בבראשית רבה פרשה י\"ט ע\"פ וכחול ארבה ימים שהוא עוף אחד ושמו חיל אלף שנה הוא חי ולסוף אלף שנה אש יוצאה מקינו ושורפתו ומשייר בו כביצה וחוזר ומגדל איברים וחי כו' והיינו מעת בריאת העולם אחר אלף שנים הוא פושט צורה ולובש צורה כו'.\nטז) <b>אין</b> לדחות שיאמרו שהבל\"ג א\"א שיהי' מחודש וא\"ת בל\"ג רגעים כיון שי\"ל רל\"ז כו' א\"כ מחודש יאמרו שאינו מושג ע\"ז נשיב דא\"כ הא עכ\"פ אינו ברור לך שהי' בל\"ג גופי' זא\"ז כ\"א זה ברור לך שכל הגופי' שהיו מחודשי' וכאלו עומדי' כולן לפניך מאחר שהגרגיר נושא לכל הדורות כו' א\"כ הכל מחודש וממ\"נ אם א\"א שיהי' מחודש אא\"כ הי' גופות גבול ודאי כן הי'.\nיז)<sup data-n=\"152\">*</sup> <b>אלו</b> הם גוף אחד ארוך מאד כחול המרבה ימים בב\"ר פי\"ט שכל אלף שנה פושט צורה ולובש צורה אחרת\nיח) <b>ומדוע</b> לא נאמר כן בענין עשיית גביע לגבי הכסף עצמו אף את\"ל שהכסף נמצא בארץ מ\"מ כיון עשיית גביע בהכרח בא ע\"י בני אדם א\"כ הכל מחודש. וא\"כ עד\"ז ממש צורות הגופות.\nיט) <b>יג</b> ואין לומר דאדרבה כיון שאמרנו ששינוי הגופות זהו כענין פושט צורה ולובש צורה כו' א\"כ אע\"פ שהחומר אחד אין להכריח שבהכרח צורת הגוף נתחדש אחר ההעדר דהא כתב הרמב\"ם בהקדמה לחלק שני הקדמה ך\"ו לדברי הפילוסף ולפי זה יהיה המתנועע בעל תכלית מתנועע על ארך בעל תכלית פעמים אין תכלית להם בחזור על הארץ הוא חלילה כו' הובא במנוח הלבבות בשער היחוד פ\"ה וא\"כ איך החלטנו שאף לדבריהם כיון שחומר של הגוף לפנינו אי אפשר שיהיו הצורות שעבדו עליו וילכו אל הקדמות כו'. מאי שנה מהנ\"ל לדבריהם. אך דברי הרמב\"ם שם בשם הפילסוף הם על ענין הזמן וסבובי ותנועות הגלגל כו' שלדבריהם אינו מחודש, וכבר חילקנו לעיל אות ח' אף לדבריהם דלא דמי ענין גופות אנשים הבאים זה אחר זה לענין רגעי הזמן כו' משום שבענין גופות אנשים י\"ל שמושכל ראשון שאי אפשר שילך זה אל הקדמות כמו שנתבאר המשל הנראה בחוש לעיל אות יוד ממשל שורות האילנות כשאין שורה שתגיע גבהה לבלי גבול כו', ואף שזהו דוקא בנמשל כשחומר הגוף מגוף אחד עכ\"פ מכל דור הוא קיים לפנינו. שאז יתברר שצורתו מחודשת. אבל בנד\"ז שעברו עליו הרבה צורות, י\"ל שחזר הספק למקומו. אך הא ליתא דאע\"פ שאנו קוראין זה התחדשות הצורה, מ\"מ זהו ענין עצום מחודש שהעפר עולה בצמח הארץ ואח\"כ האב ואם אוכלים הצמח ואח\"כ מזריעים טפת זרע ונעשה מזה ולד א\"כ מעשה זו דבר גדול הוא. וכשנכריח שכל עשיות אלו הם מחודשים בעפר זה הנשאר קיים לפנינו, שפיר נמשל זה לשורה אילן שגבהו אינו מגיע לבלי גבול, ולא דמי כלל לרגעי הזמן שמהחולף לא נשאר מאומה עד שנדמהו לשורה אילן הנ\"ל. א\"כ",[["151","*","<b>טו)</b>: קטע זה שייך לחלק שנמחק דשם מבאר בענין פושט צורה ולובש צורה. וקטע זה נכתב באורך הגיליון."],["152","*","<b>יז)</b>: נמצא בין השורות שנמחקו אחר הקטע דלעיל."]]],[3000730185,"אף לדברי הפילסוף אין להכריח מהזמן על זה תדע דכה\"ג מצינו בדברי הפילוסוף עצמו שעשה מופת שא\"א שיהיו גשם אין תכלית לו או גשמים רבים אין תכלית להן ואעפ\"כ הסכים שבוא זאס\"ז יכול להיות בלי תכלית ואע\"פ שבאמת המופת ההוא שייך גם על זה כמו שכתב בח\"ה שער היחוד פ\"ה גבי וכשנחלק כו' מן האישים מימי נח כו' ע\"ש אלא שהפילוסוף יחלק ביניהם בסברא דקה וחלושה שאין השכל מקבלה רק מפני שיטעון שעל כרחך הוא כן מהזמן כו' א\"כ כ\"ש שי\"ל כן להפך דמה שע\"כ הוא כן בענין הזמן כו' שהוא רוחני ומה שסר חלף והלך לו ואין ממנו רושם כלל, אינו שובר מה שנראה בחוש שבגופות האנשים אי אפשר לומר כן, דה\"ל העפר כגוף אחד ארוך שבלתי אפשר שילך אל הקדמות כיון שגם הפילוסוף מודה שכל גוף מחודש. וכמו בענין עוף חול הנ\"ל הנולד מזכר ונקבה ופושט צורה ולובש צורה ע\"ד הנ\"ל, אילו יודה הפילוסוף במציאותו יוכרח להודות שהוא מחודש ולא קדמון במין, דה\"ל ממש כשורות האילן הנ\"ל שבזה אי אפשר להכחיש, שהרי כולו קיים באיש ממש ופשיטות הצורה בו יודה שאינו גורע כלום. וכיון שבהכרח נולד מאב ואם א\"כ כולו מחודש. וכמ\"כ באנשים דאף שפושטים צורה ולובשים צורה מאחר שזהו ע\"י שנולדים מאב ואם, ועיבור ולידה זה בלי ספק מחודש, א\"כ כל השתלשלות גוף הנולד מזכר ונקבה וקיים לפניו חומר כל הגופים שנשתלשלו בו מאב ואם, ע\"כ חומר זה דומה לאילן שגובהו אינו מגיע לבלי גוף, וכך השתלשלות גופות אלו שבחומר זה בהכרח הכל מחודש. וכ\"ז דלא כספר מנוח הלבבות הנ\"ל שדימה שם השתלשלות האנשים לענין הזמן. וגם בספר אוצר נחמד מאמר ה' סי' י\"ח פ\"א כתב הפך דבריו. רק י\"ל עדיין ל\"ד לעוף חול הנ\"ל שעכ\"פ נולד רק פ\"א מאב ואם ולכן מה שעברו עליו שינויים בל\"ג אין זה גורע לספק על הקדמות כיון שקודם לשינויים הנ\"ל נולד מאב ואם. אבל בנד\"ז שהשינויים הרבים היינו ג\"כ ע\"י או\"א. א\"כ כיון שלשטתם י\"ל שעבר כן שינויים בל\"ג פעמים וכמו בהזמן, א\"כ ממילא מוכרח שאינו מחודש, דהא הם יאמרו שמה שעבר בל\"ג אינו מחודש, דבמחודש יודו שא\"א שיהי' בל\"ג אפילו פעם א' ומה שבקדמות מוכרח שיש כ\"פ בל\"ג א\"כ יש בל\"ג שאינו קדמון יאמרו שזה אינו מובן. אבל זה ודאי שגם בל\"ג א' אינו מחודש. א\"כ לשטתם שאפשר שיעברו על העפר לידת בל\"ג מאו\"א יאמרו שאינו מחודש. אך נניח להם דאף שנאמר כן זהו אילו היה ודאי שעברו דורות בל\"ג. אבל הרי ע\"ז אנו דנין דלפחות ספיקא הויא אף לדבריהם, ומהזמן אין ראיה עכ\"פ להכריע הספק גם באישי המין. דיש לחלק טובא ביניהם, דבזמן לא נשאר כלל רושם מהחולף מה גם אין בו ממש כלל משא\"כ הכא שי\"ל דדומה יותר לאילו כל אישי המין קיימים, ולפחות הוי כגוף אחד ארוך שעכ\"פ זהו רושם וזכר גם מהיותר ראשון. וא\"כ כיון שאין הכרח מהזמן גם לשטתם שיוכל להיות דורות בל\"ג, וזה ודאי שכל הדורות היו מחודשים ע\"כ כיון שהכל מחודש, ובמחודש א\"א שיהי' בל\"ג אף פ\"א א\"כ ממילא נפשוט שהיו רק דורות בגבול (לא דמי למ\"ש יהיה המתנועע כו' פעמים אין תכלית כו' דהתם היינו ענין הזמן החולף אין. אבל הכא החולף יש לפנינו הן בפ\"ע הן עכ\"פ הכל גוף אחד וידוע שהוא מחודש. וכיון שהוא מחודש ממילא יודו ג\"כ שלא היה מספר בלי גבול. ויש בפנים אריכות מעט יותר מהצריך).\nיד <b>קיצור.</b> הענין הנה אם נצייר שאחד נשאר קיים באיש או בעפר בפ\"ע, מכל דורות שחלפו, והרי א\"כ הכל מחודש וא\"א שילך אל קדמות כהנ\"ל אות י\"א אזי יודו שא\"א ג\"כ שהיו דורות בל\"ג ושילך אל לא תכלה, דגם לדבריהם הא בהא תליא כנ\"ל סוף אות י\"ג. וא\"כ בכה\"ג ודאי אמת שהוא מושכל"],[3000730200,"ראשון שא\"א שילך אל לא תכלה ושהוא שקר. ותוכן המושכל ראשון היינו כיון שגם היותר מוקדם עומד לפנינו ובהכרח שהוא מחודש א\"כ א\"א ושקר שילך זה אל הקדמות, שהמחודש אינו קדמון, וממילא שא\"א שילך אל לא תכלה אף לדבריהם. ואף את\"ל שהי' ללא תכלה מה שהוא שקר עכ\"פ הוא מחודש. אלא שא\"צ לזה כי גם הם יודו שכיון שהוא מחודש בהכרח שלא הי' רק בגבול. וכשנשאל מהם א\"כ מה בין זה לענין מציאות הזמן דהא על כרחינו הם ואנו מודים שכל חלקי הזמן שחלפו ועברו היו מחודשים כל חלק וחלק אין גם אחד שלא הי' מחודש, ע\"ד כל יום ויום שהוא מחודש. וכיון שכל חלקי הזמן שעברו היו מחודשים א\"כ הכל מחודש. וא\"כ לא הי' הזמן רק בעל גבול, וכדעת הגאונים והמדברים. ואיך אתם הפלסופים המכחישים סוברים שהזמן החולף הוא ללא תכלה ואינו מחודש. מאי שנא מציור אישי המין הנ\"ל אם אחד מכל דור הי' קיים שאתם מודים כיון שהכל מחודש א\"א שילך אל לא תכלה ושיהיה קדמון. וה\"נ הרי כל הימים והשנים שחלפו היו מחודשים, ושקר שמהכל המחודש יהיה קדמון שהמחודש אינו קדמון. ואין לומר שבאמת יספקו מחמת הזמן גם בהדורות אף אם איש אחד מכל דור קיים באיש, לומר שאפשר שהיו בל\"ג וקדמון במין דהא ודאי אי אפשר שיכחישו בזה דכיון שהאיש מהדור היותר קדמון ישנו גם עתה בזמן היותר מתאחר א\"כ ב' קצוות של הדורות שחלפו לפנינו ואנו רואים שגם הקצה היותר ראשון מחודש א\"א להכחיש שהכל מחודש. אלא על כרחם יסכימו לחלק בין זה להזמן אף שהחילוק אינו מספיק ומקובל בשכל ממש ויאמרו דהגם כשהחולף ישנו עתה והוא מחודש מודים אנו שהכל מחודש. וזהו ענין אישי הדורות שחלפו אם א' מכל דור קיים. משא\"כ בהזמן כיון שהשנים או השמיטים או היובלות שחלפו אינן נמצאים עתה אע\"ג דהם כמו אישי הדורות שחלפו, שכל היובלות שחלפו היו מחודשים וכמו הדורות עכ\"ז אפשר שכה\"ג יהי' המקובץ והכל בלתי מחודש. ואף שאמרת ג\"כ הרי כל החלקים החולפים היו מחודשים בהכרח, עכ\"ז יאמרו דבכה\"ג אינו מובן איך שאעפ\"כ אפשר שיהי' ענין זה בלתי מחודש. אבל עכ\"ז לא יכחישו שאם א' מאישי המין מכל דורות שחלפו קיים באיש או בעפר בפ\"ע והוא מחודש ודאי הכל מחודש. ותדע דכה\"ג מצינו שחילקו כן דהנה הם הניחו שא\"א שיהיו גשמים רבים בפועל בלי גבול ותכלית, מחמת שהמופת מראה כן. וכשהקשו ע\"ז מהזמן שהוא ג\"כ ענין ימים רבים שכל אחד הוא בעל גבול ואעפ\"כ מקיבוצם נעשה משך ימים ושנים בלי גבול ובלי תכלית. ומ\"ש מגשמים רבים, הלא המופת ההוא שייך גם בזמן. עכ\"ז מפני שמיאנו להודות בהזמן שאינו מחודש לא ביטלו מפני זה המופת על הגשמים רבים, ועשו חילוק לקבל המופת הנ\"ל בענין בלתי בעל תכלית בבת א' ר\"ל בזמן א' ובין בוא זה אחר סור זה, דהתם לא מאמינים להמופת, כיון שנראה להם שבע\"כ הזמן בבע\"ת. (מה שבאמת זה אינו כי קדמות הבורא ית' אינו בבחי' זמן כלל) אבל עכ\"ז לא מפני זה יבוטל המופת שהגשמי' א\"א שיהיו בלתי בעל תכלית כיון שיש לחלק בין זה להזמן דשאני בב\"א מבוא זאס\"ז. וכמ\"ש וכש\"כ לענין חילוק הנ\"ל דההנחה דכשאיש אחד מכל דור לפנינו וכולם מחודשים ודאי הכל מחודש. זה א\"א להכחיש יותר מהא דגשמים בב\"ת אי אפשר כי זהו ע\"ד המופת. וזה נראה בחוש כיון שב' הקצוות לפנינו והקצה הראשון ג\"כ מחודש. וגם שבהכרח בכה\"ג אחד הוא כנגד כולן ועודף עליהם למעלה, כי הכל הולך ומתמעט מלמטה למעלה עד שמגיע להיותר מוקדם והוא כנגד כולן וקודם להן. וא\"כ כיון שגם הוא מחודש מה יש לדבר בזה עוד, ולכן אם מפני שהזמן יכריח שאפשר שימים מחודשים שחלפו ילכו אל קדמות הלא זה ממש מה שחילקו שאע\"פ שבב\"א א\"א להיות גשמי"],[3000730212,"בב\"ת עכ\"ז בזאס\"ז אפשר שילכו אל לא הכלה. ומה גם כי הזמן כשנאמר שהוא המשך הבלתי משוער בתנועת הגלגל א\"כ אינו ענין שיש בו ממש כלל ואין ואפס ממש, רק שהוא המשך של הקדמון, פי' כי בעל העקרים אף שסובר שהזמן מחודש ונברא סובר שקודם התהוות הזמן הי' בחי' משך הבלתי משוער בתנועת הגלגל. וזהו המשך בבע\"ת של הבורא ית' שקדם לעולם ולזמן. אמנם הרמ\"ע בע\"מ<sup data-n=\"153\">*</sup> מאמר אם כל חי ח\"א סי' ט\"ז חלק ע\"ז ופי' דמ\"ש לכל זמן ועת לכל חפץ תחת השמים, היינו שממעל לשמים אין שייך שום זמן כלל, ואפילו המשך הבלתי משוער כו' ע\"ש. וכ\"ה באמת כי העבר וההוה והעתיד שוין אצלו ית'. ואי לזאת אף לדברי המכחישי' האומרי' שהזמן אינו מחודש אין לומר עכ\"פ יותר מהמשך הבלתי משוער, והוא אין ואפס, ובלתי מהות, רק שהוא המשך של הבורא ית' הקדמון. אלא שלפי האמת הבורא ית' הוא למעלה מהזמן לגמרי כנ\"ל עכ\"פ אף לשטתם זמן כזה אף שכל חלקיו מחודשים כיון שהוא ענין המשך שיש בו עבר הוה ועתיד. עכ\"פ לא דמי לאישי הדורות מכמה חילוקים, שיש בכל דור ממש. משא\"כ הזמן הנ\"ל שהוא רוחני והעקרים קראו דמות זמן לבד, והאישים נולדו זמ\"ז משא\"כ המשך הנ\"ל. א\"כ ברור שגם לדבריהם אין הזמן מונע אמיתית הנחה הנ\"ל הנראה בחוש.\n<b>ומעתה</b> גם שאין איש א' מכל דור במציאות ממש בפ\"ע אף שג\"ז אינו מוכרח כמש\"ל תחלה אות י\"ב, נראה למי דומה. ונאמר דכיון דודאי עכ\"פ העפר הנשאר מהגופות ראוי יותר שיקרא על שם הדור היותר ראשון. א\"כ ראוי יותר לדמותו לאישי הדורות הקיימים ממה שהי' דומה לענין הזמן הנ\"ל מכמה טעמים. האחד משום דעכ\"פ אפשר לומר רואין כאילו איש א' מהדור היותר מוקדם קיים גם עתה באיש, או אפילו כל הדור. וכל דבר שאפשר לומר עליו רואין הגם שבסיבת מה לא נעשה כן אין זה מונע מלומר כאלו נעשה כן שזה מוסכם בגמ' וגם הפילוספי' יודה ע\"ז מאחר שזהו ענין שכלי. משא\"כ הזמן שהוא ענין רוחני א\"א בשום אופן לצייר בו ענין רואין הנ\"ל שאפילו היום דאתמול א\"א שיהי' עתה כ\"ש המשך הבלתי משוער בתנועת הגלגל. והיינו שענין הזמן בהכרח ענינו ומהותו שכל חלקים אינם באים אלא דוקא זה אחר סר זה ואי אפשר לצייר שיהיה הזמן העבר קיים בזמן ההוא משא\"כ האנשים הרי אדרבא כל אחד נולד ממי שלפניו וגדל אתו עמו זמן רב עד שמת מי שלפניו מחמת חלישת גופו א\"כ הציור יכול לקבל שיהיו כל האנשים שהיו מימות עולם יחד ובבת אחת. לכן יש לדון עליהם כאילו כולם יחד ממש.\n<b>הג'</b> די\"ל ממש שדור היותר מוקדם קיים עפרו כעת ממש כיון דעכ\"פ נת' שהעפר הנשאר מהגופות ראוי שיקרא יותר לדור היותר מוקדם. א\"כ מה נפ\"מ אם היה צבור בארץ בפ\"ע שהייתי יכול להכריח שכל הדורות מחודשים שהרי ב' קצוות לפנינו וגם הקצה היותר ראשון לפנינו ומחודש. ומה נפ\"מ אם אינו צבור בפ\"ע והי' בינתיים ממנו ג\"כ גופות אחרים נהי' רואים מה שבינתיים כאילו אינו וכאילו הי' צבור בפ\"ע שא\"כ הדור היותר ראשון ויותר קדמון ישנו גם עתה והרי גם הקצה הראשון מחודש בבירור. והגע עצמך אילו בדורות גבוליים כמו אלף אלפים דורות היש שום חילוק אם העפר של דור הראשון צבור בפ\"ע או אם נתערב והי' ג\"כ בגופות אחרים עכ\"פ הוא זכר ורושם של דור הראשון ג\"כ ונשפוט עליו כאילו דור הראשון קיים עתה באיש מחמת שזהו עפר שלו א\"כ כמ\"כ כאן אפילו את\"ל שהדורות היו ללא תכלה מ\"מ זה העפר מעיד על דור היותר מוקדם כאילו קיים באיש. ועוד שזה עכ\"פ לא נתברר שהיו הדורות ללא תכלה רק נתברר שכל דור היותר מוקדם מחודש א\"כ ממילא מוכרח ג\"כ שהיו דורות",[["153","*","<b>הרמ\"ע בע\"מ</b>: ראה גם לעיל לג, א."]]],[3000730222,"רק בגבול. דגם לדבריהם הא בהא תליא כנ\"ל. היינו דאילו הי' אפ\"ל שיש כאן דור שאינו מחודש שפיר י\"ל שאינו מובן איך יעברו בל\"ג זה אחר זה כו' לדבריהם אבל בהפך כשברור שאין שום דור מחודש והיינו ע\"י שהוא לפנינו כנ\"ל דבהכרח העפר הוא מהיותר ראשון וכשאינו מחודש ה\"ז ראשון בזמן ממש. א\"כ ממילא יודו ג\"כ ששקר שילך זה אל לא תכלה בזמן, וצדקו ד' האומר שמושכל ראשון שזהו שקר. והחילוק בין זה לזמן אף לדבריהם יש לחלק טובא כנ\"ל זה וסוף אות הקדום גם משום שאישי הדורות הולכים ומתמעטים לפנים ויסתיים בהכרח בא' שהוא נברא לא ע\"י זכר ונקבה והיינו אדם הראשון. שכיון שאם היה העפר מכל הדורות קיים מוכרח שכל הדורות מחודשים א\"כ לא מפני שמה שבינתיים אינו קיים ישתנה הדבר כיון שעכ\"פ נאמר שהעפר מדור היותר מוקדם קיים וישנו ממש. (קיצור אם נצייר שאחד מכ\"ד נשאר קיים יודו שהמין מחודש ובע\"ג. וכשנשאל מהם א\"כ מדוע הזמן אינו מחודש יחלקו מפניש בא זאס\"ז ואין החולף קיים. ומעתה גם שאין איש א' מכ\"ד בפ\"ע נראה למי דומה ונאמר דומה להנ\"ל יותר מלזמן מצד ג' טעמים הא' רואין הב' מחמת מ\"ש האוצ\"נ בכוזרי מאמר ה' סי' י\"ח ספ\"א הג' די\"ל שדור היותר מוקדם קיים עפרו באיש רק מה שבינתיים אחריו אינו).\n<b>ועוד</b> יש לצרף לענין רואין הטעם הג' שנת\"ל סוף אות י\"ד די\"ל ממש שהדור היותר מוקדם קיים עפרו ממש כעת כו' ע\"ש ועי\"ז נתחזק עכ\"פ ענין הרואין יותר.\nבחלק ג' המתחיל בספר יסוד האמונה תחת פרק ג' נמצא רשום למטה<sup data-n=\"154\">1</sup>.\n<b>אמאי</b> לא נצא ספר מזמן בלי גבול כמו שהארץ קדמוני' וא\"ת ספר מחודש הא ע\"כ הוציא' ארץ תבואו' בלי גבול. גם א\"כ אנשי' שנולדים מאו\"א וקדמוני' א\"כ קדמ' קדימה לקדימ' שהם הי' עם הארץ ואו\"א קדמו לארץ. גם א\"א שיהי' ספר כן מזמן בל\"ג שזה דבר שא\"א להוציאו בפה כו' או כ\"ז שקר מוחלט.\nתחת פרק ח' ופרק ט' נמצא רשום למטה<sup data-n=\"155\">2</sup>.\n<b>אלא</b> שהם אומרים מפני שא\"א גשמי' בלי תכלי' משא\"כ בבא זאס\"ז אבל י\"ל לא מטעמייהו כ\"א מטעם הנ\"ל ולפיכך אפי' בבא זאס\"ז רואין כאלו כו'.\nתחת פרק יוד נמצא רשום למטה<sup data-n=\"156\">3</sup>.\n<b>אלנות</b> א' מב' אופנים או זה יוצא מזה כשלשול הדורות או שנטעו אדם כמו אדה\"ר יציר כפיו וא\"א שיצאו כולם זמ\"ז.",[["154","1","שייך לדף ל, א."],["155","2","שייך לדף 70."],["156","3","שייך לדף לו, א."]]],[3000730058,"אלה העדות והחוקים והמשפטים וגו'. ואיתא ברבות ר\"פ ויקהל, וז\"ל ד\"א ואל מי תדמיוני ואשוה, א\"כ יאמר קדוש, שאו מרום עיניכם וראו מי ברא אלה, בישעי' סי' מם, בזכות מי נבראו אלה תולדות השמים והארץ ובזכות מי הם עומדים בזכות אלה שמות בני ישראל, ר\"פ שמות, ואלה בזכות מי הם עומדים בזכות אלה העדות והחוקים והמשפטים כו' עכ\"ל. והנה ענין תולדות השמים והארץ מבואר במדרש פ' בראשית פי\"ב שמים וארץ הן הן עיקר ברייתו של עולם והוציאו תולדות היינו תולדות הארץ הן אילנים ודשאים וג\"ע, ותולדות השמים הם חמה ולבנה ומזלות, ועיין מזה ג\"כ בגמרא פ\"ה דיומא דף נ\"ד ע\"ב, ושם וחכ\"א אלו ואלו מציון נבראו כו'. והענין כי השמים והארץ הם ז\"א ונוק' דאצילות כי שמים אש ומים הם המדות חו\"ג כו', והארץ היא בחי' מל' שהיא הדבור עליון כו', ועמ\"ש מענין ארץ בת\"א פ' מקץ ד\"ה ענין חנוכה"],[3000730100,"ומ\"ש בד\"ה והיה מספר בנ\"י ובד\"ה השמים כסאי ובד\"ה שובה ישראל, גם חו\"ב נק' שמים וארץ עילאין. והנה התהוות העולמות הוא ע\"י חו\"ב שנק' אין ויש ונמשכו ע\"י המדות והדבור וכמ\"ש במ\"א ע\"פ הקול קול יעקב, ונק' בחי' זו יחוד או\"א התמידי שהם תרין ריעין דלא מתפרשין כי תמיד צ\"ל נמשך מאין ליש. וז\"ש רז\"ל מציון נבראו בחי' יסודות דזו\"נ שעל ידם נמשך ההשפעה והיחוד כו'. ולכן נק' תולדות השמים והארץ כמו דו\"נ המזדווגים יחד ועי\"ז מוציאים תולדות לעולם כך ע\"י חיבור ויחוד השמים והארץ שהם המדות והדבור מזה הוציאו תולדות כו' ושרש המשכה זו נמשך מיחוד חיצוניות דאו\"א כמ\"ש בפע\"ח שער הק\"ש. וזהו בהבראם בה' בראם וכמ\"ש רז\"ל מנחות כ\"ט ב' ע\"פ כי בי\"ה צור עולמים ביו\"ד נברא העוה\"ב בה' נברא העוה\"ז והיינו כי יחוד חיצוניות נק' עיקרו ע\"ש הבינה שהיא אות ה' והיינו להיות ישסו\"ת שניהם רמוזים באות ה', וזהו בה' בראם. אבל העוה\"ב עיקרו מבחי' יחוד פנימי דאו\"א שהוא אות יו\"ד כי או\"א עילאין שניהם רמוזים באות יו\"ד כמ\"ש בע\"ח והביאו הרמ\"ז ס\"פ קרח<sup data-n=\"158\">*</sup>. והענין כי בינה היא מקור ההשתלשלות וזהו ענין בינה מקננא בכורסייא, הוא בריאה שלהיות בריאה מאין ליש זהו ע\"י מסך הבינה כו' כמ\"ש בע\"ח שער סדר אבי\"ע. משא\"כ החכמה היא למעלה מהשתלשלות כמ\"ש בע\"ח שם שבחי' חכמה זו היא חכמה דא\"ק שבה ועל ידה מאיר בחכמה דאצילות כו' ע\"ש, וזהו יחוד פנימי דאו\"א שנמשך מחכמה דא\"ק כו'. ואפ\"ל עוד דתולדות השמים והארץ שהם זו\"נ הם המלאכי' שהתהוותם הוא ג\"כ בשי\"ב וכמארז\"ל ע\"פ ועוף יעופף ועוף זה מיכאל כו', והיינו שהתהוותם ע\"י דיבור העליון כמ\"ש בדבר ה' שמים נעשו וברוח פיו כל צבאם. והנה בהבראם באברהם פי' בזח\"א ד\"ג סע\"ב, שהוא בחי' אבר מ\"ה היינו זיווג יסוד ומל' ע\"י יסוד והיינו כנ\"ל בענין וחכ\"א מציון נבראו כו', וזהו אלה תולדות כו' ו\"ק דז\"א הם בחי' אלה שהוציאו תולדות ע\"י אבר מ\"ה, וזהו מי ברא אלה מי היינו בינה שנתלבשה בו\"ק דז\"א וע\"י ברא אלה מבחי' ברא נעשה אבר כו'. וע' זח\"ב ר\"פ אלה פקודי ר\"ך ע\"ב כתיב הכא אלה פקודי המשכן וכתיב התם אלה תולדות השמים כו' שנמשכו ע\"י החסד בהבראם באברהם כו' ועמ\"ש ע\"פ אלה פקודי המשכן שהוא ענין יחוד זו\"נ מלשון חייב אדם לפקוד את אשתו.\n<b>קיצור.</b> תולדות השמים והארץ שהם המדות והדבור הם המלאכים ושאר נבראים מציון יסוד המזווג המדות והדבור נבראו, ושרשו מיחוד חו\"ב ונק' חיצוניות חו\"ב וזהו בה' בראם, משא\"כ העוה\"ב נברא ביו\"ד יחוד פנימי דחו\"ב, גם בהבראם באברהם אבר מה, אלה תולדות ע\"ד אלה פקודי כו': \nב <b>והנה</b> להבין קצת הפסוק שאו מרום עיניכם וראו מי ברא אלה, דמשמע שזה נראה בעין וכמ\"ש ומבשרי אחזה אלוה, י\"ל שאחד מן הראיות מרומז ג\"כ בתיבת אלה דהיינו מ\"ש אלה תולדות השמים, ועוד ע\"ד מ\"ש ברבות בראשית פי\"ב ע\"פ אלה תולדות השמים וז\"ל כל מי שיש לו תולדות מת ובלה ונברא ואינו בורא כו' א\"כ זהו שאו כו' מי ברא אלה דהיינו אלה תולדות השמים והארץ א\"כ שהשמים והארץ יש להן תולדות הם נבראים ולא בוראים. וא\"כ שאו מרום עיניכם וראו מי כו', וענין פי' הרבות כל מי שיש לו תולדות, היינו דכמו האנשים הם הווים ונפסדים, כן ודאי כללות מין האנשי' מחודש ונברא, שהרי שום איש החולף 1) תחת<sup data-n=\"159\">*</sup> הגליון הי' בכי\"ק: תולדות השמים והארץ מדבור מלאכים ונש\"י עלו במחשבה אך תורה רצון עליון ע' ד\"ה מי מנה וג\"כ מי אלה סתים וגליא ע\"ש בענין מי מנה ומספר ואלה נשמות בנ\"י מפנימי' או\"א ע' חמשה קנינים",[["158","*","<b>קרח</b>: כאן הוא סיום העמוד שאליו שייך שולי הגליון. ובאוה\"ת ואתחנן הוא אחר הקיצור דסעי' א."],["159","*","<b>תחת</b>: בבוך 234 גוכתי\"ק נשרפו שולי הגיליון."]]],[3000730139,"לא <b>היה</b> כ\"א נברא ולא בורא, א\"כ אינו קדמון באיש עכ\"פ, וכיון שכל האנשים שחלפו היו מחודשים, הרי גם המין מחודש, וכמ\"כ שמים וארץ יבולו כדכתיב שמים כעשן כו' כבגד תבלה, כיון שיש להם תולדות ותולדותיהן מתים א\"כ גם האבות כיוצא בהן, כי התולדה היא דוגמת האב, ודבר זה קרוב למ\"ש רס\"ג מ\"א פ\"א והראיה השלישית מן הראיות כו' שאינה נמלטת מצמח וחיים שהם מחודשים וידוע כי מה שאינו נמלט מן המחודש שהוא כמוהו כו' וכן בשמים כו' והביא ראיה מפסוק אנכי עשיתי ארץ ואדם עליה בראתי כו' עכ\"ל, ובמ\"נ ח\"א פע\"ד הדרך הרביעי הוא כראיות הרס\"ג ומה שהשיב ע\"ז אינו מספיק חדא שהקדמתם הי\"א שהזכיר פע\"ג הוא אמת כמ\"ש במ\"א הב' שאף לדברי החולקים ע\"ז, ויוכל להיות מקרים זאס\"ז לבלית תכלית. אכן כח ראיה זו אינו ע\"ד שחשב המ\"נ שכל המקרים סך כולם יחד היו בע\"ג, כ\"א מאחר שעכ\"פ כל א' מחודש והוא תולדה של הארץ ממש ודבק בו, א\"כ האב כמו התולדה כיון שהאב שהוא העצם לא קדם להתולדות שהן המקרים רק זמן מוגבל לבד כמו קדימת הארץ להחטים הגדילים וצומחים ממנה אינו אלא שנה אחת והחטים הם ודאי מחודשים שא\"א להכחיש שהארץ קדם להם. וא\"כ כיון שהחטים שהם מקרה מוכרח שהם מחודשים מפאת שמוכרח שמקורם שהוא הארץ קדמה להם. וכיון שהארץ שהיא העצם לא קדם להתולדה רק זמן מוגבל א\"כ בהתוסף זמן מוגבל על המחודש הוא ג\"כ מחודש וזהו מאמר המד\"ר כל מי שיש לו תולדות הוא נברא, הרי שראיות רס\"ג אינו ע\"ד שחשב המ\"נ. ועוד יש לחזק ולסייע דבריו בטענה עכ\"פ ממ\"ש במ\"נ הדרך הראשון כו' שאיזה<sup data-n=\"160\">*</sup> דין שימצא לגשם אחד כו', ומתולדה על אב יש לחייב יותר. ומזה יובן ענין שאו מרום עיניכם וראו מי ברא אלה פי' ע\"י שתראו תולדות השמים והארץ תראו שהם נבראים שכל מי שיש לו תולדות הוא נברא ואינו בורא כו', וא\"כ וראו מי ברא אלה.\n<b>ועוי\"ל</b> ועיקר בכוונת הרבות כל מי שיש לו תולדות כו' קאי אף למעלה יותר דהיינו גם בשמים וארץ הרוחניים, והוא בהקדים מ\"ש ברכות בקהלת צ\"ד ד' ע\"פ יש אחד ואין שני גם בן ואח אין לו. שם סי' ד' ח', וז\"ל יש אחד זה הקב\"ה שנאמר ה' אלקינו ה' אחד, ואין שני שאין לו שותף בעולמו, גם בן ואח אין לו כו' אלא שחבב הקב\"ה לישראל וקראן בנים שנאמר בנים אתם לה' אלקיכם, וקראן אחים שנאמר למען אחי ורעי, והקשו שם המפרשים שהרי לפ\"ז יש לו בן ואח, והכתוב מפרש גם בן ואח אין לו, וגם הכתוב במשלי סי' למד מי עלה שמים וירד כו' מה שמו ומה שם בנו כי תדע, וארז\"ל ברבות נשא פי\"ב דרמ\"ט ב' מי עלה שמים זה הקב\"ה כו' מה שמו, צור שמו, שדי שמו, ה' צבאות שמו, ומה שם בנו כי תדע בני בכורי ישראל עכ\"ל. וכן פי' בזח\"ב ויקהל קצ\"ז ע\"א מה שמו הוי', ומה שם בנו ישראל, דכתי' בני בכורי ישראל ובמק\"מ שם פי' מה שמו אבא, ומה שם בנו ישראל פי' זעיר, וכ\"כ הרמ\"ז שם מה שמו חכמה, ומה שם בנו תפארת. וכן איתא עוד בפ' בלק דקצ\"א ע\"ב, וכ\"כ בת\"א פ' יתרו בד\"ה ענין האבות הן הן המרכבה, וז\"ל כנודע שיש ב' בחי' אדם, אדם הראשון הוא בחכמה ואדם תתאה הוא ז\"א, וזהו מה שמו ומה שם בנו כו' עכ\"ל. אך כ\"ז יובן בהקדים מה שידוע שיש ב' בחי' סוכ\"ע וממכ\"ע, פי' ממכ\"ע הוא כמשל הנשמה שמחיה את הגוף ומתלבשת בו להחיות בבחי' התחלקות מחשבה ודבור ומעשה והתלבשות המוחין בראש כו', וכן בכל אבר חיות פרטי וכך כתיב אתה עשית את השמים ושמי השמים כו' הימים וכל אשר בהם ואתה מחי' את כולם, שהחיות ההוא מבחי' ואתה מחיה את כולם מתלבש תוך עלמין",[["160","*","<b>שאיזה</b>: כ\"ה בכת\"י מעתיק. (בגוכתי\"ק מהדו\"ק ליתא קטע זה). ובאוה\"ת פ' ואתחנן הגירסא: שאינו."]]],[3000730166,"וממלא הוא בכל עולם לפי ערכו בשמי השמים גילוי בחי' עליונה יותר מבשמים, וכן בשמים יש גילוי בחינה יותר עליונה מבארץ כמו שנראה בחוש, ובחי' סוכ\"ע הוא אור וחיות אלקי שאינו מתלבש תוך עלמין ממש ואין פי' סובב עולה וסובב מלמעלה אלא שהוא ג\"כ תוך עלמין אלא שאינו מתלבש בהם וכמ\"ש הלא את השמים ואת הארץ אני מלא אני דוקא שאין בחיות ההוא בחי' התחלקות כלל אני ראשון ואני אחרון קדמון לכל הקדומים כו', משא\"כ בחי' ממכ\"ע הוא בבחי' גבול מהלך ת\"ק שנה כו' רגלי החיות כו'. והנה ב' בחי' אלו הן ג\"כ ב' שמות הוי' הוי' שבפסוק ויקרא הוי' הוי' אל רחום כו' כמשנ\"ת בתו\"א פ' בשלח בד\"ה וירא ישראל. והנה שרש נש\"י אף שעלו במחשבה וא\"כ הם למעלה מהמלאכים וכל צבא השמים שנמשכו ע\"י הדבור מ\"מ שרשן ג\"כ משם הוי' הממכ\"ע, והיינו ששרשן מבחי' חכמה עילאה, וחכמה היא הנק' מחשבה וכמ\"ש מזה בד\"ה את שבתותי תשמרו ובד\"ה כי כארץ תוציא צמחה ובד\"ה שבת שבתון, אשר זאת היא תכלית ירידתם בגוף שע\"י אתכפיא ואתהפכא, ובירור נה\"ב עי\"ז דוקא יתעלו בבחי' סוכ\"ע, אבל שרשן מבחי' ממכ\"ע. ועיין עוד מזה בתו\"א ע\"פ יביאו לבוש מל'. והנה מצד בחי' ממכ\"ע שהוא בחי' ציור אדם שייך לומר שנש\"י הם בחי' בנים למקום. וכמו שהבן הוא טפה הנמשך ממוח האב ממש כך ממש הנר\"נ של כל ישראל נמשך מחכמתו ית' כמ\"ש בתניא ח\"א פ\"ב, והמלאכים הן רק מהארה לבד הנמשך מחכמה כמו הארת השכל ע\"י הדבור אבל הנשמות נמשכו מעצמיות חכמה עילאה כמש\"ש בק\"א. וזהו ענין מה שמו היינו ח\"ע ומה שם בנו ישראל כו'. אכן כ\"ז מצד בחי' ממכ\"ע, וזהו ענין אביהם שבשמים אור אבא המלובש בז\"א כו', אבל מצד בחי' סוכ\"ע אשר גם החכמה היא נחשבת כעשייה גופנית כמ\"ש בתניא ח\"ב פ\"ט. א\"כ בבחי' זו לא שייך לומר בן כלל, ובבחי' זו נאמר כי לא אדם הוא כמ\"ש בתו\"א פ' יתרו בד\"ה זכור ושמור בדבור אחד נאמרו. וזהו יש אחד ואין שני, פי' באצי' בע\"ס יש דכר ונוק' משפיע ומקבל. משא\"כ בעצמות המאציל ית' חד ולא בחושבן, לית שמאלא בהאי עתיקא, ועז\"נ ואין אלקים עמדי. וע' מזה בתו\"א פ' נח בביאור ע\"פ מים רבים בסופו וז\"ל וזהו שאנו אומרים בק\"ש שמע ישראל ה' אלקינו יחוד או\"א תרין ריעין כו' ה' אחד יחוד זו\"נ בשכמל\"ו יחו\"ת וזהו הכל בחי' יחוד היינו כשנמשך למטה והיו לאחדים משא\"כ מעשה המצות כו' אנכי מצוך אנכי הוא בחי' כתר עכ\"ל. הרי בחי' כתר הוא למעלה מבחי' דו\"נ כי הוא בחי' יחיד ממש. והנה בבחינה זו גם בן ואח אין לו, ומה שנק' נש\"י בנים ואחים זהו בבחי' ממכ\"ע בהתלבשות אור א\"ס בע\"ס, וזהו שחבב הקב\"ה לישראל וקראן בנים כו' היינו שנתלבש בע\"ס להיות איהו וגרמוהי חד. ועפ\"ז יובן מאמר המדרש כל מי שיש לו תולדות כו' נברא ואינו בורא, דהנה החכמה שהיא ראשית ההשתלשלות נק' ג\"כ בריאה כמ\"ש והחכמה מאין תמצא יש מאין ממש. וזהו שכל מי שיש לו תולדות היינו דשייך יחוד דו\"נ הוא נברא ואינו בורא כי בחי' זו שייך רק בע\"ס שנקראים נברא לגבי אור א\"ס ב\"ה, שאפילו א\"ק נקרא אדם דבריאה כו'. וזהו אשר ברא כו' חתן וכלה וידוע כי חתן וכלה הם זו\"נ דאצילות ונקרא בחי' זו בשם בריאה. ומזה יובן ענין שאמרו ואלה ר\"ל נש\"י בזכות מי הם עומדים בזכות אלה החוקים כו', כי נש\"י אף שעלו במחשבה ונק' בנים ואחים וזהו אלה שמות בנ\"י שמות ממש מ\"מ הן בבחי' ממכ\"ע והן למעלה מבחי' אלה תולדות השמים כו' וכמ\"ש במ\"א<sup data-n=\"161\">*</sup> באריכות ע\"פ אלה תולדות נח אלה פסל את הראשונים היינו שהן פנימיות יותר מבחי' אלה תולדות השמים כו' מ\"מ כיון ששרשן ממכ\"ע הם עומדים בזכות אלה החוקים כו' שהן המשכת אשר אנכי מצוך בחי' סוכ\"ע כו'.",[["161","*","<b>והן</b>: במ\"א — נדפס באור התורה. [ כרך א פ' נח]."]]],[3000730186,"<b>(קיצור.</b> ענין וראו מי ברא אלה ע\"ד אלה תולדות השמים וכל מי שיש לו תולדות נברא ואינו בורא. ועוי\"ל ע\"ד יש אחד ואין שני גם בן ואח. וקשה הכתיב מה שמו ומה שם בנו, אלא כי יש ממכ\"ע וסוכ\"ע ב' שמות הוי', ונש\"י שרשן מחכמה ממכ\"ע, וזהו שנק' בנים לאביהם שבשמים ח\"ע אבל סוכ\"ע כי לא אדם הוא, אין שם דו\"נ וממילא לא בן ולא אח. וזהו כל מי שיש לו תולדות היינו ע\"ס דאצילות הוא נברא כי והחכמה מאין תמצא, בורא קדושים ישתבח שמך. ולכן תכלית ירידת הנשמות בגוף שע\"י המצוות מתעלים בבחי' סוכ\"ע אנכי מצוך כו'): וכה\"ג<sup data-n=\"162\">*</sup> מצאתי<sup data-n=\"163\">*</sup> אח\"כ בכת\"י מו\"ח ז\"ל מ\"ש בחורף תקס\"ג מאדמ\"ו ז\"ל אשר למעלה מאצילות לא שייך שום זווג כו' כי הוא יחיד כו' ועוד כי הזווג זהו השפעה מעצמיות כעין עילה ועלול ובא\"ס ב\"ה חלילה לומר כן. וגם מבחי' כתר נמשך רק דרך שערות לבד שזה עד\"מ אינו נוגע לעצמיות כלל.\nג <b>ועתה</b> צ\"ל מהו ענין מי ברא אלה, היינו בענין אלה תולדות השמים וכמ\"כ י\"ל אח\"כ בחי' אלה שמות בנ\"י ובבחי' אלה העדות והחוקים כו' הנה פי' מי הוא בחי' אין מה שאינו מושג, הוא ברא אלה, אלה היינו מה שמושג ונראה והוא היש הנברא, שהיש מתהוה מבחי' אין מה שאינו מושג, וזהו מי ברא אלה. וא\"כ פי' מי ברא אלה, זהו עצמי ענין שהבריאה היא יש מאין, וצ\"ל מפני מה נקרא יש מאין והלא ממך הכל כתיב, אך הענין כי הנה יש סדר השתלשלות מעילה מעלול זהו נק' יש מיש שיש להעלות ערך ויחס עם העילה, אבל הנבראים לגבי הבורא ית' אין ערוך כלל ואינם מתהוים בסדר ההשתלשלות כ\"א בדילוג הערך כו' ע\"כ נק' יש מאין. ועמ\"ש מזה בד\"ה ואתחנן אל הוי' גבי ובטובו מחדש כו' מחדש ממש דבר חדש, משא\"כ הוצאת יש מיש אינו כלל התחדשות כ\"א גלוי ההעלם.\n<b>ולבאר</b><sup data-n=\"164\">*</sup> הדברים יש להעתיק הדרוש המבואר במ\"א<sup data-n=\"165\">*</sup> וז\"ל הנה תכלית העבודה שעתה הוא הכל להמשיך מן ההעלם לגלוי כו' (כנז' במ\"א ע\"ש) ולכך צריך להיות ההתבוננות מגדולתו ית', מדברים נמוכים שלמטה דוקא, פי' שהוא ההתבוננות איך שמהוה מאין ליש גשמי ממש. (שהם עולמות שהם יש ממש ומתהוי' מאין כמשי\"ת) שבזה ההתבוננות נמצא גדולתו ית' יותר מן ההתבוננות מעולמות עליונים הגבוהים (שהוא עולם האצילות כו') שאף שההתפעלות הלב היא יותר לכאורה מההתבוננות בעולמות עליונים וגבוהים כו'. אך באמת ניכר שבחו וגדולתו ית' בזה הבריאה מאין ליש גשמי ממש יותר מן מעלת עולמות הנאצלים כו', כי כל העולמות העליונים הם נתהוו הכל בבחי' סדר השתלשלות עלה ועלול, ואין זה נק' בחי' התחדשות מאין ליש ממש, שהרי אין זה דבר מחודש כלל, שאף קודם שנתהוה העלול, היה בהעילה תחלה בהעלם בבחי' ביטול, ורק אח\"כ יצא מההעלם לגילוי כו' כמו כשנאצל חכמה מכתר, הרי גם קודם שנאצלה היתה בהעלם בכת\"ר שהוא למעלה מן החכמה כי יש בכלל מאתיים מנה, והיתה החכמה בכלל בלמעלה מן החכמה שהוא הכת\"ר רק שאז היתה שם בהעלם ובבחי' ביטול כו', ואח\"כ כשנאצלה היא, היא יצאתה מההעלם לגילוי, נמצא שזה שנאצלה החכמה מכת\"ר הוא אדרבה בחי' ירידה אליו ב\"ה (שהחכמה שהי' בכלל בהעלם בכתר נאצלה וירדה להיות בגילוי רק חכמה לבד וד\"ל), וגם אין זה דבר מחודש כלל, כי החכמה היתה גם קודם שנאצלה כו' בכת\"ר בהעלם כי יש בכלל מאתיים מנה, ורק כשנאצלה שירדה מכתר שהוא למעלה מן החכמה, להיות בחי' חכמה אז היא בגילוי כו'. וגם כולן כשנאצלו הם נאצלו הכל בסדר השתלשלות עילה ועלול, שהוא הכל בחי' ירידה כנ\"ל. וגם אין נק' בחי' התחדשות כלל שגם קודם לכן היו בהעלם בהמשפיע כנ\"ל שיש",[["162","*","<b>הנשמות</b>: וכה\"ג — ראה ג\"כ סהמ\"צ להצ\"צ מצות פו\"ר."],["163","*","<b>וכה\"ג מצאתי</b>: קטע זה נוסף בגוכתי\"ק לאחר זמן בהמדו\"ק. בכת\"י מעתיק מהדב\"ת ליתא."],["164","*","<b>ולבאר</b>: מכאן ליתא בגוכתי\"ק רק הגהות לאיזה שורות, וכן בכת\"י מעתיק חסרים כמה קטעים, ובמקום שחסר נרשם בגיליון."],["165","*","<b>במ\"א</b>: סה\"מ תקס\"ג ע' רצא ואילך."]]],[3000730201,"בכלל מאתיים מנה. וזהו לשון אצילות כדכתי' במרבע\"ה ויאצל מרוחו אשר עליו ויתן על ע' איש הזקנים כו' שהפריש מן הרוח שעל מרבע\"ה ויתן על הע' זקנים, שהזקנים היו למטה במדרגה הרבה ממרע\"ה (והיה הרוח שעל הזקנים תחלה במשה רבע\"ה בכלל רק שאח\"כ ירד ונשפל להיות על הזקנים וד\"ל) וזהו בחי' אצילות, שהנאצל הוא בחי' ירידה למטה כו' כמו בע' הזקנים כנ\"ל וד\"ל. וזהו הכל בעולמות העליונים הנאצלים, שהם הכל בבחי' השתלשלות עילה ועלול<sup data-n=\"166\">*</sup>. [ועמ\"ש* מזה בתו\"א בביאור ע\"פ ואלה המשפטים. ועד\"ז פירשו מארז\"ל עד שלא נברא העולם היה הוא ושמו בלבד שמו בגימ' מקור וגימ' רצון היינו בחי' כתר שנק' ע\"ס הגנוזות שהי' גנוז במאצילו אך לא ע\"ד התכללות השכל במקור השכל שיש לו ערך זל\"ז אלא ע\"ד התכללות שם האדם בעצמותו שהשם אין ערוך כלל לבעל השם וכלא חשיב כו', ושמו הגדול הוא מקור ושורש להתהוות האצילות שנאצלו מבחי' שמו כו' ע\"ד ויאצל מן הרוח כו' וזהו ע\"ד גלוי ההעלם כו', וע' בספר עה\"ק ח\"א פ\"ב, ובפרדס שער שלישי פ\"א.\n<b>ושער</b> חמישי ספ\"ד מענין היה הוא ושמו כו' ובשל\"ה בהקדמה דף ה'. וגם אפ\"ל ע\"ד שכ' המקובלים שענין ע\"ס הם מה שאוא\"ס ב\"ה מאיר בבחי' גבול כי משלימות הא\"ס ב\"ה שלא יחסר בו גם הכח להאיר בגבול ומדה שהוא כל יכול וזהו ענין אל שדי שאמר לעולמו די. וכח זה הכלול בעצמותו נקרא שמו ולכן הוא מקור לאצילות ע\"ס כו' ולא ששמו הוא מוגבל ח\"ו אלא שהוא מקור וכח להאיר גם בדרך גבול].\n<b>אבל</b> עולמות בי\"ע הם נק' מחודשים מאין ליש ממש, שזהו מחדש בטובו בכל יום מעשה בראשית, שמעשה בראשית דוקא נק' מחודשים מאין ליש, שמחדש בכל יום כו', והם עולמות בי\"ע שהם דוקא נק' מעשה בראשית שהוא המספר שמונין שית אלפי שני הוי עלמא, שהוא מספר מעולם החידוש שהוא מעולם הבריאה ואילך כו'.\n<b>(שזה</b> מונין ה' אלפים תקס\"ג לבריאת עולם החידוש) שמזמן ששת ימי בראשית הוא מספר השנים, ה' אלפים תקס\"ג כו', שהוא הכל מעולם הבריאה ואילך כו', שעולם האצילות שהוא בחי' השפעת המאציל הוא קדמון כו' ואין שם בחי' זמן כלל (כנז' במ\"א ואין שייך למנות כו') כ\"א הששת ימ\"ב כו' הם מעולם הבריאה ואילך כו'. וכן התורה שלנו היא בעולם הבריאה ולזה כתיב בראשית בבית ממש*, שזהו התחדשות גמור מאין ליש ממש, ופי' שזה לא יתכן כלל לומר שהיש הגשמי הוא היה תחלה קודם התהוותו בהעלם בהאין הכח השופע המהוה אותו מאין ליש. שאף שנז' במ\"א שמה שאנו קוראים להכח השופע בשם אין והנתהוה יש, הוא לפי סדר מלמטה למעלה שלגבינו נק' המתהוה בשם יש שמושג (ונראה כו'), והכח השופע נק' לגבינו אין שאינו מושג, וד\"ל. אבל לפי סדר מלמעלה למטה נק' הכח השופע בשם יש העיקר, והמתהוה ממנו בשם אין שהוא בטל נגדו והוא היה בו בהעלם ובבחי' ביטול קודם התהוותו כו'. אף שזה אמת, אבל אינו תכלית האמת לאמיתו שלא יתכן כלל לומר שהיש הגשמי הנתהוה מאין שהיה תחלה בהעלם ובחי' ביטול בהאין כו' (כי אין ערך כלל היש הגשמי להאין כמשי\"ת) כמו למשל התפוח הגשמי שיש בו כמה מיני טעמים מתיקות וחמיצות כו'. וכמה גוונין כו' (כנז' במ\"א) אי אפשר ולא יתכן כלל לומר שזה המתיקות הגשמי שבתפוח הגשמי הוא נמשך ונשתלשל בבחי' סדר השתלשלות עילה ועלול מן מתיקות הרוחני, שהוא כמו שיש מתיקות בהשכלת דבר חכמה. שכשמשכיל דבר חכמה הטיב, הוא מתענג הימנה שמתוקה ועריבה היא לו כו', שזה לא יתכן לומר כלל. שא\"א לימשך בסדר השתלשלות עילה ועלול מן מתיקות הרוחני שבהשכלת דבר חכמה כו' המתיקות הגשמי שבתפוח הגשמי, כי אין ערך כלל המתיקות הגשמי שבתפוח הגשמי להמתיקות הרוחני שבחכמה שאינה מהותה וערכה כלל, שזה גשמי",[["166","*","עי' לקמן במ\"מ לדף זה."]]],[3000730213,"וזה רוחני (ולא היה אפשר לימשך בסדר השתלשלות עילה ועלול כמשי\"ת). וכמ\"כ כל הברואים דצח\"מ גשמיי' א\"א ולא יתכן כלל שישתלשלו השתלשלות בסדר עילה ועלול מלמעלה. והטעם כנ\"ל (ואף שישנם במקורם למעלה וכנ\"ל שהיש המתהוה מאין ישנו תחלה קודם התהוות בהאין בבחי' העלם וביטול כו' וכנ\"ל שזה אמת כו' וד\"ל). ופי' כמו שיש סלע גשמי למטה כמ\"כ יש בלמעלה מעלה באצילות ג\"כ בחי' סלע, והוא שמלכות דאצילות נק' סלע, וכן יש בחי' עפר ג\"כ באצילות שמלכות דאצילות נק' ג\"כ עפר (וכן נק' מלכות דאצילות תפוח כנז' לעיל ע\"ש) וכן כל המיני פירות גשמיי' שישנם בבי\"ע כו' כמ\"כ ישנם באצילות בבחי' רוחני', והם כמו זתים תאנים וענבים ורמונים תפוחים ואתרוגים כו' (כנז' בכתבי האריז\"ל ע\"ש) ופי' שאיכות של כל המינים שבאצילות הוא בבחי' רוחניות, ואינם המהות והערך כלל לאותן שבבי\"ע הגשמיי' וד\"ל, ופי' שבחי' הסלע כדומה שבאצילות הוא כמו שהחיות של הסלע הגשמי שלמטה וקיומו, הוא מן כח השופע האלקי שעליו שמהוה אותו מאין ליש וכח השופע שמהווה כו', הוא הבחי' רצון העליון ב\"ה שהי' רצונו ית' שיהי' זה הסלע, וזה הרצון עליון ב\"ה הוא המהווה אותו מאין ליש ממש. וכמ\"כ הוא בחי' הסלע באצילות, שהוא המחשבה של הרצון עליון ב\"ה פי' שהרצון שהיה שיהי' הסלע הגשמי כו', והמחשבה שבאותו רצון עליון ב\"ה שחושב את הסלע שעלה ברצונו שיהי' במחשבתו כו', וזהו הבחי' סלע שבאצילות, פי' שהמחשבה של רצון עליון שיהי' הסלע הוא הנק' סלע דאצילות, והוא למשל באדם שחושב ומצייר במחשבתו מהות הסלע הגשמי כו'. כמ\"כ נק' למעלה זה הסלע שנצטייר במחשבה עילאה כו' בחי' סלע דאצילות וד\"ל. ועד\"ז הם כל המינים שבאצי' כמו רמונים ותפוחים ואתרוגים כו' כנ\"ל. אך אעפ\"כ אין ערך כלל המינים שבבי\"ע להמינים שבאצי' כנ\"ל שאין מהותם שוה כלל, שזה רוחני וזה גשמי, וא\"א כלל שישתלשל בסדר עילה ועלול מהסלע הרוחני כדומה שבאצילות הסלע הגשמי שבבי\"ע, וכן המתיקות שבתפוח הגשמי אינו ערך כלל להמתיקות שבאצילות שהוא כמו מתיקות השכל כנ\"ל שאינו המהות כלל, ולכן א\"א שיתהוה המתיקות הגשמי שבתפוח הגשמי שבבי\"ע מן המתיקות הרוחני שבתפוח הרוחני שבאצי' בבחי' סדר השתלשלות עילה ועלול שזה גשמי וזה רוחני כנ\"ל (ולא היה המהות היש הגשמי באצי' כו' ואיך יתהוה היש הגשמי מן האין מה שלא היה מהות היש בהאין וד\"ל). אך הענין הוא כנז' בע\"ח שיש מסך ופרגוד המפסיק בין אצילות לבי\"ע כו' ע\"ש. ושורש המסך הנ\"ל הוא מבחי' חשמ\"ל דבינה כו' ע\"ש. ופי' שבלא המסך הנ\"ל לא היה אפשר להתהוות עולמות בי\"ע שהם מתהוים מאין ליש ממש. וכנ\"ל שמהות היש ממש לא היה בהאין ואיך היה יכול להתהוות היש מהאין בסדר השתלשלות עילה ועלול כנ\"ל רק התהוות של עולמות בי\"ע מאצילות שמתהוים מאין ליש ממש (שלא היה מהות היש באין כנ\"ל) הוא ע\"י המסך והפרגוד המפסיק ביניהם לאצילות, ופי' שענין המסך הוא כמו שמשפיע הרב דבר חכמה לתלמידו ומלביש הרב את אותו השכל באיזה משל, שע\"י אותו משל מבין התלמיד את השכל ההוא הנמשל כו'. דהנה המשל אינו ממהות השכל כלל, כ\"א הוא מהות אחר ממש המסתיר ומלביש את השכל, ורק ע\"י המשל מאיר אור השכל שמבינים השכל הנמשל ע\"י המשל וד\"ל (אבל המשל הוא ד\"א ממש המסתיר השכל רק ע\"י מבינים השכל הנמשל שמאיר בו השכל הנמשל וד\"ל) כמ\"כ הוא המסך הגשמי שמסתיר האור כו' רק דרך בו מאיר האור כו', שהוא נק' אור הנכפל, פי' שהאור השמש כדומה מאיר בהמסך, והמסך מאיר כו', והוא כמו אור הלבנה שמאירה על הארץ שנק' אורה אור הנכפל, פי' הלבנה היא מקבלת האור"],[3000730223,"מהשמש כו', והיא מאירה על הארץ וד\"ל. וכמ\"כ הוא התלבשות השכל בהמשל שאור השכל מאיר מתוך המשל כנ\"ל שזהו ג\"כ נק' אור הנכפל שהוא ג\"כ בחי' מסך כנ\"ל וד\"ל. וכן התלבשות השכל בחידה כמו חידתו דשמשון מאוכל יצא מאכל כו' ג\"כ כנ\"ל וד\"ל. וזהו מה שמקבלים העולמות בי\"ע שפע ואור להחיותם שהאור והשפע שמקבלים הוא בחי' אור הנכפל שיוצא דרך המסך והפרגוד שמפסיק ביניהם לאצילות וד\"ל. ולכך הנבראים כו' הם בחי' יש ודבר ממש נגד אצילות שאינם מקבלי' מאצי' בסדר השתלשלות עילה ועלול שזה לא היה באפשרי שיתהוו בחי' יש מאין כלל, שאין מהות היש דבי\"ע בהאין שהוא אצילות כנ\"ל, כ\"א התהוותם שמתהוים מאין ליש ממש שהוא בחי' התחדשות ממש, (שלא היה מהות היש בהאין כנ\"ל) הוא ע\"י אור הנכפל שמקבלים דרך המסך והפרגוד המפסיק בין אצילות לבי\"ע כנ\"ל ועי\"ז המסך דוקא שמקבלים אור הנכפל כו' הם מתהוים מהות אחר ממש שהוא שמתהוים מהות יש ודבר נפרד ממש, שהוא בחי' התחדשות ממש שלא היה מהות היש בהאין שהוא אצילות קודם המסך כו' כי המסך דוקא עושה זה כנ\"ל וד\"ל וכדכתי' ומשם יפרד והיה לארבע ראשי' פי' שעולמות בי\"ע הם נק' עלמא דפרודא, שהם בחי' יש ונפרד ממש (שהוא בחי' התחדשות מאין ליש שלא היה מהות היש באין כלל כנ\"ל וד\"ל) כמו מלאך מיכאל דבריאה שהוא בחי' חסד דבריאה שהוא בחי' יש ונפרד לגבי אצילות שביטולו הוא בבחי' יש ונפרד בפ\"ע רק שבטל כו' שאומר שירה ומשתחוה כו', ואף שמתהוה מחסד דאצילות אעפ\"כ אין ערך כלל ביניהם, שזה יש ונפרד בפ\"ע והחסד דאצילות הוא בחי' אין ואחדות בתכלית היחוד דאיהו וגרמוהי חד שאין נופל כלל לשון השתחואה אף על הדבור שהוא מלכות דאצי' שאין שייך לומר שהדבור משתחוה להמחשבה כו' שהדבור ומחשבה אחד כו' (ואף שהדבור למטה ממחשבה ובטל לגבי המחשבה כו', אך אין שייך לשון השתחוואה שהוא בחי' יש בפ\"ע ומשתחוה כ\"א שם היחוד בתכלית וד\"ל כנ\"ל במ\"א ע\"ש), והוא מפני המסך שמפסיק בין אצילות לבי\"ע כנ\"ל שנעשי' עולמות בי\"ע מהות אחר בחי' יש ונפרד בפ\"ע ואינם ערך לאצי' שהוא אין והם מחודשים ממש שזהו ההתחדשות שהם נעשים יש ונפרד בפ\"ע ומה שלא היה מהות היש באצילות כנ\"ל וד\"ל. וכן על הנבראי' כו', דכתי' הן שמים לא זכו בעיניו כו' וכן כתי' ובמלאכיו ישים תהלה, שיש להם חטא כשאינם עובדים באהוי\"ר כדבעי כו' (שהם יש ונפרד כנ\"ל וד\"ל). וזהו ההתחדשות שמתחדשים עולמות בי\"ע מאין ליש ממש שהוא התחדשות גמור שלא היה מהות היש תחלה קודם המסך בהאין שהוא האצילות כנ\"ל וזה עושה הכל המסך כנ\"ל וד\"ל. ושרש המסך הנ\"ל הוא מחשמ\"ל דבינה (כנז' בע\"ח) ופי' שחשמ\"ל דבינה הוא כמו השכל עצמו הוא היולי (בלא אותיות כלל וד\"ל) וכשבא בגילוי במוח הוא בא באותיות המחשבה שהוא האותיות של פשט ההבנה, כמו שחושב איזה השכלה במחשבתו שחושב השכל הנ\"ל בצירופי אותיות המחשבה של השכל ההוא, זהו נק' לבוש החשמל דבינה, פי' שאותיות המחשבה שחושב השכל, מסתירים את השכל ההוא (שהשכל עצמו הוא היולי בלא אותיות) ואח\"כ כשמשפיע השכל ההוא באותיות ההם לזולתו, כמו שמדבר לזולתו השכל ההוא בצירופי אותיות ההם כו' אזי המקבל השכל ההוא הוא מקבל מן האותיות ההם שמאיר השכל מן האותיות (שמן האותיות מבין השכל וד\"ל) ה\"ז שמקבל השכל מן האותיות השכל, כמו קבלת האור דרך מסך הנ\"ל וד\"ל (רק שהאור השכל שמאיר דרך האותיות הוא נגלה יותר מן האור שמאיר דרך המסך שהוא האור השכל שמאיר דרך משל וחידה כנ\"ל וד\"ל) ולכך משתלשל למטה מעור החשמל דבינה המסך המבדיל בין אצי' לבי\"ע כנ\"ל וד\"ל) (או כמו שיש לו איזה תאוה וחמדה בלבבו."],[3000730232,"שכשהתאוה היא בלבו אז אין בה עדיין שום צירופי אותיות כלל, ואח\"כ כשמהרהר אותו במוחו אז מהרהרה בצירופי אותיות כו' והאותיות המלבישים אותה נק' לבוש החשמ\"ל כנ\"ל וד\"ל. והמסך הב' הוא בין בריאה ליצירה שמבדיל ומפסיק בין בריאה ליצירה כו', והמסך הג' הוא המבדיל ומפסיק בין יצירה לעשיה וד\"ל. וזהו מחדש בטובו בכל יום מעשה בראשית דייקא שכל המינים שבבי\"ע כמו תפוחים ורמונים ואתרוגים כו' כנ\"ל לא היה כלל מהותם באצילות שהם מתחדשים מאין ליש ממש פי' שמהות היש לא הי' כלל מהותו תחלה בהאין, שהוא אצילות כ\"א נתחדשו ממש להיות יש גמור מה שלא הי' בהאין תחלה כנ\"ל וזה עושה המסך והפרגוד כו' כנ\"ל, ולכך ניכר יותר גדולת א\"ס ב\"ה מדברים תחתונים שהם בי\"ע שמתחדשים מאין ליש ממש כנ\"ל, מן התהות עולמות הנאצלי' ששם הוא בחי' השתלשלות עילה ועלול, והיה מהות העלול תחלה בהעילה בהעלם כי יש בכלל מאתיים מנה כנ\"ל, ורק אח\"כ יורד ומתגלה כנ\"ל, והוא אדרבה ירידה אליו ב\"ה, וגם אין שם בחי' התחדשות כלל כי לא שייך למנות מזמן התהוות הנאצלים כי הם בחי' אלקות ואחדות עם המאציל ב\"ה שהם<sup data-n=\"167\">*</sup> ג\"כ בחי' קדמון כנ\"ל) שהם בחי' עצמות המאציל ב\"ה, כמשל השכל ומדות של עצמות הנפש שאף שהם מגלין עצמות הנפש לא נחשבו לדבר בפ\"ע כלל (כנ\"ל שלא שייך לומר ל' השתחוואה וביטול בהדבור והמחשבה שהם א' עם הנפש כנ\"ל וד\"ל) כמ\"כ כל האצי' הוא רק בחינת השפעת המאציל ב\"ה וד\"ל. משא\"כ בהתהוות עולמות בי\"ע שהם מתחדשים מאין ליש ממש שלא היה קודם הבריאה מהות היש בהאין שהוא אצי' כלל כ\"א אח\"כ מתחדש ממש הבריאה להיות יש ממש מה שלא היה קודם לכן כנ\"ל וד\"ל, ולזה מונין הזמן של התחדשות הבריאה כו' זמן ו' אלפי שני כו' וד\"ל. (וזה ההתחדשות עושה המסך כנ\"ל וד\"ל). ולכך כתי' בברכי נפשי רק דברים תחתונים דוקא שמספר גדולת א\"ס ב\"ה והוא ניכר יותר מדברים תחתונים כדכתיב שם זה הים גדול כו' הכל דברים תחתונים כו' שאף שהם תכלית ההסתר שהם יש גמור (ונעשי' ע\"י מסכים המסתירי' רבי' כנ\"ל), אך בזה הם קרובים יותר מצד שניכר עוצם גבורתו ית' בהם שמחדש הבריאה להיות יש מאין מה שלא היה תחלה מהות היש בהאין כנ\"ל וד\"ל ובזה ניכר גבורתו ית', שהן הן גבורותיו שיכול לשפול מלמעלה מעלה ולהתצמצם בגשם ממש, כמו מתיקות התפוח הגשמי שנתצמצם מאד כו' להיות מתיקו' גשמיי' וכן כל הטעמים שבכל המינים גשמיי' והדר הכל גבורותיו ית' שיכול להתצמצם כ\"כ (ע\"י מסכים רבים כנ\"ל)<sup data-n=\"168\">*</sup>, ועוד יש טעם מה שקרובים יותר העולמות בי\"ע שמתחדשים מאין ליש אליו ית', והוא מפני ששרשם הוא נעלה מאצי' כי התהוות העולמות בי\"ע הוא משבירת הכלים כו'. ושורש של שבירת הכלים שהוא עולם התוהו היה בעקודים ונקודים כו' (וממנו סבת היש מאין לכך קרובים יותר וד\"ל) והוא ס\"ג שלמעלה מש' מ\"ה שהוא אצילות שעתה שהוא עולם התיקון שהוא ברודים וד\"ל<sup data-n=\"169\">*</sup>. וזהו ענין מי ברא אלה מי היינו בינה שממנה נמשך המסך שבין אצילות לבריאה כו' כמ\"ש בע\"ח שער מ\"א, והיינו לפי שבינה היא כתר לז\"א שבחי' הז\"א לגבי הבינה הוא ע\"ד והחכמה מאין תמצא כו' לכך ממנה דוקא נמשך הכח הזה שיהי' התהוות יש מאין ולא דרך השתלשלות שהכח הזה נמשך מבחי' הכתר והמשקיף כו', ולכן מי דוקא ברא אלה שהוא ענין ההתהות יש מאין, וכמו המשל שנמשך ג\"כ דוקא ממי שהוא חכם גדול כענין משלי שלמה וכמ\"ש מזה בתו\"א פ' לך לך בד\"ה והבדילה הפרוכת לכם כו', ומ\"מ ההמשכה ע\"י זו\"נ ממכ\"ע היינו אלה תולדות השמים והארץ רק שסוכ\"ע נותן כח שיומשך מזה היש, ועמ\"ש מזה ג\"כ בביאור ע\"פ יביאו לבוש מלכות",[["167","*","<b>שהם ג\"כ</b>: בסה\"מ תקס\"ג: (שהם ג\"כ."],["168","*","<b>רבים כנ\"ל)</b>: בסה\"מ תקס\"ג נוסף: וד\"ל."],["169","*","<b>ברודים וד\"ל</b>: ע\"כ בסה\"מ תקס\"ג."]]],[3000730241,"תחת<sup data-n=\"170\">*</sup> הגליון (מכי\"ק): מי ברא אלה דנשמו' היינו מהתבוננו' נמשכי' המדות ביטול היש לאין מעלה אלה תולדות וכו' ותכלית דרצוא השוב ע\"י אלה המצות עד\"ז ענין מי ברא אלה דתומ\"צ שזה שישתלשלו המצות בגשמי' נמשך מבחי' מי כו'\n<b>וזהו </b>המוציא במספר צבאם מספר היינו זו\"נ שבהם ועל ידם נמשכו התולדות\n<b>והנה </b>פי' אלה היינו ג\"כ ששה מדות שהם כלולים מששה כחשבון אלה, והוא שאע\"ג שהכח להתהוות יש מאין נמשך מבחי' מי שהוא בינה שממנה נמשך החשמל המסך והפרסא, עכ\"ז ההשפעה נמשך מבחי' ו\"ק שהן המדות שהפרסא והמסך מלבשת אותן, וכנודע מענין ששת ימים עשה כו' והיינו כמו שאנו רואים ההתחלקות בפרטי מיני צומח יש פירות מתוקים ויש מרים ויש ממוצעים אשר שרש המתיקות נמשך מהחסד והמרירות מהגבורה כו' (כמ\"ש בזח\"ב שמות ט\"ו ב' בענין שהקדים מתוקים ומרים), והנה ו\"ק אלו בהשתלשלותן למטה מתחלקים לריבוי בחי' שונות אין קץ כי בחסד יש ג\"כ ו\"ק וכן בגבורה כו' וגם הם מתחלקי' לריבוי בחינות, וזהו המוציא במספר צבאם, והוא מה שאנו רואים בדצח\"מ שאין שום א' דומה לחבירו אין לך עשב שאין לו מזל כו' וכן בחי ומדבר, ויש לכל א' שורש ומקור בפ\"ע, והוא ע\"י התחלקות פרטי המדות לבחינות רבות אין קץ, וזהו ע\"י שהמשכת החיות מסוכ\"ע מבחי' מי נמשך ע\"י אלה שהם הו\"ק שעי\"ז המוציא במספר כו' וזהו כי אראך שמיך מעשה אצבעותיך כמו שפעולת האצבעות לפרר ולחלק הדבר לחלקים רבים. והנה המוציא ההא הוא ה' עילאה בחי' מ\"י הוא המוציא במספר שהוא ז\"א ונוק' צבאם, וכמ\"ש בזח\"ב משפטים ק\"ה א', מאי במספר כו' אילנא רבא ותקיף כו' ומספר שמיה, דהיינו ז\"א, ובמא\"א אות מם סעיף מם פי' מספר הוא הדעת, והיינו כי דעת כולל ה\"ח וה\"ג שהם נמשכים ומתחלקים לריבוי בחי' אין קץ וכמ\"ש בזח\"ג קל\"ו א' ע\"פ ובדעת חדרים ימלאון חדר היינו חסד דין רחמים שהם נמשכי' ע\"י הדעת כו'. ועמ\"ש עוד מענין מספר ע\"פ והיה מספר בני ישראל, ועיין מזה בהרמ\"ז פ' במדבר דקי\"ז סע\"ב שבחי' המספר הוא במקום גילוי האורות והיינו בחי' עלמא דאתגלייא כו', וזהו המוציא במספר, המוציא היינו המשכתם מעלמא דאתכסייא בעלמא דאתגליא הוא במספר כו', וע' עוד בפי' במספר בזח\"א בראשית ד\"ב סע\"א ובפ' תרומה דקס\"ח רע\"ב ודקע\"א ע\"ב, ועמ\"ש בד\"ה וידבר אלקים כו' אנכי כו' דפי' המוציא כענין המוציא מרה\"י לרה\"ר, וכך הוא כאן בענין המוציא במספר מה שנמשכים מאצי' לבי\"ע להיות נבראים יש מאין כי אצילות הוא בחי' עולם האחדות ונק' רשות היחיד איהו וגרמוהי חד, ובי\"ע שם רה\"ר טורי דפרודא כו'.\n<b>ועוי\"ל</b> בפי' המוציא במספר צבאם, דהנה השל\"ה בפ' במדבר הקשה בענין מ\"ש שאו וכו' במספר, הלא בדבר המדוד אין שורה ברכה וכו' וע\"ש מזה כי יש שני עניני מספר, עד ויהיה דבר שבמנין ולא יהיה בטל והמכוון כמו שאנו רואים שיש חשיבות בדבר שדרכו למנותו ולספרו שהוא דבר חשוב ואינו בטל בששים ואפילו באלף לא בטל כדאיתא במשנה פ\"ג דערלה ובגמ' פ\"ק דביצה ד\"ג סע\"ג. וכך הענין למעלה שאע\"פ שיש נבראים רבים לאין קץ ותכלית וקס\"ד שאין חשיבות כל א' אצל הקב\"ה כ\"כ עד שישגיח על כל פרטי הדצ\"ח בהשגחה פרטיות כ\"א על המין כולו כמו שזהו דעת הפילוסופים. ולהוציא מדעת זו כי אם שיש השגחה פרטיות אפילו בדצ\"ח וכדפירש\"י בחולין פא\"ט דס\"ג ע\"א ע\"פ ומשפטים תהום רבה, על זה אמר המוציא במספר צבאם, שהרי הם כמו את שדרכו למנות שהוא דבר החשוב מאד וכך כל נברא חשוב אצלו ית' להשגיח עליו בפרטיות, ועד\"ז נאמר מונה מספר לכוכבים, שהם כמו דבר שדרך למנותו ולסופרו.",[["170","*","<b>תחת</b>: בגוכתי\"ק בוך 234 נמצא רק ב' שורות והשאר נשרף."]]],[3000730250,"תחת<sup data-n=\"171\">*</sup> הגליון הי' כתוב בכי\"ק: לענין מי ברא אלה דאלה החוקי' ע\"ד שהקדימו נעשה לנשמע נק' מי גילה לבני רז זה א\"כ ביטול דנשמע לאלה החוקי' וביטול דנעשה לבעל הרצון מי ברא מי גילה כו', גם ע\"ד שנק' המצות שלוחי' ושלוחו ש\"א כמותו כו' וזהו מי ברא אלה הדברים האל\"ה אשר אנכי מצוך כו'.\n<b>מענין</b> שאו מרום עיניכם. פי' זח\"א ד\"א ע\"ב לבחי' המל' הנק' פתח עיניים והיינו כמ\"ש בפ' אחרי דע\"א סע\"ב מאן פתח עיניים כד\"א והוא יושב פתח האהל וכו', והיינו כמש\"ש דצ\"ה א' בענין פתחי לי. ויש לבאר זה ע\"ד בחי' מפתחות החיצוניות הנז' בד\"ה כי תשמע בקול, שהוא ענין מלכותך מל' כל עולמים ממכ\"ע, ותמן תנדעון בחי' מי ברא סוכ\"ע ע\"ד מבין דבר מתוך דבר, ועיניים ראיה איזהו חכם הרואה את הנולד מאין ליש ופתח עיניים ממכ\"ע, או כל החיות מאין ליש נק' רק פתח מפתחות החיצוניות, ולפ\"ז פי' אלה היינו בי\"ע. ובסה\"מ סי' ס\"ה פי' ע\"פ מאמר הנ\"ל ד\"א סע\"ב דאלה הוא שית דרגין לכורסייא ו\"ק דבריאה, ויש לפרש ע\"פ המדרש דאלה היינו אלה תולדות השמים והארץ כנ\"ל, ואלה ו\"ק הכלולים מו', ע\"ד הנה מקום אתי, ברוך המקום, גם אלה לשון רבים ע\"ש מה רבו מעשיך ע' זח\"ג מ\"ג א' ועמ\"ש בד\"ה וידבר אלקי' כו' וארא כו' שבחי' הרבוי וההתחלקות נמשך דוקא משם אלקים לכן אלקים לשון רבים אלקים קדושים הוא וזהו מי ברא אלה ש' אלקים כנז' בד\"ה חרבות צורים בסידור, רבוי הכלים וצרופי האותיות וי\"ל לכן פי' הסבא דנק' שמיה רבא י\"ל רבוי הכלים, גם אלה לשון כח, עי' יומא נ\"ד ב' מענין תולדות השמים והארץ, ברבות משפטים פ\"ל קרוב לתחלת הפ' מענין אלה תולדות מלא וזהו ג\"כ שאו כו' שלעתיד יהי' מלא ע\"י מי מי ירפא לך. ועוד מענין שאו בפ' פנחס רכ\"ג ב' שהוא ע\"ד שאו שערים ראשיכם כו' שאו את ראש, והעלאה זו היינו לגלגלתם סכ\"ע כך ע\"י פתח עיניים יראו שמי ברא, א\"נ שאו מרום לאפוקי מההסתכלות בגשמיות וכמ\"ש רז\"ל בזמן שישראל מסתכלין כלפי מעלה ועמ\"ש בד\"ה נחש נחושת, ועד\"ז שאו שערים והאופנים מתנשאים.\n<b>המוציא</b> במספר, פי' בזח\"א ד\"ב סע\"א דקאי על מל' וכן פי' בפ' תרומה קס\"ח רע\"ב ודקע\"א ע\"ב. ועמ\"ש מזה בד\"ה וידבר דעשה\"ד דפי' המוציא ל' המוציא מרה\"י לרה\"ר כי רה\"י הוא עולם האצי' ואח\"כ ומשם יפרד להיות טורא דפרודא כו'. ויש להעיר מברכת המוציא לחם ומענין מוציאם ממצרים. והנה הפרש בין ברא לענין המוציא ברא מאין ליש והוא בעולם הבריאה ואח\"כ יצרתיו מההעלם אל הגילוי זהו המוציא כו', וכענין מ\"ש ע\"פ כי תקנה ע\"ע ההפרש בין בורא שמים וארץ לקונה שמים וארץ, והקנין זהו כענין יציאה מרשות לרשות, וע' ד\"ה מי יתנך מענין קונה. והנה הבריאה מי ברא סוכ\"ע משם דוקא נמשך כח התחדשות יש מאין כנז' בד\"ה ואתחנן בענין ובטובו מחדש, בטוב של עצמותו משם נמשך להיות מחדש, אבל המוציא מההעלם אל הגלוי זהו ע\"י בחי' שהוא למטה מבחי' מי, שהוא בחי' מל' דרגא תתאה בחי' ממכ\"ע, בע\"מ נברא ומתחלה נבראו במאמר א' במחשבה א', א\"נ במספר היינו ז\"א כמ\"ש הסבא תרומה ק\"ה א'. ועמ\"ש ע\"פ המאמר פ' חיי שרה קכ\"ג א' בענין פי' ספירות ותכלית יציאה המוציא הנ\"ל צורך עלייה וזהו הקנין שיהי' העלאה מרה\"ר לרה\"י, והיינו בשבת עליות כו' לכן אז אומרים קונה שמים ע' דרוש ה' קנינים קנה, א\"נ במספר ע\"ד את מספר ימיך אמלא, דפי' בתו\"א ס\"פ משפטים ל' הארה, ובהסבא פי' מספר ז\"א והיינו כשנפרש אי\"ה אלה קאי נש\"י ועז\"נ ומספר את רובע ישראל.\n<b>לכולם</b> בשם יקרא, פ' תרומה קס\"ח ב' פי' ע\"ד מונה מספר לכוכבים לכולם שמות",[["171","*","<b>תחת</b>: נרשם בהיפוך בסוף העמוד."]]],[3000730259,"יקרא, ופי' בסידור היינו בחי' כלים להאורות נק' שמות יקרא, כי השם שייך בהתחברות הנשמה עם הגוף, ברבות וישלח פע\"ח משמע שיש למלאכים כמה שמות לפעמי' כך ולפעמי' כך ודרך כלל כשמשפיעי' למטה או כשמתעלים למעלה כענין<sup data-n=\"172\">*</sup> משריין ורתיכין אלף אלפי' ישמשוני' כו ', וזהו ענין שמות ל' רבים ע\"ש רבוי השפעות אכן כשמתעלים שם אחד כו' עושה שלום. ועיין בד\"ה כה תברכו את בנ\"י בפי' ויקרא האדם שמות שהוא ג\"כ המשכה, ועיין ברע\"מ פ' עקב דרע\"א סע\"ב מענין וקרא זא\"ז ובהרמ\"ז שם ובע\"ח שט\"ו ספ\"ו, ועמ\"ש בד\"ה ויקרא אל משה שהוא ענין הארה והמשכה למטה כדי שיוכל לעלות, וכענין מ\"ש אשר תקראו אתם ישראל אינהו דקדשינהו לזמנים כו' ע\"ש. ועד\"ז נאמר ראה קראתי בשם בצלאל, ראו קרא ה' בשם בצלאל, וע' מזה בזח\"א ד\"ב סע\"א, ח\"ב קנ\"ב סע\"א, ועי\"ז ואמלא אותו כו' השפעה ורבוי כמ\"ש לקמן בביאור ע\"פ ונתתי לך מהלכים כו', ולכן נק' המלאכים בשמות צירופי אותיות ושם אל בסופן כי הן הן האותיות שבהן נבראו ובהן התלבש מקור האותיות, וע\"ש דבחי' מל' פה הוא עד\"מ מקור האותיות הדבור כמו שהם קבועים בנפש, ואפשר זהו ענין בשם יקרא והתגלות האותיות זהו ענין לכולם שמות יקרא, ועיין בפ' ויחי דרכ\"ז ע\"ב ע\"פ קורא הדורות מראש לכולם בשם יקרא. ובמ\"א נתבאר פי' מראש היינו א\"ק מחשבה הקדומה אשר שם נכללו כל הדורות יחד ומשם קורא אותן שיומשכו בגלוי ועמ\"ש מענין שם בד\"ה מי מנה, וע' בפ' אמור דף ק\"ד ע\"א ע\"פ כל הנקרא בשמי ובפי' הרמ\"ז שם שהאריך, ויש להעיר ממ\"ש אסתר ב' י\"ד כ\"א חפץ בה המלך ונקראה בשם, וע' בת\"ז תיקון ך'. כי ה' קורא לנער ש\"א ג' י\"ח, וקראת לשבת ענג ישעי' נ\"ח י\"ג, מן המצר קראתי י\"ה תלים קי\"ח ה' כי גאלתיך קראתי בשמך לי אתה ישעי' מ\"ג א' קראתי ואין עונה ישעי' נ' ב'. וקראתי אל הדגן והרביתי אותו יחזקאל ל\"ו כ\"ט, הרי הקריאה היא השפעה בריבוי, בכל קראינו אליו דברים ד' ז'. יעננו ביום קראנו תלים כ' י'. א\"כ כמ\"כ בענין הקריאה אשר לכולם בשם יקרא צ\"ל ג\"כ ענייה שהרי הכתוב קובל קראתי ואין עונה, וענין ענייה זו יש להעיר ממ\"ש סד\"ה משה ידבר והאלקים יעננו בחי' ביטול היש נק' עונה, ועמ\"ש בד\"ה בהעלותך בענין ושמן ימינו יקרא, ועמ\"ש בד\"ה ולא אבה בענין קול קורא במדבר פנו דרך כו', לא יקרא שמך יעקב כ\"א ישראל כו' וכן באברם אברהם כו', כי שם ה' נקרא עליך דברים כ\"ח אלו תפילין כו', יען קראתי ולא עניתם ישעי' ס\"ה י\"ב, וצ\"ל תען לשוני אמרתך, וכמ\"ש ויענו כל העם כו' נעשה שמות י\"ט ח'.\n<b>מרוב</b> אונים פי' בזח\"א ד\"ב סע\"א ריש דרגין דסליקו ביה כל רעותין ואיסתלקו ביה. בסה\"מ סי' ע\"א פי' ריש דרגין הוא חכמה ראש המדרגות כי כתר נעלם מאד ואף חכמה קדומה נעלמה מעיני כל חי שאף יסוד שהוא כ\"ל ח\"י המושך טפה הזרעית מהמוח הנקרא חכמה, אינו מושך מהחכמה זו הקדומה, כי נעלמה ממנו, אלא חכמה זו הנקרא שירותא ריש המדרגות והוא נק' אבא, ונק' חכמה זו רוב אונים, שכל הרצונות הנק' רעותין כולם עולים עד שם כו'. והנה טיפה הזרעית כו' און, כד\"א ראשית אוני כו' ולפיכך נק' רוב אונים כו' ואמיץ כח היא הבינה כו' הכוונה שלהוליד ס' רבוא כו' הוא ע\"י יחוד או\"א הנק' רוב אונים ואמיץ כח, ועי\"ז לא נעדר איש מהס\"ר דוגמת עולם העליון עכת\"ד. וע' בהרמ\"ז פ' יתרו דס\"ח בענין חמוי דיוסף כהן און. ואפשר שנגד ב' בחי' אלו דרוב אונים ואמיץ כח אמר יעקב על ראובן בכורי אתה כחי וראשית אוני. וברבות שם ויחי פצ\"ט אתה היית טפה ראשונה שלי, ועד\"ז החכמה נק' בכר ראשית הגלוי. ובפ' תצא כתיב כי את הבכור בן השנואה כו' כי הוא ראשית אונו. ומבואר במ\"א בן השנואה היינו",[["172","*","<b>לפעמי'</b>: כענין משריין — ראה ביאוה\"ז ר\"פ בשלח."]]],[3000730267,"בירור נה\"ב ונק' ראשית אונו ע\"ד לפני מלוך כו'. וא\"כ יש ב' בחי' ראשית אונו הא' מצד נה\"א חכמה דתיקון, הב' מצד בירור נה\"ב. ואפשר שזהו פי' מרוב אונים, היינו התחברות תוהו ותיקון. ובהושע י\"ב ג' כתיב ובאונו שרה את אלקים כו', ובפ' פקודי דרל\"א סע\"ב פי' מרוב אונים דא סטרא דימינא ואמיץ כח דא סטרא דשמאלא, איש לא נעדר סטרין דנגדין מתרין עברין, ופי' במק\"מ ב' הרח\"ו דהיינו תפארת. ויש להעיר לענין ואמיץ כח ממ\"ש בענין יגדל נא כח, וע' מענין מרוב אונים במא\"א אות ריש סמ\"ה פי' אבא והי\"נ שם הביא מהת\"ז תיקון מ\"ט דפ\"ח ע\"ב מרוב אונים דא כתר עילאה כו' וע\"ש כל הפסוק וע' בלק\"ת ר\"פ יתרו.\n<b>והנה</b> ביאור הדברים בענין מי ברא אלה נתבאר בביאור ע\"פ אלה מסעי דתקס\"ג מי הוא בחי' אין הבורא את היש שנק' אלה, כי מי היינו מה שאינו מושג, אלה היינו מה שמושג היש הנברא. והתהוות יש מאין היינו ע\"י הפרסא המסתיר לגמרי ולא דרך השתלשלות. ועי\"ז דוקא נעשה הנברא יש ומחודש, והפרסא שרשה מבחי' בינה וזהו מי בינה ברא אלה. ועמ\"ש בד\"ה והבדילה הפרוכת ששרש הפרסא המפסיק בין אצי' לבריאה שרשה למעלה מזו\"נ דאצי' וכענין משלי שלמה ולכן מי דוקא שלמעלה מזו\"נ ברא אלה, כי זו\"נ היינו ממכ\"ע ובינה סוכ\"ע. וזהו ענין מבטן מי יצא הקרח כנז' בד\"ה הנותן שלג. ועוד נתבאר מזה באריכות בדרוש חוה\"מ פסח תקס\"ג להבין ענין המסך כו' ואיך שבהתהוות בי\"ע יש מאין יש בזה גדולת הבורא ית' יותר מבאצילות ע\"ס דאצילות שהם דרך השתלשלות כו' וזהו שאו כו' מי ברא אלה דוקא. ועד\"ז י\"ל פי' מארז\"ל ע\"פ גדול ה' כו' אימתי גדול ה' כשהוא בעיר אלקינו, כי שם הוי' מורה על עולם אצי' יו\"ד חכמה ה' בינה כו' ושם עדיין דרך השתלשלות אבל כשנמשך בעיר אלקינו בחי' מל' להוות ולחדש יש מאין בבי\"ע ע\"י הפרסא שבין אצי' לבי\"ע, שם נגלה כח הא\"ס ממש לחדש יש מאין ולא דרך ההשתלשלות, ואז נראה ונגלה גדולתו ית' בבחי' א\"ס ממש וזהו אימתי גדול כו', כי ממל' דוקא נמשך יש מאין לפי שהוא בבחי' רוממות והתנשאות, ובזח\"ג ד\"ז ע\"ב פי' שע\"י יחוד שם הוי' ואלקי' נעשה השלימות והיינו גלוי כח בחי' מי בינה סוכ\"ע להיות ברא אלה יש מאין, גם בחי' מי ברא אלה להוציא ממאמר המין מפלגך ולעילא כו' כנז' בד\"ה ששים המה מלכות וסוף הביאור דוהיה מספר בנ\"י,\n(תחת<sup data-n=\"173\">*</sup> הגליון הי' כתוב בכי\"ק: אלה מסעי בנ\"י היינו מ\"ב מסעו' העלאה בחי' אלה לבחי' מי הפך סה\"ע שהוא ענין מי ברא אלה המוציא בספר סה\"ע, ואפשר שזהו לכולם בשם יקרא)\nוהנה כל הנ\"ל זהו ענין התהוות בי\"ע הנקרא אלה תולדות השמים והארץ יש מאין מבחי' מי כנ\"ל וע\"ז אומר המדרש פ' ויקהל, בזכות מי נבראו אלה תולדות השמים והארץ ובזכות מי הם עומדים, בזכות ואלה שמות בנ\"י כו' והיינו שכללות נש\"י נק' ג\"כ אלה. וכמבואר בסבא דמשפטים דק\"ה ע\"א, מפסוק כל אלה שבטי ישראל שנים עשר. והיינו בחי' אלה תולדות השמים והארץ הם שנבראו בבחי' יש ודבר נפרד ו\"ק גשמיים עד שבהשתלשלות נמשך מזה בחי' כפירה באחדותו ב\"ה כמו בחטא העגל אמרו אלה אלהיך כו' ויעקב אמר ליוסף מי אלה לפי שעתיד ירבעם כו' כו' וע' מזה בזהר ויחי רכ\"ז ב' ובמק\"מ שם. אכן בחי' נש\"י ששרשן מו\"ק דז\"א דאצילות שכל א' כלול מששה כמנין אלה, שהם ו\"ק רוחניים דרום בחי' אהבה כמ\"ש באברהם הלוך ונסוע הנגבה צפון יראה מזרח בחי' קדם ומערב בחי' אחור והכל בבחי' העבודה האלקית וכן מעלה ומטה וע' בד\"ה וארא אל אברהם גבי אחד כו' בת\"א פ' וארא. וזהו דאלה תולדות השמים והארץ עומדי' בזכות",[["173","*","<b>תחת הגליון</b>: בגוכתי\"ק 234 יש רושם ניכר שהי' כתוב, אבל לפנינו נשרפו כל השולי העמודים וכן בצידי העמודים נשרפו. בעמוד ב' בגוכתי\"ק יש מקום חלק יותר מחצי עמוד קודם והנה כל הנ\"ל."]]],[3000730275,"אלה שמות בנ\"י והיינו כמארז\"ל כשם שא\"א לעולם בלי רוחות כך א\"א לעולם בלא ישראל. וכמבואר ענין זה בת\"א פ' בשלח בד\"ה אכלוהו היום, כי רוחות אין פי' רוחות הנושבות כ\"א הו\"ק מזרח מערב כו' הם ו\"ק שהם עיקר העולם שזהו גבול המקום ואם לא היו הרוחות לא היה בחי' מקום כלל אלא כמ\"ש הנה מקום אתי שהוא בחי' ביטול כו' ורוחות אלו דהיינו ו\"ק נתהוו יש מאין ע\"י מי ברא אלה בחי' הפרסא כנ\"ל המסתיר להיות מקום גשמי ו\"ק. אמנם שרש ו\"ק הגשמיים נמשך תחלה מבחי' ו\"ק הרוחניים שהם מדות העליונות, והוא ענין אלה דנש\"י שהם בחי' ו' מדות שבנה\"א וזהו ענין ששה משמותם על האבן האחת כו' ע\"ש. וזהו ויזכור ימי עולם וארז\"ל דהיינו נש\"י שהם ו\"ק דאצילות הנק' אלה, ובהתלבשותן ביצי' נמשך מזה ו\"ק דמט\"ט הנק' אלה תולדות השמים כו'. אך הנה גם בבחי' אלה דנש\"י יש בחי' מי ברא אלה, שעכ\"ז נק' ג\"כ בריאה יש מאין. והוא כי הגם ששרשם מאצילות אך באצי' יש ג\"כ אבי\"ע אשר בחי' בריאה היינו יש מאין. ויש שם ג\"כ בחי' פרסא המפסיק שעי\"ז נמשך יש מאין, ודרך כלל הוא ענין תפארת דאימא שנעשה כתר לז\"א ובחי' פרסא, עד שאין ערוך בחי' הז\"א לבחי' בינה, כענין והחכמה מאין תמצא, וכמ\"ש בד\"ה הנותן שלג בענין ועל ראשי החיות רקיע כעין הקרח וכתי' מבטן מי יצא הקרח. ואע\"ג שלמעלה אמר דאצילות היינו גלוי ההעלם וא\"כ איך שייך באצי' בי\"ע, אפ\"ל דהיינו כלים דאצי' שהם בי\"ע דאצילות, אשר לגבי האורות שייך לקרותם בי\"ע, אף שהם כלים דאצי' ונאצלו מן הרשימו, וזה כעין שיטת הר\"מ מראקנטי שהביא הפרדס שער עצמות וכלים, או גם כעין שטת הפרדס עצמו שם, גם שבנשמה יש ב' בחי' הא' אתה בראת הב' בחי' מזלייהו ואתה משמרה כנז' בד\"ה יונתי, והוא ענין מי ואלה. וענין מי ברא אלה היינו ג\"כ התחברות ב' הבחי' יחד והוא ע\"י לידת המדות מההתבוננות ונק' יציאת מצרים והיינו אלה מסעי בנ\"י אשר יצאו מאמ\"צ שהוא גלוי בחי' אלה כו', ועמ\"ש בד\"ה והיה מספר שזהו ענין פלג אלקים מלא מים שנפלג ונתחלק ההעלם דשם אלקים להיות בחי' מי ברא אלה, והוא ענין המשכת המוחין בהמדות בחי' נה\"י דאימא נמשכין להיות מוחין לז\"א. וכן פי' בעמה\"מ ענין מי ברא אלה הוא המשכה מעלמא דאתכסיא בעלמא דאתגלייא וז\"ל שער עולם התוהו פס\"ב דל\"ח ע\"א כי זה היה חיבור אימא הנקרא מי כולל חמשים שער חירות המלבשת בסוד חופה לזו\"נ אשר כללו הוא ו\"ק וכלול מו\"ק והם ופ\"ו עולה אלה וזהו סוד שאו מרום עיניכם וראו מי ברא אלה ובעוונות הרבים מיום החורבן נסתלקת אימא מעל בנין היינו מי מן אלה כו', וזהו סוד הקדיש יתגדל ויתקדש שמיה רבה כו' עכ\"ל, וע\"ש ש\"ח פ\"ט דמ\"ז ע\"ג ובשער קרית ארבע פמ\"ב האריך בזה, ושער רישא דז\"א פ\"ב ופרק ל\"ד דקמ\"ב ע\"ד. ועמ\"ש בד\"ה באתי לגני וע\"פ הללוי' הללי נפשי. וזהו ג\"כ ענין הנחת תש\"ר לחבר בחי' מי בינה עם ז\"א אלה כמ\"ש ע\"פ את שבתותי תשמרו שלא נדפס בלק\"ת.\n(תחת הגליון הי' בכי\"ק<sup data-n=\"174\">*</sup>: א\"ת בניך אלא בוניך זהו אלה דנש\"י בזכות אלה העדות ו\"ק מדות שלמעלה מהחו\"ב ושמן ימינו יקרא, שיורד ע\"פ מדותיו, ו דוהנורא אל עליון).\n(ע\"ג הגליון<sup data-n=\"175\">*</sup> בכי\"ק: ברבות באיכה כ\"א, ד' אילו זכיתם הייתם קורים אלה מועדי, ועכשיו על אלה וכו' היינו שאין יכולים לקיים בחי' אלה מועדי, גבי מעשה דאשה ושבעה בניה נז' ג\"כ על אלה וכו' כי הוא בחי' מי ברא אלה, דס\"ח ע\"ב על אלה, אלה שני בני היצהר שהם ושנים זתים עליה, שהם ב' מזלות ונוצר ונקה המשפיעי' לאצי' ע' סד\"ה מנורת זהב. וח\"א ביטול קרבנות אלה תעשו במועדיכם אשר ע\"י קרבנו' ריח ניחוחי כו' זח\"א רכ\"ח א' פקודי רל\"ו ב').",[["174","*","<b>בכי\"ק</b>: בבוך 234 נשרף הגליון."],["175","*","<b>ע\"ג הגליון</b>: נכתב בראש הגליון."]]],[3000730282,"<b>וענין</b> מי ברא אלה בנש\"י י\"ל ברא אותיות אבר כמ\"ש בזח\"א ג' סע\"ב והיינו שבחי' יסוד המשפיע לבחי' מל' הנק' אלה מקבל מהבינה וכמ\"ש בענין בצלאל בפ' תרומה קנ\"ב סע\"א. וזהו מי מנה עפר יעקב כמבואר בסבא דמשפטים ק\"ה א'. וזהו מי מושל בי צדיק כי הצדיק מרכבה ליסוד המקבל מבינה הנק' מי וע\"כ בחי' מי מושל בי כביכול. גם ענין המשכה זו כי בינה נק' שכינתא עילאה למס\"נ באחד ונמשך בבחי' אלה שכ\"ת וכמ\"ש במ\"א בד\"ה והקרבתם עולה אשה פי' ויחד לבבינו יחוד חיצוניות הלב הנק' אלה בפנימיות הלב נק' מי. המוציא במספר צבאם כמ\"ש ומספר את רובע ישראל וכתיב והיה מספר בנ\"י, לכולם בשם יקרא כמ\"ש במ\"ר ר\"פ ואלה שמות ראובן ע\"ש ראה ראיתי כו', איש לא נעדר כי לא ידח ממנו נדח. וי\"ל ג\"כ בענין המוציא וכו' ע\"ד בעצם כו' יצאו כל צבאות ה' מאמ\"צ, והמוציא כענין המוציא אתכם מתחת סבלות מצרים, במספר, שנעשו ד' דגלים, היינו ס\"ר בחי' הכללות היותר גדול ו\"ק ה\"פ יוד מיו\"ד, גם ע\"ד את מספר ימיך אמלא הבהירות של היומין כו'. וא\"כ מספר ל' בהירות. והנה דרך כלל ענין מי ברא אלה דבחינת אלה תולדות השמים והארץ נמשך מיחוד חו\"ב להחיות העולמות שזהו מי בינה ברא אלה ו\"ק דז\"א וזהו יחוד חיצוניות ובזכות מי נבראו בזכות ואלה שמות בנ\"י שהם ממשיכים יחוד פנימי דחו\"ב שזהו הנמשך ע\"י למס\"נ באחד. ומ\"מ זהו עדיין הגלוי מחיצוני' עתיק, ובזכות מי אלו עומדים בכות אלה העדות היינו גלוי פנימי' עתיק כו'.\n<b>והנה</b> בחי' אלה הנ\"ל דנש\"י נבראו בזכות אלה העדות כו' בחי' התורה שנאמר בה ג\"כ אלה, אלה מועדי ה', ובקרבנות אלה תעשו לה' במועדיכם והיינו כי נש\"י שרשן מאצילות בחי' מי בינה ברא יסוד אלה מל' כנ\"ל. לכן העולמות בי\"ע הנק' אלה תולדות השמים והארץ עומדין בזכותן, שבהן ועל ידן נמשך מאצילות לבי\"ע. אך ישראל מתקשראן באורייתא ה\"ע התקשרות האצי' בהמאציל א\"ס ב\"ה ע\"י הכתר המחבר המאציל עם הנאצלי' ושם תרי\"ג מצות דאורייתא עם ז' דרבנן הם תר\"ך כתר. ועמש\"ל בענין יש אחד ואין שני לו, באות ב'. אך בחי' מי ברא אלה, היינו כידוע שבכתר יש ב' בחי' עתיק וא\"א. והנה ע\"ד התלבשות הבינה דאצי' בז\"א שנק' חיבור עם מי אלה, כך הוא ענין חיבור והתלבשות עתיק בא\"א, והם נק' ג\"כ מי אלה, והיינו כמ\"ש במ\"א בהגהות דביאור והיה מספר בנ\"י דמבואר בע\"ח שער א\"א פ\"א וספ\"ב בהג\"ה ובשער או\"א פ\"א שיסוד דעתיק המתלבש בא\"א מסתיים ג\"כ בחזה דא\"א ע\"ד יסוד אימא בחזה דז\"א. והנה ענין מי ברא אלה שבבינה וז\"א היינו התחברות עלמא דאתכסייא שהם חו\"ב י\"ה בזו\"ן ו\"ה והיינו ע\"י ההמשכה מיסוד אימא גלוי החסדים למטה מהחזה כו'. וכמ\"כ ממש הוא ענין שרש המשכה זו גם מהמאציל לנאצלים בבחי' כתר יש ב' בחי' הנ\"ל, מה שהוא שרש הנאצלים נק' אלה. שלגבי א\"ס ב\"ה נחשב זה בחי' גלוי, והבחי' תחתונה שבמאציל נק' מי רדל\"א, ומה שבחי' עתיק מתלבש בא\"א נק' מי ברא אלה. והנה עד\"ז בתורה יש סתים וגליא כנגד ב' בחי' מי אלה הנ\"ל כי התורה היא הממוצע כו' שיש בו ב' בחי', ופנימי' התורה היא עין לא ראתה כו' ע\"כ נק' מי. אך כל מצות התורה נק' אלה, וזהו אלה מועדי ה', והוא מה שנמשך להיות שרש הנאצלים, וזהו ענין הנז' במדרש ע\"פ על אלה אני בוכיה, דהיינו מ\"ש אלה שני בני היצהר וכו' שהם בחי' ושתים זתים עליה שהם ב' מזלות ונוצר ונקה הנמשכי' מא\"א להיות מקור לחו\"ב, כי אורייתא מחכמת נפקת. וזהו ג\"כ קנה חכמה קנה בינה ב\"פ קנה"],[3000730289,"גימט' יש שהוא מחצה מתר\"ך ומבחי' זו נמשכי' ש\"י עולמות לכל צדיק, הנה בין המאציל לאצילות יש ג\"כ פרסא בחי' קרומא דאוירא וכו' יהי רקיע וכו' וזהו ג\"כ ענין מי ברא אלה, ופרסא זו בחזה דא\"א וכו'. גם י\"ל מי מה שהוא למעלה מהצמצום ומק\"פ ברא אלה בחי' הקו וחוט וכו', כי הקו וחוט הוא בחי' וא\"ו שהוא המשכה מלמעלה למטה. והנה ו' פעמים ו' זהו אלה, ואפ\"ל כאן ברא ל' גילוי ולא בריאה מאין ליש כמ\"ש במא\"א ב' ל\"ז בריאה לשון נקיבה וקריעה (ע' גבי שמא הבריא פא\"ט מ\"ג ב') כי בקעה וקרעה מ' דאצילות המסך שבין עולם לעולם וירדה שם, וכן פי' רבינו ז\"ל בענין אשר ברא ששון ושמחה כו', ועד\"ז בקיעת החשך והצמצום שיהי' נמשך הקו הנק' יבקע צורים נק' ג\"כ ברא אלה כו' כי<sup data-n=\"176\">*</sup> הקו וחוט הוא בחי' וא\"ו שהוא המשכה מלמעלה למטה.\n<b>והנה</b> ו' פעמים ו' זהו אלה, ואפ\"ל כאן ברא ל' גילוי ולא [ ] בריאה מאין ליש כמ\"ש במא\"א [ ] וענין אלה ופ\"ו, בחי' מדות דא\"א טורי חשוכא, וכענין ו' והנורא אל עליון כו'. גם י\"ל מי תשב\"כ כי מי שער החמישים מנש\"ב שבו ניתנה תורה בשבועות ברא אלה היינו תשבע\"פ בחי' גלוי הרצון שבתשב\"כ גם ששה סדרי משנה וכל א' כלול מכולם גימטריא אלה. המוציא במספר תרי\"ג מצות בחי' מספר, ואתא מרבבות וכו' לכולם בשם יקרא כל התורה שמותיו של הקב\"ה. וע' ד\"ה ואהי' אצלו אמון שנענש דוד על אומרו זמירות כי כל מצוה ענין בפ\"ע וא\"כ לכ\"א שם בפ\"ע, והם המשכות שמו הגדול, גם מ\"ע ו\"ה ל\"ת י\"ה. ולע\"ל כתיב והי' מספר כו' אשר לא יספר כו' והיינו ע\"י תשובה הנק' מי. וע\"ז נאמר והי' הוי' לי לאלקים שבחי' אלקי' מי אלה יהי' מבחי' הוי' שבשם הוי' ג\"כ י\"ה עלמין סתימין ו\"ה עלמא דאתגלייא, וגם לעתיד ש' הוי' בחי' יהיה ו\"ה כמו י\"ה א\"כ גם בחי' אלה יהי' כמו מי, מי אלה כעב תעופינה, מי גילה רז זה. והמכוון מכ\"ז י\"ל שע\"י שאו וכו' מי ברא אלה שזהו ע\"ד וידעת וכו' כי הוי' הוא האלקים יומשך לע\"ל גלוי מי ברא אלה בבחי' ראייה ממש עין בעין יראו ונגלה כבוד ה' כמ\"ש בד\"ה שובה ישראל דרוש הראשון פ\"א. ולכן אלה תולדות השמים וכו' נבראו רק בשביל ואלה שמות בנ\"י שהם ימשיכו דירה בתחתונים שיהי' גלוי מי ברא אלה, והיינו ע\"י אלה המצות כו'.\n<b>ועמ\"ש</b> בהגהות לד\"ה אלה מסעי דתקס\"ג שלא נדפס בלק\"ת, שם העירותי לענין אלה מסעי, מפסוק גפן ממצרים תסיע. ומ\"ש ע\"ז במד\"ר כי תשא ר\"פ מ\"ד עקרן ממצרים ושתלן במדבר. והנה גפן יין המשמח אלקים, וע\"י שמחה זו נמשך הגלוי משם אלקים בחי' מי ברא אלה, מי אלה זהו ש' אלקים בזהר בתחלתו וזהו ענין יציאת מצרים כי מצרים מצר ים שאין מתגלה בחי' מי ברא אלה ואזי שם אלקים מעלים, וע\"י הגפן שמשמח אלקים התגלות מי ברא אלה, זהו היציאה ממיצר ים. וזהו ענין אלה דנש\"י הנק' ואלה שמות בנ\"י הבאים מצרימה וכשיצאו ממצרים זהו שמקיימים אלה תולדות השמים והארץ ע\"ד שמקיימין את העולם שנברא בעשרה מאמרות כו'. ואח\"כ ע\"י ששתל גפן זה במדבר נתגלה יינה של תורה חמר חווריין עתיק. וזכרו כיין לבנון ואזי משמח גם ש' אלקים דאצילות בחי' מי אלה דנש\"י, ע\"י שקבלו התורה, ונתגלה מי אלה, מי המקיף של הנשמה באלה גלוי הנשמה כו' וזהו ענין מ\"ב מסעות דמדבר ש' מ\"ב. ושמחה זו הוא ענין שמחה של מצוה כו' בבחי' מרוב כל.",[["176","*","<b>כי. . במא\"א [ ]</b>: קטע זה ניתוסף בגוכתי\"ק בבוך 234 ושם נכתב בצד העמוד ונסמן ששייך לכאן. וצידי העמוד נשרף."]]],[3000730059,"<b>(קיצור</b><sup data-n=\"177\">*</sup> ב'). ממה שלא נפסק השפע, כ\"א כמבוע מים דלא פסיק, זהו רואים בחי' א\"ס, והיינו כי במל' דעשייה מלובש מל' דאצי' שבתוכה אור א\"ס. וענין מופת זה קרוב לכאורה למ\"ש הרמב\"ם בספרו מ\"נ ח\"ב פרק ראשון עיון שלישי והביאו ג\"כ בעל העקרים במאמר ב' פרק חמישי, וז\"ל אמר הנמצאות לא ימנע הענין בם משלשה חלקים כו' ושקר שיהיו כולן הוות ונפסדות כו' היו כל הנמצאות אפשרי ההפסד והיה ראוי שיפסדו כולם כו' עד יתחייב בהכרח שימצא נמצא בלתי הווה ולא נפסד שאין אפשרות הפסד בו כלל הוא המכריח מציאות הדברים ההוים ונפסדים על העדרם כו' עכ\"ד. דהמכוון כמש\"כ כיון שאנו רואים למטה בארץ נמצאים רבים הווים ונפסדים הם כל אישי חי מדבר וכן הצומחים. א\"כ זה שאנו רואים שהשמים והכוכבים קיימים באיש ואין נפסדים, ואין נעדרים, אי אפשר לומר שהם מצד עצמם הם יש בהם הכח הזה של בלתי הוה ולא נפסד, שהרי הם בעלי גבול, שיש גבול למדת שמים, וכ\"ש לכל כוכב. וכיון שהם בעלי גבול ומדה, אי אפשר שיהי' בהם הכח הזה, דכל שהוא בעל גבול יש לכחו ג\"כ גבול. וכיון שהוא בעל גבול ע\"כ שולט בו ההפסד וההפסק לכחו, דמאי שנא מאישי החי ומדבר, שכיון שהם בעלי גבול נפסדים, והפסדם הוא במהרה כמ\"ש כצל ימינו עלי ארץ, א\"כ גם אישי השמים כיון שהם בעלי גבול ראוי שיהי' כן אף שהגבול שלהם גדול יותר, מ\"מ שניהם שוים לגבי בלתי בעל גבול, ואינן בערך הכח הבלתי הוה ולא נפסד שהוא הבלתי בעל גבול. וזהו שאמרו ברבות פ' בראשית פרשה ב' ע\"פ והארץ היתה תהו, אמרה עליונים והתחתונים נבראו בבת אחת העליונים חיים והתחתונים מתים, לפיכך והארץ היתה תוהו, ר\"ל תמיה, על זה, והיינו כיון שהעליונים הם ג\"כ בעלי גבול כמו התחתונים מדוע הם קיימים באיש ואין בהם הפסק והעדר, והתחתונים הם בעלי העדר והפסד. ועוד הכריח הרמב\"ם שא\"א שיהי' זה הקיום מצד עצם הכח שיש בשמים, מלבד שהם בעלי גבול, עוד זאת כיון שהם גוף וא\"כ הם מורכבים מחומר וצורה, וכיון שהם מורכבים בהכרח שהם אפשרי ההפסד, אע\"כ יש כאן נמצא בלתי הוה ולא נפסד, ואינו גוף, וברצונו הפשוט יעשה מה שירצה, והוא הנותן הכח תמיד באישי השמים שלא יפסדו ולא יהיה הפסק להשפעתן, וג\"כ נותן כח באישי הארץ שלא יפסד המין, וזהו עצמו ענין הפסוק שאו מרום עיניכם כו' מרוב אונים ואמיץ כח איש לא נעדר, ר\"ל ממה שאנו רואים באישי השמים, אשר איש מהם לא נעדר, ואין הפסק לההשפעה, אשר זה אי אפשר מצד הכח המלובש בהן שהוא בעל גבול והיה ראוי שיפלו תחת ההפסד, וא\"ת שעדיין לא נפסדו ועתידין להפסד, מ\"מ הי' ראוי שיהי' בהם חלישות ותשות כח לפרקים כמו באדם ובעלי חיים, שלפי שהם נפסדים, אזי גם בחייהם יש להם תשות כח לפעמים, והרי אנו רואים באישי השמים שאין בהם חלישות ולא העדר, וכמ\"ש בתשו' הרשב\"א ח\"א סי' ט' וז\"ל ואנו רואים הגלגלים בלתי משתנים כלל מיום הבראם וכן הארץ בכללה הולכת על מנהג אחד תמיד עכ\"ל, וכמ\"ש בירושלמי פ\"ק דברכות אמתניתין א' ויכולו השמים כו' מה כתיב בתריה אלה תולדות השמים והארץ בהבראם ביום עשות כו' וכי מה ענין זה אצל זה אלא יום נכנס ויום יוצא שבת נכנס ושבת יוצא כו' שנה נכנס שנה יוצאה וכתיב בתריה אלה תולדות השמים והארץ בהבראם פי' אעפ\"כ הם חזקים, כמו אלה תולדות השמים והארץ בהבראם, ביום בראם וביום עשות, והובא במד\"ר פ' בראשית ס\"פ בראשית ע\"ש בידי משה, וזהו מי ברא אלה פי' שיהיה בחי' אלה תולדות השמים והארץ בהבראם שיהיו גם תמיד כמו ביום הבראם, וזהו ברא אלה שיהי' אלה תולדות כו' בהבראם, וזהו הפליאה מי",[["177","*","<b>קיצור</b>: קיצור. . . — כמובן מקום כ\"ז הוא בד\"ה סמכוני (פה, א) [כ\"ה בבוך 1095]."]]],[3000730101,"ברא אלה, שבחי' בריאת אלה זה נמשך מבחי' מי, היינו מי שאמר והיה העולם, וה\"ע מי יתן טהור מטמא כו', וגם מזה נראה בחוש שהוא מחיה אותם תמיד שיהיו חזקים כמו ביום הבראם. והנה זה שלא ישתנו ויוחלש כחן כלל אף ברוב ימים ושנים א\"א בשום אופן שיהי' מצד כח המלובש בהן שהוא בעל גבול, וכל בעל גבול בהכרח שיוחלש מעט ברוב ימים וא\"כ זה שאינם משתנים כלל הוא ע\"י בהבראם ביום עשות שהוא ית' נותן בהם הכח שיהיו הכל כמו ביום הבראם וביום עשות א\"כ אנו רואים שזה נמשך מכח הבלתי בעל גבול והוא הבורא ית', שנותן בהם כח זה שאע\"פ שהם מצד עצמם בעלי גבול, עכ\"ז לא יהי' בהם העדר והפסק ושום שינוי וחלישות עד עת רצונו ית' בקיומם. וזהו מרוב אונים ואמיץ כח איש לא נעדר, היינו מרוב אונים ואמיץ כח שלו ית' הבלתי בעל גבול, עי\"ז דוקא נמשך בחינה זו אשר איש לא נעדר. וכן ת\"י חד מסדריה לא מתעכב, שאין עיכוב לההשפעה ולא הפסק כו'.\n<b>ושאר</b> המפרשים פירשו באיש לא נעדר, דקאי על השמות מה שלכולם בשם יקרא והוא דוחק. נמצא ד' אאזמו\"ר נ\"ע בפי' הפסוק שאו מרום כו' הם ד' הרמב\"ם בעיון שלישי הנ\"ל רק שבאו בביאור יותר דהמכוון ממה שאנו רואים שאין שום הפסק ועיכוב כלל בההשפעה של אישי השמים ולא שום שינוי בהם וזה אי אפשר כלל מצד כח המוגבל המלובש בהם מצד עצמו, שכל כח בעל גבול נופל תחת השינוי וההפסד וההפסק כנראה בחוש. ולכן מזה שאיש לא נעדר באישי השמים, וכן בארץ, אנו רואים מי ברא אלה, שהוא רוב אונים ואמיץ כח בלתי בעל גבול כו'. וגם עוד זאת דעיקר המכוון מעיון שלישי שהביא הרמב\"ם להכריח שיש מחוייב המציאות, בלתי הוה ולא נפסד, הוא דוקא יותר מהאישים ההוים ונפסדים שהם חי ומדבר, כיון שכל האישים הם הווים ונפסדים, א\"כ היה אפשר שיפסד לגמרי איזו מינים מן החי ומדבר, שהרי הם אפשרי ההפסד, והאפשר במין אי אפשר שלא יצא לפועל, בזמן בלתי בעל גבול, א\"כ הי' ראוי שכל החי מדבר יפסדו, וכ\"ש עכ\"פ איזה מינים מהם, כמו איזה מין בהמות ועופות, וממה שלא נפסד שום מין, ע\"כ נראה שיש מכריח הדברים ההוים ונפסדים שלא יעדרו, וזהו המחוייב המציאות. וכמ\"כ נראה ממה שהשמים קיימים באיש, והם בעלי גבול, ע\"כ יש מכריח קיומם באיש. ועפ\"ז נרוויח ג\"כ דחייה למ\"ש הרש\"ט בשם י\"א שהכח להתמיד המציאות כו' כמ\"ש לקמן [בד\"ה<sup data-n=\"178\">*</sup> לשון רס\"ג] סוף סי' א', שאף שבלאו הכי זהו מוקצה מהדעת ונגד המושכל ראשון עכ\"ז הרי לפי עיון שלישי הזה דהרמב\"ם ע\"כ צ\"ל כח המכריח קיום כל המינים ההוים ונפסדים שלא יפסדו, ולא להתמיד מציאות עצמו לבד, כ\"א להתמיד כל הנמצאים המורכבים מהפכיים, שלא יפסדו ויתקיימו זה במין וזה באיש, והכרח וקיום זה א\"א להיות כ\"א ממחוייב המציאות.\n<b>קיצור.</b> נמצא זהו פי' הפסוק שאו מרום עיניכם ותראו באישי השמים שפע כח הא\"ס, במה שאין עיכוב והפסק בהשפעם ואינם משתנים ולא מתחלשים שזה א\"א מצד כוחם המוגבל כ\"א ע\"י ששופע בהם כח וחיות מא\"ס ב\"ה. וכמ\"כ נראה מצד האישים ההוים ונפסדים צומח חי מדבר, אשר איש לא נעדר כנ\"ל, שאין שום מין כלה ונפסד. וגם מכ\"ז נראה שהוא מהוה ומחייה אותם תמיד בכל יום שלכן אין באישי השמים שום שינוי, וכן באישי הארץ שלא יופסדו.\n<b>ולכאורה</b><sup data-n=\"179\">*</sup> מופת זה איננו מופת על חידוש העולם אלא רק על מציאות הש\"י. וא\"כ לדברי הסוברים שיש מופת על החידוש א\"צ למופת זה, אך באמת אעפ\"כ יש ריווח ממופת זה ג\"כ לתשובת המינים הנזכר בסש\"ב ח\"ב פ\"ב הטועים בדמיונם הכוזב לומר שאחר שהש\"י ברא את העולם שוב אין העולם צריך לו, והוא מה",[["178","*","[בד\"ה לשון רס\"ג]: בגוכתי\"ק ליתא. ובמקומו נכתב: לקמן. וכנראה שזה תיקון המו\"ל הראשון. בגוף כתי\"ק 1179 נמצא זה בתחלת הספר."],["179","*","<b>ולכאורה</b>: ולכאורה. . פרק חמישי (ס\"ג, א) — כ\"ז אינו בכת\"י. [בוך 2106]. [בגוכתי\"ק 1179 נמצא זה בהוספה לדף פה, א]."]]],[3000730140,"שהזכיר במ\"נ ח\"א ס\"פ ס\"ט בשם המדברים שהפעול אחר שנפעל א\"צ להפועל, והרמב\"ם שם דחה דבריהם בשתי ידים, וכן בסש\"ב שם, ביתר שאת. וגם אמנם מופת זה הוא דחייה לדבריהם, כי ממה שאיש לא נעדר, ע\"כ שהוא ית' מעמידם ומהוה ומחיה אותם תמיד.\n<b>(קיצור.</b> ואף לפי האמת שיש מופת על חידוש העולם מ\"מ יש תועלת ממופת זה לדחות המינים הנזכר במ\"נ ח\"א ס\"פ ס\"ט ובסש\"ב ח\"ב פ\"ט).\nג<sup data-n=\"180\">*</sup> <b>ונלע\"ד</b> שמופת זה שכ' אאזמו\"ר כאן בנוי ע\"פ שאו מרום עיניכם כו' מרוב אונים ואמיץ כח איש לא נעדר. זהו עולה בקנה אחד עם המופת שכתב הרמב\"ם במ\"נ ח\"ב פרק ראשון עיון שלישי והביאו ג\"כ בעל העקרים במאמר ב' פרק חמישי.",[["180","*","<b>ג</b>: ג — צ\"ע פי' ציון זה."]]],[3000730060,"<b>במדרש</b> רבה פ' בראשית פ\"ח זכר ונקבה בראו<sup data-n=\"181\">*</sup>, ר' יהושע בר נחמיה בשם ר' חנינא בר יצחק ורבנן בשם ר\"א<sup data-n=\"182\">*</sup> אמרי, ברא בו ארבע בריות מלמעלה וארבעה מלמטן. אוכל ושותה כבהמה, פרה ורבה כבהמה, ומטיל גללים כבהמה, ומת כבהמה. מלמעלן, עומד כמלאכי השרת, מדבר כמלה\"ש, יש בו דעה<sup data-n=\"183\">*</sup> כמלה\"ש, ורואה כמלה\"ש כו' ע\"ש. נלע\"ד שמזה אנו לומדים מופת על השארת הנפש. דהנה הרמב\"ם במ\"נ ח\"ב פ\"א עיון שני הביא בשם הפלסופים שכאשר אנו רואים דבר מורכב משני דברים ואח\"כ אנו מוצאים דבר אחד משני הדברים הנ\"ל בפני עצמו ג\"כ, אזי ודאי גם הדבר השני נמצא בפ\"ע, כמשל יש דבר מורכב מחומץ ודבש, וכשאנו יודעים שיש ג\"כ דבש בפני עצמו, הרי אין ההרכבה ההיא של המשקה העשויה מחומץ ודבש מחוייבת, שהרי נמצא ג\"כ דבש בלא חומץ, א\"כ ע\"כ ימצא ג\"כ חומץ בלא דבש, אף אם לא ראינו חומץ עדיין בלי דבש נכריח שהוא כן שיש חומץ בפ\"ע ממה שאנו רואים שיש דבש בפני עצמו כו' ע\"ש. כמ\"כ בהאדם אנו רואים ההרכבה מחי וממדבר, שהרי יש בו ד' דברים כמו בבהמה ממש אלא שנוסף בו עוד ד' דברים שאינן כלל בבהמה, ה\"ז הרכבה מבחי' חי ומבחי' מדבר, ובחי' החי שבו זהו ממש כמו החיות שבבהמה אף שהוא בדקות יותר מ\"מ הרי שוה לה ממש בארבעה בריות הנ\"ל אוכל ושותה פרה ורבה ומטיל גללים כו', אלא יש בו עוד דיעה וכח הדיבור כו', וכיון שאנו מוצאין ד' דברים שבו מבחי' חי אנו מוצאין זה בפני עצמן בבהמה, מזה אנו שופטים שכמ\"כ ד' דברים שבו מלמעלן דיעה ודבור ימצאו ג\"כ בפני עצמן, היינו בזולת בחי' חי, ור\"ל כי בחי' חי היינו מה שהגוף גשמי בשר ודם יקבל חיות, וע\"כ אמר ד' דברים הנ\"ל דיעה ודיבור כו' נמצאים ג\"כ בלי גוף גשמי כ\"א בשכליים נבדלים, זה מוכרח לפי הנחה ומופת הנ\"ל. ועתה כיון בנשמת האדם יש בחי' מהשכליים הנבדלים מחומר היינו ארבעה דברים הנ\"ל, מזה נכריח השארת הנפש שיש בה ד' בחי' הנ\"ל אף אם נפש הבהמה אין בה השארת מ\"מ נפש האדם ודאי נשארת. ואף שאנו מאמינים בזה בלי שום חקירה ושכל אנושי ע\"פ התורה שנאמר והיתה נפש אדוני צרורה בצרור החיים וכתיב ונתתי לך מהלכים כו', מ\"מ אין הפסד לסמוך זה ג\"כ במופת, אף שחכמי המחקר הביאו ע\"ז מופתים יותר, מ\"מ מופת זה יש לסומכו לדברי המדרש רבה הנ\"ל. והנה האפודי והרש\"ט במ\"נ שם הקשו כי אנחנו נראה דברים מורכבים ונמצא אחד מהם בפני עצמן והשני לא ימצא, שהאדם הוא מורכב מחיות ודבור והחיות נמצא בלתי דבור והדבור לא נמצא בלתי החיות עכ\"ד. ולפמ\"ש בשם",[["181","*","<b>בראו</b>: כ\"ה בגוכתי\"ק 1152, אבל בב\"ר: בראם."],["182","*","<b>בשם ר\"א</b>: בב\"ר נוסף: אמרי, אבל בגוכתי\"ק ליתא."],["183","*","<b>דעה</b>: כ\"ה בגוכתי\"ק אבל בב\"ר: דעת."]]],[3000730102,"המד\"ר אדרבה מזה ראיה לעיון הנ\"ל, כי הדבור שיש באדם זהו שנמצא בו מלמעלן ר\"ל שבזה הוא דומה למלאכי השרת, ועז\"נ בצלם אלקים עשה את האדם, א\"כ הרי נמצא הדבור בלא החיות ר\"ל בלי החיות גופני אלא בשכליים הנבדלים, ומה שהקשו מעצם ומקרה כבר תירץ הרש\"ט שם כי המקרה אינו קצה כי לא ימצא מבלי נושא, ואינן נמצאים בעצמותם ולכן לא יתחייב כשימצא העצם בלי המקרה שימצא המקרה בלי העצם."],[3000730061,"<b>עדות</b> ה' נאמנה, ופי' המגיד משרים וז\"ל לפי שאין עדות אמיתית אלא ע\"י ראיה ולא ע\"י שמיעה ואמונת התורה אינה אלא ע\"י קבלה, אמר דע שאעפ\"כ נאמנת, ותדע שהרי היא מחכימת פתי כו' עכ\"ל, ולהבין הטעם לזה בגודל אמונת קבלת התורה, הנה נלע\"ד לפרש חלקי ה' אמרה נפשי כי כ\"א מישראל יש לו חלק בתורת הוי' כפי שרש נשמתו כידוע, ועם היות כי למעמיקים בתורת ה' ברזין דאורייתא א\"צ לשית טעם לזה כי האמת עד לעצמו וטועמיה חיים זכו, חיים נצחיים, אעפ\"כ תורת ה' תמימה, וגם בנגלה ודאי הדבר נכון וקיים וישר ונאמן מאד בקבלת התורה והוא זה, דע כי העדות האמיתי שכתב הרב\"י שאינו אלא ע\"י ראיה והוא לקצת פוסקים ובדיני נפשות דוקא אבל בדיני ממונות מתקיים העדות בידיעה בלא ראיה כדאיתא בשבועות דל\"ד ולקצת פוסקים גם בדיני נפשות כן, אך ורק כל שהידיעה ברורה בלי שום ספק בעולם וכמבואר שם בחיה\"ר ותוס'. והנה עיקר ההפרש בין ידיעה בלא ראיה לראיה הוא שהידיעה היא ידיעת המציאות ולא השגת המהות כמו עד\"מ האדם רואה עצמו חי ומזה ידוע שיש בו נפש החיוני' המחי' אותו ומ\"מ אינו מכיר מהות הנפש איך ומה הוא, וזהו הנק' ידיעת המציאות. אמנם השגת המהות הוא כשמשיג מהות הנפש מה הוא וכמו בג\"ע שאז משיג נשמתו, וכן הצדיקים הגדולים זוכים לזה בעוה\"ז שמתגלה לו שרש נשמתו כמ\"ש בספר שע\"ק להרח\"ו ז\"ל. ועד\"ז יובן בהפרש בין עדות שע\"י ראיה שהעדים ראו מהות המעשה שמעידים עליו, או כשמעידין ע\"י ידיעה שאע\"פ שהדבר מוכרח שודאי הי' המעשה שמעידים עליו כגון ע\"ד המבואר בגמ' שם ובטור חו\"מ סי' צ' גבי נחבל מ\"מ לא ראו מהות המעשה. וזהו הנק' ידיעת המציאות ולא השגת המהות ובודאי שהעדות שע\"י השגת המהות חזקה ונאמנת יותר מן העדות שע\"י ידיעת המציאות אע\"פ שהיא נאמנת ג\"כ מאחר דמיירי באופן הידיעה היא ברורה מ\"מ ראית המהות עדיפא טובא מינה כמובן ומורגש לכל חכם לב, ובהא א\"ש טעם להפוסקים האומרים דבד\"נ אין העדות מתקיימת אלא בראיה וידיעה ולא בידיעה בלא ראיה להיות כי ד\"נ הוא דבר גדול עד מאד בהריגת גוף אדם מישראל שבו מלובש נה\"א חלק אלוה ממעל אין ראוי להפריד ביניהם אלא ע\"י עדות היותר נאמנת והוא העדות שע\"י ראיה שהוא השגת המהות ממש, עין בעין יראו.\nב <b>ועתה</b> י\"ל בענין עדות קבלת התורה שבודאי צ\"ל ג\"כ נאמנה בראיה וידיעה ולא בידיעה לבד שהרי קבלה זו הו\"ע גדול מאד מאד יותר מענין דיני נפשות לאין ערוך ביניהם, וכידוע שאין ערוך לנה\"א לגבי יותר הכל ב\"ה כטפה מאוקיינס וכערך בע\"ג לגבי בלתי בע\"ג, א\"כ לפ\"ע ענין שמאמינים עליו נ' צ\"ל העדות נאמנה יותר. ועוד שהרי בכלל עדות קבלת התורה הוא דין ארבע מיתות התורה שנמסרו לב\"ד. וכן דין מצות קדה\"ש שמחוייב כ\"א מישראל למסור נפשו אם רוצים להעבירו על דת בא' מן ג' המצות שהן ג\"ע ע\"ז ושפ\"ד כדאיתא ביו\"ד סי'"],[3000730103,"קנ\"ז. א\"כ כיון שבזה תלוי כמה וכמה דיני נפשות פשיטא ופשיטא שקבלת עדות התורה צ\"ל ג\"כ באופן היותר מעולה ואע\"פ שאפשר לדחות טעם זה לדברי האומרים שאין עדות דיני גיטין וקדושין צריכי' דרישה וחקירה כמו ד\"נ אע\"פ שאח\"כ יבוא לד\"נ ממש. מ\"מ כיון שעכשיו אין כאן דיני נפשות אין זה כדיני נפשות ממש כמ\"ש הב\"י בבד\"ה בחו\"מ סי' ל' וכ\"כ שארי פוסקים. ולפ\"ז י\"ל דה\"נ קבלת התורה ל\"ד לד\"נ אע\"פ שבזה תלוי ד\"נ, מ\"מ לא דמי דהתם שאני שהענין מצד עצמו אינו גדול כד\"נ ואי משום שיוכל להביא לד\"נ אין להחמיר בו כ\"כ דהיינו רק גורם לדבר דד\"נ ואינו כהדבר עצמו, דכל גרמא אין בו חומר כמו עצמות הדבר. משא\"כ קבלת התורה הוא אבוהון דכל המצות והחוקים והמשפטים וענין גדול יותר ויותר ממהות מצוה א' דדיני נפשות א\"כ האמנתו בודאי צריך עדות יותר ממה שצריכים בדיני מצוה א' ממנו שהוא ענף א' לבד מדיני כללות התורה כולה. אך באמת ודאי עדות ה' נאמנה כי היא בידיעה ובראיה ממש.\nג <b>והענין</b> כמ\"ש הרמב\"ם פ\"ח מה' יסוה\"ת ה\"א, וז\"ל, משה רבינו לא האמינו בו ישראל מפני האותות שעשה כו' ובמה האמינו בו במעמד ה\"ס שעינינו ראו ולא זר ואזניו שמעו ולא אחר האש והקולות והלפידים והוא נגש אל הערפל והקול אליו ואנו שומעים משה משה לך אמור להם כך וכך וכה\"א פב\"ב דבר ה' עמכם כו' נמצאו כו' כל ישראל עדים לו כשני עדים שראו דבר אחד ביחד כו' ע\"ש באריכות. וכיון שכן עדותן היא ע\"פ ראיה וגם הראיה זו היא השגת מהות הדבר שהשיגו ממש מהות אלקות שכולם הגיעו לנבואה מאחר שנגלה עליהם ה' פב\"פ אין לך נבואה גדולה מזו ואינה ידיעת המציאות לבד, כי זהו<sup data-n=\"185\">*</sup> ההפרש בין חכם לנביא שהחכם יודע מציאות הענינים האלקית ולא המהות ממש ולכן יכול להשיג בחכמה תעלומות חכמה בעולמות עליונים מאד משא\"כ הנביא דשורש הנבואה הוא מנו\"ה לבד, והיינו לפי שהוא השגת המהות וא\"א להשיג יותר מספי' נו\"ה שהן כלי ההשפעה ומ\"מ בהן מלובש חכמתו ובינתו ודעתו של א\"ס ב\"ה, והנביא משיג מהותן ממש שהן אלקות מבחי' אצילות שעד שם שורש הנבואה כמ\"ש הרח\"ו בשער היחודים ע\"ש. וכיון שכולם זכו אז לנבואה שהוא השגת מהות האלקות, א\"כ עדותן הוא כעדים שראו דבר אחד בעיניהם ממש וידעו היטיב שכן הוא כפי מה שאומרים.\nד <b>אלא</b> שעדיין יש לחקור דמ\"מ האיך הגיע קבלת התורה עלינו, דלכאורה הוא עד מפי עד. אך הענין דאין זה כלל עד מפי עד אלא עדות מפי ב\"ד שראו כל קהל ישראל שראו זו בעיניהם הם בעצמם נעשים דיינים לקבל עדותן דקיי\"ל ג' שראו עדותן ביום נעשים דיינים לדון ע\"פ ראייתם כדאיתא ר\"פ ראוהו ב\"ד ובמס' ב\"ק דע\"ב, אלא דמ\"מ זה תלוי במחלוקת ר\"ט ורע\"ק, אם בד\"נ נמי דינא הכי או בד\"מ לבד כדאיתא בגמ' שם, ודעת הרמב\"ם דהלכה כר\"ט דנעשים דיינים כמ\"ש בכ\"מ ספ\"ה מה' עדות מיהו דעת התוס' דהלכה כר\"ע. ואפי' לשיטתם נמי ניחא דהא עכ\"פ העידו לבני בניהם שלא היו במעמד הר סיני ולא ראו א\"כ הם עצמם שלא ראו הם הדיינים ואבותיהם שראו הן מעידין בפניהם והיינו באמרם בכל יום שמע ישראל כו' הוי' אחד וכל הענין וקן בקיומם כל המצות שכולם הם עדות למעמד הר סיני. וא\"ת הרי האבות קרובים לבניהם ופסולי עדות נינהו, הא לא קשיא שאע\"פ שאב א' קרוב לבנו הנה כל ששים רבוא הנשארים כשרים לו וכן לחבירו, ונמצא כל ב\"ד וב\"ד מישראל שמעו עדותן על קבלת התורה מעדות כשרים וכה\"ג נעתק הענין מדור לדור ואין לך עדות גדול מזה, וכמבואר ג\"כ בהקדמת הרב המחבר ספר החינוך יעוי\"ש תחלת ההקדמה. ונמצא ששפיר אמר הכתוב עדות ה' נאמנה שהרי העדים",[["185","*","<b>פב\"פ</b>: כי זהו — ראה אגה\"ק סי\"ט."]]],[3000730141,"ראו הדבר ממש, לא בידיעה לבד וששים רבוא עדים היו לבד מנשים וטף וזקנים וכולם העידו לפני ב\"ד הגדול יותר מששים רבוא, וכן נעתק הענין מדור לדור עד שהגיע עדינו.\nה <b>והשתא</b> א\"ש טובא מאי דמשמע בקרא דמעמד הר סיני לבד הוא הראיה לנבואת משה שהיא אמת שאין בה שום דופי כמ\"ש הרמב\"ם שם מדכתיב הנה אנכי בא אליך בעב הענן בעבור ישמע העם בדברי עמך וגם בך יאמינו לעולם כו'. דלכאורה קשיא טובא דהא גם בשאר נביאים האמינו ע\"י אותות ומופתים לבד אע\"פ שלא ראו להם שישיגו בעצמם ג\"כ מהות האלקות. מיהו הרמב\"ם תירץ זה ספ\"ז באמרו ז\"ל ואפשר שיעשה אות ומופת ואינו נביא וזה האות שלו דברים בגו ואעפ\"כ מצוה לשמוע לו כו' כמו שנצטוינו לחתוך את הדין על פי שני עדים כשרים כו' ע\"ש והציוי ע\"ז היגיענו ע\"י מרע\"ה. וא\"כ לפ\"ז א\"ש דנבואת משה לא היתה אפשר שנאמין בה עי\"ז לבד כיון שאפשר שעשה כו' ומי מעיד לנו שנביא הוא, משא\"כ עכשיו בשאר הנביאים ציוי מרע\"ה מעיד לנו ע\"ש. מיהו זה דוחק דהא אשכחן בקרא דכמה אותות יש שא\"א שיהיו נעשים אלא לנביא אמת שהשי\"ת הוא עושה לו המופת וכמ\"ש החרטומים לפרעה במכת כינים אצבע אלקים היא וכה\"ג גרסינין בגמ' סנהדרין ס\"פ הנחנקין ד\"צ ע\"א ח\"ו שהקב\"ה מעמיד חמה לעוברי רצונו כו'. הנה מבואר שנס דהעמדת חמה באמצע רקיע א\"א שיהיה נעשה בלט ובכישוף וא\"כ יכולה הנבואה להתקיים ע\"י אותות אלו. אלא עיקר ההפרש ביניהם הוא כמש\"ל סי' א' ההפרש בין ידיעת המציאות להשגת המהות שהמאמין בנביא ע\"י אותות ומופתים עם היות המופת אמיתי שא\"א שיהיה נעשה אלא ע\"י השי\"ת, מ\"מ הנה אין ענין אמונה זו רק ידיעת המציאות שיודע עי\"ז מציאות השי\"ת הבבע\"ג ובב\"ת שהוא הכל יכול לעשות אות ומופת זה, וכיון שנעשה זה ע\"י נביא זה ה\"ז ידיעה ברורה שהשי\"ת עשה אות זה בגילוי שישמעו לו בדבריו כמ\"ש אליו תשמעון כו', משא\"כ ע\"י מעמד הר סיני היה להם ראיה והשגת המהות האלקות ואיך שמגיע מהשי\"ת הנבואה למשה, והוא עדיפא טובא מהשגת המציאות כידוע דמה\"ט אין דומה שמיעה לראיה שהראיה מקרבת הדבר להנפש יותר מהשמיעה לפי שהראיה הוא השגת המהות ממש, משא\"כ בשמיעה שהוא ידיעת והכרת המציאות. לכן ע\"י מעמד ה\"ס נתקרב יותר אמונת השי\"ת בעצמות ופנימית נפשותם וזהו וגם בך יאמינו לעולם.\nו <b>מיהו</b> אע\"פ דהשגת המהות עדיפא מידיעת המציאות, היינו משום שמקרבת הענין יותר למהות הנפש. אבל מ\"מ גם ע\"י ידיעת המציאות מתברר הענין שהוא נמצא וזה\"ע כל האותות ומופתים שבהם וע\"י מתברר אמיתת מציאות השי\"ת (אע\"פ שיוכל להתברר גם בלי מופת כדכתיב מבשרי אחזה אלוה וכדלקמן אי\"ה) והשגחתו בתחתונים ומציאת הנבואה וכמ\"ש הרמב\"ן בספר המצות בל\"ת שמנה הוא סי' א' וז\"ל יציאת מצרים שנעשה באותות מחודשים משנים התולדות מורים על אלוה קדמון חפץ ויכול ומחדש. שענין יציאת מצרים ליודעיו משתק כל כופר בחדוש ומקיים האמונה בידיעת האלוה והשגחתו ויכלתו בפרטים ובכללים כולם עכ\"ל, וכ\"כ בטור או\"ח סי' רע\"א דמה\"ט אנו אומרים זכר ליצי\"מ בקידוש של שבת שהשבת מורה ג\"כ על החדוש ע\"ש. ובאור הענין הוא דהנה נתבאר אצלינו במ\"א שיש ב' בחי', בחי' השתלשלות מעילה לעילה ובחי' המשכה שלא כסדר ההשתלשלות, וענין ההשתל' מעילה לעילה הנה העלול הוא מעין העילה ויש לו ערך לעילתו, כמו עד\"מ ודוגמא שהשגתו הוא חלק עשירית מהשגת העילה או עשירית מיני עשירית. וכה\"ג"],[3000730167,"השתל' זו הוא בעולמות העליונים כי מפני אריה שבמרכבה העליונה מקבלים שאר מלאכים העלולים ממנו מעילה לעילה עד שברבות ההשתלשלות ורבות הירידה מעילה לעילה נמשך מזה המשכה מצומצמת כ\"כ עד שנמשך משם גם חיות הנפש האריה הגשמי, וכן מפני שור שבמרכבה לנפש השור הגשמי. ובחי' השתלשלות זו הוא מה שהשי\"ת מוריד וממשיך ומשפיע חיות לנמצאים מעילה לעילה. אך כ\"ז הוא להיות התהוות נמצאים רוחניים העלולים משרשן ומקורן שכבר נבראו והן פני אריה ופני שור כו'. אבל להיות התהות הגשמית מהרוחיות א\"א בשום פנים להתהוות ע\"י עו\"ע שאפילו אלף אלפים ורבוא רבבות צמצומים ומיני השתלשלות וירידת החיות מעילה לעילה לא יועילו להיות התהוות גוף השור עד\"מ מפני שור הנ\"ל או התהוות גשם עב כעפר. כי התהוות הגשמי' מרוחני' הוא כמו התהוות מלא דבר אל דבר באין שום חילוק ממש, כיון שאין ערוך כלל מהות הגשמי' לרוחני' שיתכן לומר שההתהוות הוא מדבר אל דבר אלא מלא דבר ממש, לפיכך א\"א להיות התהוות זו כ\"א ע\"י כח הא\"ס ב\"ה עצמו הבבע\"ג ובב\"ת שהוא הכל יכול להוות דבר מאין ואפס ממש. וכמו שהאריך בזה כאאזמו\"ר נ\"ע באגה\"ק המתחיל איהו וחיוהי כו' ע\"ש.\nז <b>וכיון</b> שכן גם האות והנס המשנה התולדה הגשמי כמו הניסים דיצ\"מ וקי\"ס השליו והמן והבאר וענני כבוד וכה\"ג שכולם הם התפעלות ענין גשמי שלא כפי הטבע הרי בהכרח שזהו ע\"י כח הא\"ס ב\"ה הבבע\"ג ובב\"ת שהוא לבדו יכול לברוא יש מאין לכך יוכל להפכו כרצונו, מה שאין כן בכח שום מלאך ושרף ח\"ו, שהרי מהות הגשמי אינו מערך הרוחני' ואין להמלאך מצד עצמו שום כח לפעול בענינים גשמים כנ\"ל אלא ע\"י רצון הא\"ס ב\"ה הבבע\"ג ובב\"ת יכול לברוא יש מאין ולהפכם ולהטותם לכל אשר יחפוץ ואזי גם המלאך יוכל לעשות דבר גשמי בשליחותו של מקום ב\"ה דוקא, והוא ית' העושה זאת, דהיינו רצון הבבע\"ג לא המלאך בלבד, וכמ\"ש כל אשר חפץ עשה כו' כמ\"ש במ\"א. והנה כשיתבונן המשכיל בריבוי הניסים והנפלאות שעשה עמנו אלקינו ביצ\"מ ונס המן התמיד ארבעים שנה הנה בכל יום מארבעים שנה הנ\"ל הראה לנו בגילוי רב הארתו ית' הבבע\"ג שזולתו א\"א ירידה והתהוות זו כנ\"ל, וכן בשארי ניסים כמו שבא בספרי הנביאים אח\"כ. ולזאת יקבע בלבו ויצייר כאלו הוא רואה ממש גדולתו ית' הבבע\"ג וכמ\"ש שויתי ה' לנגדי תמיד. וירא ויפחד ממנו ויבוש ממנו בהיותו ית' מבין ומביט ומאזין לכל מחשבותיו ודיבוריו ומעשיו וכל צעדיו יספור כו'. וגם יתאוה ויכסוף כוסף רב לידע את גדולתו ית' מה שאפשר לידע, וכ\"כ בשערי התשובה לרבינו יונה שמעלת התבונן בגדולתו ית' וזכרון חסדיו ית' נמסרו לנו במ\"ע.\nח <b>וכן</b> מאשר בכל דור ודור גם אחר הנביאים השי\"ת מראה אותות ומופתים בישראל כמו מתנאים ואמוראים כמבואר בגמ' ומדרשות, וגם אחריהם כידוע מהרוקח ור\"י חסיד וסייעתם שהיו אנשי מופת מאד, וגם אח\"כ מהאריז\"ל שעליו אמרו פלאי פלאות מופתים שהיה השי\"ת מראה על ידו, וכן בדורו היה הרב ב\"י ז\"ל שהיה לו מלאך מגיד השלוח לו, ואחריהם בדור שלפנינו הבעש\"ט ז\"ל אשר כמוהו לא היה מימות הראשונים פלאי פלאות ניסים היוצאים מהטבע היו נראים על ידו כאשר שמעתי מאאזמו\"ר נ\"ע שהוא ותלמידו הה\"מ נ\"ע היו רואים מסוף העולם ועד סופו ממש בעין ראיה והיו אומרים מה שהיו רואים כאשר היה נראה בעליל לתלמידיהם, והיינו ע\"י שהיה גלוי לפניהם אור שנברא ביום ראשון שהשי\"ת גנזו בתורה. הנה כל אלה המופתים האמיתים מגלים גילוי א\"ס ב\"ה הבבע\"ג, גם מזקיני נ\"ע שמענו עתידות קולע אל השערה."],[3000730062,"<b>במ\"נ</b> ח\"א פ\"א בענין צלם תמונת הדבר ותארו כו', וקשה איך יפרש מ\"ש בברכת חתנים בצלם דמות תבניתו והרי כ' בפ\"ג דפי' תבנית תאר, מיהו הרד\"א דף קט\"ו ע\"א תיקן זה דפי' בצלם דמות תבניתו שב אל האדם ור\"ל דמות תבניתו שהוא צורת גופו צר אותו בצלמו שהוא צורת הנפש, וכפי פשוטו נ' דדמות תבניתו זהו ענין כדמותנו, וכ\"מ בזח\"ג פנחס דרל\"ט רע\"א. ובשט\"מ כתובות דף ח' ב' הריטב\"א ע\"ד מ\"ש הרד\"א וכ\"כ שם ב' הרדב\"ז וע' בספר הפלאה, ובת\"א פ' בראשית פי' תבניתו הוא עלמא דאתגליא, וע' עה\"ק ח\"ג פכ\"ה שהשיג על המ\"נ. והענין דכתיב כמראה אדם כו' והיינו ע\"ס חכמה מוחא וכו', חסד דרועא ימינא, ועיין מזה בד\"ה צאינה וראינה בפי' שיעור קומה מהו ענין ראש למעלה כו', ובד\"ה אני דפ' ציצית בפי' הקב\"ה מנענע בראשו, ובד\"ה אני ישנה גבי רעיתי וגבי תמתי וכמ\"כ ראיה עיני ה' כי הנה ההפרש בין ראיה לשמיעה ע\"ד נביא וחכם שהוא השגת המהות וידיעות המציאות, וזהו היוצר עין הלא יביט, ועיין בשל\"ה דף י\"א שעיקר ראש ויד וכו' זהו למעלה בע\"ס אלא שלמטה נשתלשל להיות בחי' זו גם בנפש וכן אף בגוף דוגמת ציון וסימן כמו שעד\"ז המצות הם ציון וסימן לע\"ס כמ\"ש בת\"א בד\"ה רני ושמחי, ודוגמת ציור העולם במפה, ע\"כ א\"ש בצלמנו כפשוטו. אמנם אור א\"ס עצמו לאו מכל אלין מדות איהו כלל, כי לא אדם הוא, וגם בע\"ס בחי' אדם הרי אין לו גוף ולא דמות הגוף כ\"א הכל ענינים שכליים חכים ולא בחכ' ידיעא וכו' רק שמ\"מ הג' שכליים וז' מדות הם ברוחניות בחי' אדם חב\"ד בחי' ראש רצון החופה על חב\"ד נמשל לגלגלתא, וע\"כ גשמיות גוף האדם שהוא בגשמיות ציון וסימן לבחי' הרוחניים ההמה, שייך לומר בו כדמותנו, ועל הנשמה שייך לומר בצלמנו. וזהו וספרתם לכם שתמשיכו ע\"ס העליוני' שיהי' מאירים בכם ע\"י שתהיו בבחי' בצלמנו:\n<b>בישעי'</b> מ\"ד י\"ג כתבנית איש כתפארת אדם לשבת בית פי' בשל\"ה קס\"ז דקאי על תפארת דאצי' שהוא גלוי חכמה עילאה, א\"כ כתבנית איש היינו נמי כן. והמגיד פי' תפארת אדם קאי על מל' וכ\"מ ברבות בראשית פכ\"א דקאי על חוה כמ\"ש בת\"י ורש\"י בישעי' שם והרי נאמר כאן תבנית היינו דמות וצורה וזהו כדמותינו ע\"ד כל הנביאים נתנבאו בכה וזהו בצלם דמות תבניתו היא מל' יחו\"ת. ועיין מענין בצלמנו בת\"א מקץ בד\"ה רני ושמחי גבי ציון. וע\"ש בביאור ע\"פ כי עמך מק\"ח בענין הקב\"ה מניח תפילין, ובד\"ה משה ידבר כי על התומ\"צ נאמר נעשה אדם בצלמנו כדמותנו וכ\"כ עוד בד\"ה כי ביום הזה יכפר (השני) וע' סד\"ה כי תצא (הראשון) גבי ונתנו ה' אלקיך היינו תומ\"צ, ובביאור ע\"פ ואלה המשפטים אדם אדמה לעליון, היינו בצלמנו. וצ\"ע דאיתא ובך לית דמיון ודיוקנא מכל מה דלגאו ולבר וכדפי' בפרדס שע\"ד פ\"ו שעם היות שגם האורות שבהכלים הם בלי מהות עכ\"ז הם עד\"מ המים שמשתנים לפי גוון הכלי אע\"פ שאין השינוי קנוי בהם באמת אכן באוא\"ס שלמעלה מהאורות וכלים לית דמיון ודיוקנא כו', וזהו ואל מי תדמיוני כו', וצ\"ל אדמה לעליון לבחי' כתר א\"א, ועי' מענין בצלמנו סד\"ה ראשי המטות ובד\"ה אלה מסעי ובד\"ה כי תצא גבי וראית בשביה אשת יפת תאר, ובפ' תבא ד\"ה ענין ר\"ה ויוהכ\"פ."],[3000730063,"<b>פל\"ב</b> פי' הש\"ט דכוונתו שאין להכריח החדוש, והנה בח\"ה הביא ג\"כ ענין זה ששכל האדם יש לו גבול בשער היחוד פ\"י בד\"ה וממה שצריך שתדע כו' יעו\"ש, ואעפ\"כ ס\"ל להכריח החדוש במופת שם פ\"ה פ\"ו, ונלע\"ד דפרק זה הוא עזר גדול לדעת הכוזרי ורס\"ג מכריחי החדוש במופת, כי מופתיהם מופת אמיתי שא\"א שעברו עד עתה דורות בלי גבול ושנים שלשים פעמים בלי גבול וימים עשרה אלפים פעמים בלי גבול, שכ\"ז יש לבאר במופת שהוא נמנע שהרי מעתה ועד עתיד א\"א"],[3000730104,"שיצא לפועל אף פעם א' ימים בלי גבול, רק שהטענה שיש לנגד זה הוא דהא על כרחנו לכולנו יש מצוי ראשון שהוא ושנותיו לא יתמו א\"כ ע\"כ עבר דמות זמן בל\"ג א\"כ אמור כמ\"כ על העולם, אך ע\"ז תשובה גדולה מפרק זה דכיון שהשכל יש לו גבול א\"כ אינו משיג הבלי גבול זמן של שנותיו ית' עד\"מ למה שאינו בגדר הזמן שלנו כמו שאינו בגדר המקום לכל הדיעות, משא\"כ בענין הזמן שאצלינו ובענין מספר הדורות יש להשכל השגה גמורה א\"כ מה שיש מופת בשכל שלא עברו דורות בלי גבול זהו מופת גמור והטענה נגד זה משנים וימים של הבורא ית' אינו טענה כיון שהשכל מוגבל ואינו משיג זה כלל<sup data-n=\"186\">*</sup>.",[["186","*","<b>שהשכל</b>: בביכל (בא 36) בא אחרי פסקא זו ”אך בצלם — שער יא\" הנדפס ברשימות הצ\"צ על תהלים לט, ז."]]],[3000730064,"<b>בראשית</b><sup data-n=\"187\">*</sup> ג' ז' ותפקחנה עיני שניהם וידעו כי עירומים הם ויתפרו עלי תאנה ויעשו להם חגרת, הקשה הרמב\"ם במ\"נ ח\"א פ\"ב בשם חכם אחד כי איש מן האנשים מרה והפליג בעול, ולפיכך שינו ברייתו לטוב והושם כוכב בשמים וכו', ותירץ וכאשר היה על שלמות עניניו לא היה לו כח להשתמש במפורסמות כו' ולא השיג גנות הערוה כו' ע\"ש, וז\"ל הבחיי דף י\"ב ב' בפ' בראשית ועה\"ד נותן באוכליו רצון ובחירה כו' לשון רז\"ל שדעתו לחזור כו', וידעו כי ערומים כלומר המשיכו רצון ובחירה מעה\"ד כו' היה לו לאדה\"ר בה יצר ותאוה עכ\"ל, ודי\"ג ע\"ד כ' שהאדם היה מתחלה כולו שכלי כו' אבל אחר אכלו מן הפרי נתחדש בתאוה אחרת ונתלבש בה והוא תאות המשגל כו', ועד\"ז פי' בפ' ויצא מ\"ב ב' מ\"ש יעקב ואבואה אליה וז\"ל וידוע שאין הפרש אצל השכל בין אברי המשגל לשאר האיברים כגון הפנים והידים ומעולם אדם ואשתו לא עשו להם חגורות לכסות בשר ערוה עד שאכלו והמשיכו מכח עץ הדעת ונתלבשו בתאוות וכיון שכן היו האבות שכליים כמלאכי השרת אין לתמוה עליהם בדבר הזה כי כל כוונתם בהשתמשם בכלי הגוף כדי להמשך אחר השכל גם האמהות רחל ולאה כו' וזהו שאמרה לאה לרחל המעט קחתך כו' עכ\"ל, ועמ\"ש בלק\"ת בשה\"ש סד\"ה קול דודי בענין שהאבות הטעימן הקב\"ה מעין עוה\"ב, וא\"כ היינו בחי' אדה\"ר כמו שהיה קודם חטא עה\"ד שהיה מופשט מחוש התאוה כנ\"ל, וכמ\"ש בר\"ח שעה\"ק פט\"ו<sup data-n=\"188\">*</sup> בענין ומתחממין באישין קדישין ע\"ד איש ואשה אש יוד ואש הא כו', וזהו ולא יתבוששו ולכן אמר יעקב ואבואה אליה. ובפ' בראשית דף י\"ד ע\"ד פי' ותפקחנה עיני שניהם מנהג החומר והכח המשכיל כלומר הגוף והנפש שאחר שחטאו ירגישו חטאם ויכירו חסרונם איך חטאו ואיך נתלבשו בתאוות והוא שאמר ותפקחנה עיני שניהם וידעו, ואין ענין התפקחות זה בחכמה כו' רק בהעדר קנין כי נפקחו עיניהם והכירו העדר השגתם, כי תחלה היו שכליים ולא ידעו בתאוות כלל ועתה נתלבשו בהם כו' וידעו המשיכו כח התאוה מעה\"ד כו' כי ערומים הם ובכח התאוה שנתלבשו בהם גנו הענין מה שלא הי' מגנים אותו מתחלה כו', וזהו כפי' הרמב\"ם בתוספת באור, ועמ\"ש כן בד\"ה<sup data-n=\"189\">*</sup> ויהיו שניהם ערומים האדם ואשתו בשם הפנים יפות. ויש לבאר עוד עם מ\"ש בלק\"ת פ' חקת ע\"פ ויעש משה נחש נחושת איך ששרש הרע המחייהו הוא טוב, ועד\"ז ארז\"ל שטן ופנינה לש\"ש נתכוונו כו', ועד\"ז פי' בד\"ה כי תצא איך היצה\"ר שהוא אש זר דולק מ\"מ שרשו טוב מיסוד האש האלקי שבחיות ואופנים כו' רק שלמטה ע\"י שבה\"כ נעשה אש זר כו' לכן קודם חטא עה\"ד לא הי' היצה\"ר ע\"ד אש זר כ\"א כמו שהוא בשרשו בחיות ואופנים כו' שנאמר אופן א' בארץ מלרע כו' כמ\"ש במ\"א, ועמ\"ש בת\"א ס\"פ וישב בד\"ה מהלכים בין העומדים.\nב <b>בזח\"א</b> בראשית דכ\"ח ע\"ב פי' כי ערומים הם, דהוו בלא אורייתא ואתמר בהו ואת ערום ועריה כו', ויתפרו עלי תאנה אתכסו בכמה קליפין כו'",[["187","*","<b>בראשית</b>: בראשית. . — ראה ע\"פ זה ג\"כ באוה\"ת (מח, ב). [המאמר נמצא בגוכתי\"ק בוך א\"ב כמה דפים קודם מאמר זה]."],["188","*","<b>פט\"ו</b>: כ\"ה בגוכתי\"ק, ולכאורה צ\"ל: פט\"ז. וראה במ\"מ לכאן."],["189","*","<b>מגנים</b>: בד\"ה ויהיו — כנראה הכוונה להנדפס באוה\"ת."]]]]});
